def _coerce_bool_series(x, index=None) -> pd.Series:
    if isinstance(x, pd.Series):
        s = x.copy()
    else:
        if index is None:
            index = pd.RangeIndex(0)
        s = pd.Series(x, index=index)

    if s.dtype == bool:
        return s.fillna(False)

    return (
        s.astype(str)
         .str.strip()
         .str.lower()
         .isin(["true", "1", "yes", "y", "t"])
         .fillna(False)
    )

TOURNAMENT_FLAG_DEBUG = {}
NCAA_TOURNEY_TEXT_RE = (
    r"ncaa tournament|march madness|first four|first round|1st round|second round|2nd round|"
    r"round of 64|round of 32|sweet 16|sweet sixteen|elite 8|elite eight|"
    r"regional semifinal|regional semifinals|regional final|regional finals|"
    r"final four|national semifinal|national semifinals|national championship|championship game"
)
CONF_NAME_RE = (
    r"sec|acc|big ten|big 12|big east|pac-12|pac 12|aac|a-10|atlantic 10|"
    r"conference usa|c-usa|mvc|wcc|maac|mac|ivy|swac|meac|nec|summit|"
    r"horizon|sun belt|caa|america east|wac|wacc|asun|a-sun|patriot|southern"
)
CONF_TOURNEY_TEXT_RE = (
    r"conference tournament|conference championship|tournament quarterfinal|tournament quarterfinals|"
    r"tournament semifinal|tournament semifinals|tournament final|tournament finals|"
    r"quarterfinal|quarterfinals|semifinal|semifinals|semi-final|semi-finals|championship"
)


def _bad_team_name(x) -> bool:
    s = str(x).strip().lower()
    return s in {"", "nan", "none", "null", "tbd", "tba", "unknown"}


def _safe_team_text_col(df: pd.DataFrame, candidates: list, default="TBD") -> pd.Series:
    for c in candidates:
        if c in df.columns:
            out = df[c]
            if isinstance(out, pd.DataFrame):
                out = out.iloc[:, 0]
            return out.astype(str).fillna(default)
    return pd.Series([default] * len(df), index=df.index)


def _schedule_text_blob(df: pd.DataFrame, cols: list) -> pd.Series:
    parts = []
    for c in cols:
        if c in df.columns:
            parts.append(df[c].astype(str).fillna(""))
    if not parts:
        return pd.Series("", index=df.index, dtype=object)
    out = parts[0].copy()
    for p in parts[1:]:
        out = out + " " + p
    return out.str.strip().str.lower()


def _fallback_ncaa_tourney_flag(df: pd.DataFrame) -> pd.Series:
    detail_txt = _schedule_text_blob(
        df,
        ["status_type_short_detail", "status_type_name", "note", "notes", "game_note", "game_name", "name", "event_name"]
    )
    season_txt = _schedule_text_blob(df, ["season_type"])
    neutral = _coerce_bool_series(df.get("neutral_site", False), df.index)
    dt = pd.to_datetime(df.get("game_dt_et", df.get("game_date_time", pd.NaT)), errors="coerce")
    month = dt.dt.month.fillna(0).astype(int) if isinstance(dt, pd.Series) else pd.Series(0, index=df.index)
    day = dt.dt.day.fillna(0).astype(int) if isinstance(dt, pd.Series) else pd.Series(0, index=df.index)

    explicit = detail_txt.str.contains(
        NCAA_TOURNEY_TEXT_RE,
        case=False,
        na=False,
    )
    postseason = season_txt.str.contains(r"post|tournament|championship", case=False, na=False)
    march_window = ((month == 3) & (day >= 15)) | (month == 4)
    supporting_round = detail_txt.str.contains(
        r"first round|1st round|second round|2nd round|round of 64|round of 32|sweet|elite|regional|final four|national semifinal|championship",
        case=False,
        na=False,
    )
    return (explicit | (postseason & neutral & supporting_round) | (neutral & march_window & supporting_round)).fillna(False)


def _fallback_conf_tourney_flag(df: pd.DataFrame) -> pd.Series:
    detail_txt = _schedule_text_blob(
        df,
        ["status_type_short_detail", "status_type_name", "note", "notes", "game_note", "game_name", "name", "event_name"]
    )
    season_txt = _schedule_text_blob(df, ["season_type"])
    neutral = _coerce_bool_series(df.get("neutral_site", False), df.index)
    dt = pd.to_datetime(df.get("game_dt_et", df.get("game_date_time", pd.NaT)), errors="coerce")
    month = dt.dt.month.fillna(0).astype(int) if isinstance(dt, pd.Series) else pd.Series(0, index=df.index)
    roundish = detail_txt.str.contains(CONF_TOURNEY_TEXT_RE, case=False, na=False)
    explicit = detail_txt.str.contains(
        rf"{CONF_TOURNEY_TEXT_RE}|(?:{CONF_NAME_RE}).{{0,20}}(?:tournament|championship)",
        case=False,
        na=False,
    )
    postseason = season_txt.str.contains(r"post|tournament|championship", case=False, na=False)
    ncaa_fallback = _fallback_ncaa_tourney_flag(df)
    conservative = postseason & neutral & roundish & month.eq(3)
    return (explicit | conservative).fillna(False) & ~ncaa_fallback.fillna(False)


def _coerce_schedule_tournament_flags(df: pd.DataFrame, debug_key: str = "") -> pd.DataFrame:
    if df is None or len(df) == 0:
        return pd.DataFrame() if df is None else df.copy()

    out = df.copy()
    season_txt = _schedule_text_blob(out, ["season_type"])
    detail_txt = _schedule_text_blob(
        out,
        ["status_type_name", "status_type_short_detail", "note", "notes", "game_note", "game_name", "name", "event_name"]
    )
    neutral = _coerce_bool_series(out.get("neutral_site", False), out.index)

    explicit_ncaa = detail_txt.str.contains(
        NCAA_TOURNEY_TEXT_RE,
        case=False,
        na=False,
    ) | season_txt.str.contains(r"ncaa tournament", case=False, na=False)

    explicit_conf = detail_txt.str.contains(
        rf"{CONF_TOURNEY_TEXT_RE}|(?:{CONF_NAME_RE}).{{0,20}}(?:tournament|championship)|conference tournament|conference championship",
        case=False,
        na=False,
    ) | season_txt.str.contains(
        r"conference tournament|conf tournament",
        case=False,
        na=False,
    )

    fallback_ncaa = _fallback_ncaa_tourney_flag(out)
    fallback_conf = _fallback_conf_tourney_flag(out)
    existing_ncaa = pd.to_numeric(
        out.get("is_ncaa_tourney", pd.Series(0, index=out.index)),
        errors="coerce"
    ).fillna(0).astype(int).eq(1)
    existing_conf = pd.to_numeric(
        out.get("is_conf_tourney", pd.Series(0, index=out.index)),
        errors="coerce"
    ).fillna(0).astype(int).eq(1)
    existing_tourney = pd.to_numeric(
        out.get("is_tournament", pd.Series(0, index=out.index)),
        errors="coerce"
    ).fillna(0).astype(int).eq(1)

    is_ncaa = (explicit_ncaa | fallback_ncaa | existing_ncaa).fillna(False)
    is_conf = ((explicit_conf | fallback_conf | existing_conf).fillna(False)) & ~is_ncaa
    is_tournament = (is_ncaa | is_conf | existing_tourney | season_txt.str.contains(r"postseason", case=False, na=False)).fillna(False)
    is_tournament = is_tournament | (neutral & (is_ncaa | is_conf))

    out["is_tournament"] = is_tournament.astype("int8")
    out["is_conf_tourney"] = is_conf.astype("int8")
    out["is_ncaa_tourney"] = is_ncaa.astype("int8")

    if debug_key:
        TOURNAMENT_FLAG_DEBUG[debug_key] = {
            "rows": int(len(out)),
            "is_tournament": int(out["is_tournament"].sum()),
            "is_conf_tourney": int(out["is_conf_tourney"].sum()),
            "is_ncaa_tourney": int(out["is_ncaa_tourney"].sum()),
        }

    return out


def _build_team_id_name_map(schedule_df: pd.DataFrame, team_snaps: pd.DataFrame = None) -> dict:
    """
    canonical team name -> team_id
    built from schedule first, then team_snaps if available
    """
    frames = []

    if schedule_df is not None and len(schedule_df) > 0:
        s = schedule_df.copy()

        if {"home_id", "home_short_display_name"}.issubset(s.columns):
            x = s[["home_id", "home_short_display_name"]].copy()
            x.columns = ["team_id", "team_name"]
            frames.append(x)

        if {"away_id", "away_short_display_name"}.issubset(s.columns):
            x = s[["away_id", "away_short_display_name"]].copy()
            x.columns = ["team_id", "team_name"]
            frames.append(x)

        if {"home_id", "home_team"}.issubset(s.columns):
            x = s[["home_id", "home_team"]].copy()
            x.columns = ["team_id", "team_name"]
            frames.append(x)

        if {"away_id", "away_team"}.issubset(s.columns):
            x = s[["away_id", "away_team"]].copy()
            x.columns = ["team_id", "team_name"]
            frames.append(x)

    if team_snaps is not None and len(team_snaps) > 0:
        ts = team_snaps.copy()
        for id_col in ["team_id"]:
            if id_col in ts.columns:
                for nm_col in ["team_name", "display_name", "short_display_name", "team"]:
                    if nm_col in ts.columns:
                        x = ts[[id_col, nm_col]].copy()
                        x.columns = ["team_id", "team_name"]
                        frames.append(x)

    if not frames:
        return {}

    out = pd.concat(frames, ignore_index=True)
    out["team_id"] = pd.to_numeric(out["team_id"], errors="coerce")
    out["team_name"] = out["team_name"].astype(str).str.strip()

    out = out.dropna(subset=["team_id"]).copy()
    out = out[~out["team_name"].map(_bad_team_name)].copy()
    out["team_id"] = out["team_id"].astype(int)
    out["team_canon"] = out["team_name"].map(canonical_team)

    out = out.drop_duplicates(subset=["team_canon"], keep="last")
    return dict(zip(out["team_canon"], out["team_id"]))


def _build_id_team_name_map(schedule_df: pd.DataFrame, team_snaps: pd.DataFrame = None) -> dict:
    frames = []

    if schedule_df is not None and len(schedule_df) > 0:
        s = schedule_df.copy()

        if {"home_id", "home_short_display_name"}.issubset(s.columns):
            x = s[["home_id", "home_short_display_name"]].copy()
            x.columns = ["team_id", "team_name"]
            frames.append(x)

        if {"away_id", "away_short_display_name"}.issubset(s.columns):
            x = s[["away_id", "away_short_display_name"]].copy()
            x.columns = ["team_id", "team_name"]
            frames.append(x)

        if "home_id" in s.columns:
            x = pd.DataFrame({
                "team_id": s["home_id"],
                "team_name": _safe_team_text_col(s, ["home_team", "home_display_name", "home_name"], default="TBD"),
            })
            x.columns = ["team_id", "team_name"]
            frames.append(x)

        if "away_id" in s.columns:
            x = pd.DataFrame({
                "team_id": s["away_id"],
                "team_name": _safe_team_text_col(s, ["away_team", "away_display_name", "away_name"], default="TBD"),
            })
            x.columns = ["team_id", "team_name"]
            frames.append(x)

    if team_snaps is not None and len(team_snaps) > 0:
        ts = team_snaps.copy()
        if "team_id" in ts.columns:
            for nm_col in ["team_name", "display_name", "short_display_name", "team"]:
                if nm_col in ts.columns:
                    x = ts[["team_id", nm_col]].copy()
                    x.columns = ["team_id", "team_name"]
                    frames.append(x)

    if not frames:
        return {}

    out = pd.concat(frames, ignore_index=True)
    out["team_id"] = pd.to_numeric(out["team_id"], errors="coerce")
    out["team_name"] = out["team_name"].astype(str).str.strip()
    out = out.dropna(subset=["team_id"]).copy()
    out = out[~out["team_name"].map(_bad_team_name)].copy()
    out["team_id"] = out["team_id"].astype(int)
    out = out.drop_duplicates(subset=["team_id"], keep="last")
    return dict(zip(out["team_id"], out["team_name"]))


def _extract_valid_schedule_slate(schedule_df: pd.DataFrame, slate_date_et) -> pd.DataFrame:
    if schedule_df is None or len(schedule_df) == 0:
        return pd.DataFrame()

    s = schedule_df.copy()
    slate_date_et = pd.Timestamp(slate_date_et).date()

    dt_col = None
    for c in ["game_dt_et", "game_date_time", "start_date", "date"]:
        if c in s.columns:
            dt_col = c
            break

    if dt_col is None:
        return pd.DataFrame()

    s[dt_col] = pd.to_datetime(s[dt_col], errors="coerce", utc=True)

    if pd.api.types.is_datetime64tz_dtype(s[dt_col]):
        s["game_dt_et"] = s[dt_col].dt.tz_convert("America/New_York").dt.tz_localize(None)
    else:
        s["game_dt_et"] = pd.to_datetime(s[dt_col], errors="coerce")

    s = s.dropna(subset=["game_dt_et"]).copy()
    s["slate_date_et"] = s["game_dt_et"].dt.date
    s = s[s["slate_date_et"] == slate_date_et].copy()

    if len(s) == 0:
        return pd.DataFrame()

    # normalize ids
    for c in ["game_id", "home_id", "away_id", "home_score", "away_score"]:
        if c in s.columns:
            if c == "game_id":
                s[c] = s[c].astype(str)
            else:
                s[c] = pd.to_numeric(s[c], errors="coerce")

    if "neutral_site" in s.columns:
        s["neutral_site"] = _coerce_bool_series(s["neutral_site"], s.index)
    else:
        s["neutral_site"] = False

    if "home_short_display_name" not in s.columns:
        s["home_short_display_name"] = _safe_team_text_col(
            s, ["home_team", "home_display_name", "home_name"], default="TBD"
        )
    if "away_short_display_name" not in s.columns:
        s["away_short_display_name"] = _safe_team_text_col(
            s, ["away_team", "away_display_name", "away_name"], default="TBD"
        )

    if "home_team" not in s.columns:
        s["home_team"] = s["home_short_display_name"].astype(str)
    if "away_team" not in s.columns:
        s["away_team"] = s["away_short_display_name"].astype(str)

    req = ["home_id", "away_id"]
    for c in req:
        if c not in s.columns:
            s[c] = np.nan

    s = s.dropna(subset=["home_id", "away_id"]).copy()
    if len(s) == 0:
        return pd.DataFrame()

    s["home_id"] = s["home_id"].astype(int)
    s["away_id"] = s["away_id"].astype(int)

    if "game_id" in s.columns:
        s = s.sort_values(["game_dt_et", "game_id"])
        s = s.drop_duplicates(subset=["game_id"], keep="last")
    else:
        s = s.sort_values(["game_dt_et", "home_id", "away_id"])
        s = s.drop_duplicates(subset=["game_dt_et", "home_id", "away_id"], keep="last")

    s = s.reset_index(drop=True)
    return _coerce_schedule_tournament_flags(s, debug_key=f"schedule_slate_{slate_date_et}")


def _attach_schedule_tournament_context(
    df: pd.DataFrame,
    schedule_df: pd.DataFrame,
    slate_date_et,
    debug_key: str = "",
) -> pd.DataFrame:
    if df is None or len(df) == 0 or schedule_df is None or len(schedule_df) == 0:
        return pd.DataFrame() if df is None else df.copy()

    out = df.copy()
    sched = _extract_valid_schedule_slate(schedule_df, slate_date_et)
    if sched is None or len(sched) == 0:
        return out

    meta_cols = [
        c for c in [
            "game_id", "home_id", "away_id", "season_type", "neutral_site",
            "status_type_name", "status_type_short_detail",
            "note", "notes", "game_note", "game_name", "name", "event_name",
            "is_tournament", "is_conf_tourney", "is_ncaa_tourney",
        ]
        if c in sched.columns
    ]
    if not meta_cols:
        return out

    flag_cols = {"is_tournament", "is_conf_tourney", "is_ncaa_tourney"}
    text_cols = {"season_type", "status_type_name", "status_type_short_detail", "note", "notes", "game_note", "game_name", "name", "event_name"}
    match_counts = {"game_id": 0, "team_ids": 0, "canonical_names": 0}

    def _apply_lookup(key_series: pd.Series, lookup_df: pd.DataFrame, key_col: str, count_key: str = "") -> None:
        if count_key:
            try:
                match_counts[count_key] += int(key_series.isin(lookup_df.index).sum())
            except Exception:
                pass
        for col in [c for c in meta_cols if c != key_col]:
            mapped = key_series.map(lookup_df[col])
            if col in flag_cols:
                existing = pd.to_numeric(out.get(col, pd.Series(np.nan, index=out.index)), errors="coerce")
                out[col] = np.where(mapped.notna(), pd.to_numeric(mapped, errors="coerce"), existing)
            elif col == "neutral_site":
                existing = _coerce_bool_series(out.get(col, pd.Series(False, index=out.index)), out.index)
                mapped_bool = _coerce_bool_series(mapped, out.index)
                out[col] = np.where(mapped.notna(), mapped_bool, existing)
            elif col in text_cols:
                if col not in out.columns:
                    out[col] = pd.Series("", index=out.index, dtype="object")
                elif not (pd.api.types.is_object_dtype(out[col]) or pd.api.types.is_string_dtype(out[col])):
                    out[col] = out[col].astype("object")
                existing = out[col].fillna("").astype(str)
                mapped_txt = mapped.fillna("").astype(str)
                use_map = mapped_txt.str.strip().ne("") & existing.str.strip().eq("")
                out.loc[use_map, col] = mapped_txt.loc[use_map]

    if "game_id" in out.columns and "game_id" in sched.columns:
        sched_gid = sched[meta_cols].copy()
        sched_gid["game_id"] = sched_gid["game_id"].astype(str)
        sched_gid = sched_gid.drop_duplicates(subset=["game_id"], keep="last").set_index("game_id")
        _apply_lookup(out["game_id"].astype(str), sched_gid, "game_id", "game_id")

    if {"home_id", "away_id"}.issubset(out.columns) and {"home_id", "away_id"}.issubset(sched.columns):
        sched_ids = sched[meta_cols].copy()
        sched_ids["home_id"] = pd.to_numeric(sched_ids["home_id"], errors="coerce")
        sched_ids["away_id"] = pd.to_numeric(sched_ids["away_id"], errors="coerce")
        sched_ids = sched_ids.dropna(subset=["home_id", "away_id"]).copy()
        if len(sched_ids) > 0:
            sched_ids["k_ids"] = (
                sched_ids["home_id"].astype(int).astype(str) + "|" +
                sched_ids["away_id"].astype(int).astype(str)
            )
            sched_ids = sched_ids.drop_duplicates(subset=["k_ids"], keep="last").set_index("k_ids")
            out_home = pd.to_numeric(out["home_id"], errors="coerce")
            out_away = pd.to_numeric(out["away_id"], errors="coerce")
            out_keys = (
                out_home.fillna(-1).astype(int).astype(str) + "|" +
                out_away.fillna(-1).astype(int).astype(str)
            )
            _apply_lookup(out_keys, sched_ids, "k_ids", "team_ids")

    sched_home = _safe_team_text_col(sched, ["home_team", "home_short_display_name", "home_display_name", "home_name"], default="TBD")
    sched_away = _safe_team_text_col(sched, ["away_team", "away_short_display_name", "away_display_name", "away_name"], default="TBD")
    out_home_name = _safe_team_text_col(out, ["home_team", "home_short_display_name", "home_display_name", "home_name"], default="TBD")
    out_away_name = _safe_team_text_col(out, ["away_team", "away_short_display_name", "away_display_name", "away_name"], default="TBD")
    sched["k_names"] = sched_away.astype(str).map(canonical_team) + "|" + sched_home.astype(str).map(canonical_team)
    out_name_keys = out_away_name.astype(str).map(canonical_team) + "|" + out_home_name.astype(str).map(canonical_team)
    sched_names = sched[meta_cols + ["k_names"]].copy()
    sched_names = sched_names[sched_names["k_names"].str.strip().ne("|")].drop_duplicates(subset=["k_names"], keep="last").set_index("k_names")
    if len(sched_names) > 0:
        _apply_lookup(out_name_keys, sched_names, "k_names", "canonical_names")

    for col in flag_cols:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce").fillna(0).astype("int8")

    if debug_key:
        TOURNAMENT_FLAG_DEBUG[debug_key] = {
            **TOURNAMENT_FLAG_DEBUG.get(debug_key, {}),
            "context_match_game_id": int(match_counts["game_id"]),
            "context_match_team_ids": int(match_counts["team_ids"]),
            "context_match_canonical_names": int(match_counts["canonical_names"]),
            "context_flagged_rows": int(pd.to_numeric(out.get("is_tournament", pd.Series(0, index=out.index)), errors="coerce").fillna(0).astype(int).sum()),
        }

    return out


def _build_rotowire_fallback_slate(
    slate_date_et,
    schedule_df: pd.DataFrame,
    rotowire_dir: str,
    team_snaps: pd.DataFrame = None,
) -> pd.DataFrame:
    rw = load_rotowire_all_for_date(slate_date_et, rotowire_dir)
    if rw is None or len(rw) == 0:
        return pd.DataFrame()

    if "rw_game_dt_et" in rw.columns:
        rw = rw.copy()
        rw["rw_game_dt_et"] = pd.to_datetime(rw["rw_game_dt_et"], errors="coerce")
        if rw["rw_game_dt_et"].notna().any():
            rw = rw[rw["rw_game_dt_et"].dt.date == pd.Timestamp(slate_date_et).date()].copy()
        else:
            rw = pd.DataFrame()
        if len(rw) == 0:
            return pd.DataFrame()

    name_to_id = _build_team_id_name_map(schedule_df, team_snaps)

    out = rw.copy()
    out["away_team"] = out["away_team"].astype(str).str.strip()
    out["home_team"] = out["home_team"].astype(str).str.strip()
    out["away_canon"] = out["away_team"].map(canonical_team)
    out["home_canon"] = out["home_team"].map(canonical_team)
    out["away_id"] = out["away_canon"].map(name_to_id)
    out["home_id"] = out["home_canon"].map(name_to_id)

    missing_ids = out[out["away_id"].isna() | out["home_id"].isna()]
    for _, row in missing_ids.head(10).iterrows():
        _record_canonical_mismatch("rotowire_fallback_id_unmapped", {
            "date": str(pd.Timestamp(slate_date_et).date()),
            "away_team": row.get("away_team"),
            "home_team": row.get("home_team"),
            "away_canon": row.get("away_canon"),
            "home_canon": row.get("home_canon"),
        })

    out = out.dropna(subset=["away_id", "home_id"]).copy()
    if len(out) == 0:
        return pd.DataFrame()

    out["away_id"] = out["away_id"].astype(int)
    out["home_id"] = out["home_id"].astype(int)

    base_dt = pd.Timestamp(slate_date_et).tz_localize("America/New_York").tz_localize(None)
    out["game_dt_et"] = base_dt + pd.to_timedelta(np.arange(len(out)) * 5, unit="m")
    out["game_id"] = [
        f"RW_{pd.Timestamp(slate_date_et).strftime('%Y%m%d')}_{i}_{a}_{h}"
        for i, (a, h) in enumerate(zip(out["away_id"], out["home_id"]))
    ]

    out["neutral_site"] = False
    out["away_short_display_name"] = out["away_team"]
    out["home_short_display_name"] = out["home_team"]
    out["home_score"] = np.nan
    out["away_score"] = np.nan
    out["status_type_completed"] = False
    out["status_type_state"] = "pre"
    out["status_type_name"] = "STATUS_SCHEDULED"
    out["status_type_short_detail"] = ""
    out = _attach_schedule_tournament_context(
        out, schedule_df, slate_date_et,
        debug_key=f"rotowire_fallback_context_{pd.Timestamp(slate_date_et).date()}",
    )
    out = _coerce_schedule_tournament_flags(out, debug_key=f"rotowire_fallback_{pd.Timestamp(slate_date_et).date()}")

    keep = [
        "game_id", "game_dt_et", "neutral_site",
        "home_id", "away_id",
        "home_team", "away_team",
        "home_short_display_name", "away_short_display_name",
        "home_score", "away_score",
        "status_type_completed", "status_type_state",
        "status_type_name", "status_type_short_detail"
    ]
    return out[keep].reset_index(drop=True)


def _fill_tbd_schedule_from_rotowire(
    slate: pd.DataFrame,
    slate_date_et,
    schedule_df: pd.DataFrame,
    rotowire_dir: str,
    team_snaps: pd.DataFrame = None,
) -> pd.DataFrame:
    """
    If schedule has TBD on one side, fill the missing side using Rotowire.
    Match priority:
      1) exact known home team canon
      2) exact known away team canon
      3) unique unused RW row
    """
    if slate is None or len(slate) == 0:
        return slate

    rw = load_rotowire_all_for_date(slate_date_et, rotowire_dir)
    if rw is None or len(rw) == 0:
        rw = pd.DataFrame()

    name_to_id = _build_team_id_name_map(schedule_df, team_snaps)
    id_to_name = _build_id_team_name_map(schedule_df, team_snaps)
    rw = rw.copy()
    rw["rw_idx"] = np.arange(len(rw))
    rw["home_team"] = _safe_team_text_col(
        rw, ["home_team", "home_short_display_name", "home_display_name", "home_name"], default="TBD"
    ).astype(str).str.strip()
    rw["away_team"] = _safe_team_text_col(
        rw, ["away_team", "away_short_display_name", "away_display_name", "away_name"], default="TBD"
    ).astype(str).str.strip()
    bad_home = _normalize_bool_mask(rw["home_team"].map(_bad_team_name), label="bad_home", context="_fill_tbd_schedule_from_rotowire")
    bad_away = _normalize_bool_mask(rw["away_team"].map(_bad_team_name), label="bad_away", context="_fill_tbd_schedule_from_rotowire")
    rw = rw[~(bad_home | bad_away)].copy()
    rw["home_canon"] = rw["home_team"].map(canonical_team)
    rw["away_canon"] = rw["away_team"].map(canonical_team)
    rw["home_id"] = rw["home_canon"].map(name_to_id)
    rw["away_id"] = rw["away_canon"].map(name_to_id)

    b = slate.copy()
    b["home_team"] = _safe_team_text_col(b, ["home_team", "home_short_display_name"], default="TBD")
    b["away_team"] = _safe_team_text_col(b, ["away_team", "away_short_display_name"], default="TBD")
    b["home_short_display_name"] = _safe_team_text_col(b, ["home_short_display_name", "home_team"], default="TBD")
    b["away_short_display_name"] = _safe_team_text_col(b, ["away_short_display_name", "away_team"], default="TBD")

    def _relaxed_canon_keys(name: str) -> list:
        c = canonical_team(name)
        keys = [c]
        toks = c.split()
        if len(toks) >= 2:
            keys.append(" ".join(toks[:-1]))
        return [k for k in keys if k]

    used_rw = set()

    for idx in b.index:
        home_name = str(b.at[idx, "home_team"]).strip()
        away_name = str(b.at[idx, "away_team"]).strip()
        home_bad = _bad_team_name(home_name)
        away_bad = _bad_team_name(away_name)

        if home_bad:
            home_id = pd.to_numeric(pd.Series([b.at[idx, "home_id"]]), errors="coerce").iloc[0] if "home_id" in b.columns else np.nan
            if pd.notna(home_id):
                mapped = id_to_name.get(int(home_id))
                if mapped and not _bad_team_name(mapped):
                    b.at[idx, "home_team"] = mapped
                    b.at[idx, "home_short_display_name"] = mapped
        if away_bad:
            away_id = pd.to_numeric(pd.Series([b.at[idx, "away_id"]]), errors="coerce").iloc[0] if "away_id" in b.columns else np.nan
            if pd.notna(away_id):
                mapped = id_to_name.get(int(away_id))
                if mapped and not _bad_team_name(mapped):
                    b.at[idx, "away_team"] = mapped
                    b.at[idx, "away_short_display_name"] = mapped

        home_name = str(b.at[idx, "home_team"]).strip()
        away_name = str(b.at[idx, "away_team"]).strip()
        home_bad = _bad_team_name(home_name)
        away_bad = _bad_team_name(away_name)

        if not (home_bad or away_bad):
            continue

        if len(rw) == 0:
            continue

        cand = rw.copy()

        # match on known side
        if not home_bad:
            hc = canonical_team(home_name)
            cand = cand[cand["home_canon"] == hc].copy()
            if len(cand) == 0:
                cand = rw[rw["home_canon"].isin(_relaxed_canon_keys(home_name))].copy()

        if not away_bad:
            ac = canonical_team(away_name)
            cand = cand[cand["away_canon"] == ac].copy()
            if len(cand) == 0:
                cand = rw[rw["away_canon"].isin(_relaxed_canon_keys(away_name))].copy()

        # if still multiple, prefer one not used yet
        if len(cand) > 1:
            cand = cand[~cand["rw_idx"].isin(used_rw)].copy()

        # weak fallback: if only one schedule row is unresolved and one rw row unused fits
        if len(cand) == 0:
            remaining = rw[~rw["rw_idx"].isin(used_rw)].copy()
            if len(remaining) == 1:
                cand = remaining

        if len(cand) == 0:
            _record_canonical_mismatch("rotowire_tbd_unresolved", {
                "date": str(pd.Timestamp(slate_date_et).date()),
                "home_team": home_name,
                "away_team": away_name,
                "home_canon": canonical_team(home_name) if not home_bad else "tbd",
                "away_canon": canonical_team(away_name) if not away_bad else "tbd",
                "rw_candidates": rw[["away_team", "home_team", "away_canon", "home_canon"]].head(10).to_dict("records"),
            })
            continue

        row = cand.iloc[0]
        used_rw.add(int(row["rw_idx"]))

        # overwrite both sides from RW so the matchup is fully coherent
        b.at[idx, "home_team"] = row["home_team"]
        b.at[idx, "away_team"] = row["away_team"]
        b.at[idx, "home_short_display_name"] = row["home_team"]
        b.at[idx, "away_short_display_name"] = row["away_team"]

        if pd.notna(row.get("home_id")):
            b.at[idx, "home_id"] = int(row["home_id"])
        if pd.notna(row.get("away_id")):
            b.at[idx, "away_id"] = int(row["away_id"])

    return b


def ensure_board_team_columns(df: pd.DataFrame) -> pd.DataFrame:
    """
    Guarantees home_team / away_team always exist.
    """
    if df is None:
        return pd.DataFrame()

    out = df.copy()

    if "home_team" not in out.columns:
        if "home_short_display_name" in out.columns:
            out["home_team"] = out["home_short_display_name"].astype(str)
        else:
            out["home_team"] = "TBD"

    if "away_team" not in out.columns:
        if "away_short_display_name" in out.columns:
            out["away_team"] = out["away_short_display_name"].astype(str)
        else:
            out["away_team"] = "TBD"

    out["home_team"] = out["home_team"].astype(str).replace({"nan": "TBD", "None": "TBD"})
    out["away_team"] = out["away_team"].astype(str).replace({"nan": "TBD", "None": "TBD"})

    if "home_short_display_name" not in out.columns:
        out["home_short_display_name"] = out["home_team"]
    if "away_short_display_name" not in out.columns:
        out["away_short_display_name"] = out["away_team"]

    return out


def _dedupe_game_rows(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or len(df) == 0:
        return pd.DataFrame() if df is None else df.copy()

    out = df.copy()
    sort_cols = [c for c in ["game_dt_et", "status_type_completed", "status_type_state", "home_score", "away_score"] if c in out.columns]
    if sort_cols:
        out = out.sort_values(sort_cols, kind="mergesort", na_position="last").reset_index(drop=True)

    if "game_id" in out.columns:
        gid = out["game_id"].astype(str).str.strip()
        valid_gid = gid.ne("") & ~gid.isin(["nan", "None"])
        if valid_gid.any():
            out = pd.concat(
                [
                    out.loc[~valid_gid],
                    out.loc[valid_gid].drop_duplicates(subset=["game_id"], keep="last"),
                ]
            ).sort_index().reset_index(drop=True)

    if {"game_dt_et", "home_id", "away_id"}.issubset(out.columns):
        key = out[["game_dt_et", "home_id", "away_id"]].copy()
        if key.notna().all(axis=1).any():
            out = out.drop_duplicates(subset=["game_dt_et", "home_id", "away_id"], keep="last").reset_index(drop=True)

    if {"game_dt_et", "away_team", "home_team"}.issubset(out.columns):
        game_dt = pd.to_datetime(out.get("game_dt_et"), errors="coerce")
        if getattr(game_dt.dt, "tz", None) is not None:
            game_dt = game_dt.dt.tz_convert("America/New_York").dt.tz_localize(None)
        out["_game_date"] = game_dt.dt.date
        out["_away_team_key"] = out["away_team"].astype(str).map(canonical_team)
        out["_home_team_key"] = out["home_team"].astype(str).map(canonical_team)
        valid_key = out["_game_date"].notna() & out["_away_team_key"].ne("") & out["_home_team_key"].ne("")
        if valid_key.any():
            out = pd.concat(
                [
                    out.loc[~valid_key],
                    out.loc[valid_key].drop_duplicates(
                        subset=["_game_date", "_away_team_key", "_home_team_key"],
                        keep="last",
                    ),
                ]
            ).sort_index().reset_index(drop=True)
        out = out.drop(columns=["_game_date", "_away_team_key", "_home_team_key"], errors="ignore")

    return out.reset_index(drop=True)


def build_pregame_dataset_for_slate(
    schedule_df: pd.DataFrame,
    team_snaps: pd.DataFrame,
    roll_cols: list,
    slate_date_et,
    window: int = ROLL_WINDOW,
    elo_snap: pd.DataFrame = None,
) -> pd.DataFrame:
    slate_date_et = pd.Timestamp(slate_date_et).date()
    today_et = pd.Timestamp.now(tz="America/New_York").date()
    is_past_date = slate_date_et < today_et

    _set_build_progress(f"Loading schedule slate for {slate_date_et}...")
    slate = _extract_valid_schedule_slate(schedule_df, slate_date_et)
    _set_build_progress(f"Schedule rows found: {0 if slate is None else len(slate)}")

    if is_past_date:
        schedule_is_complete = False
        if slate is not None and len(slate) > 0:
            try:
                schedule_is_complete = bool(
                    {"home_id", "away_id"}.issubset(slate.columns)
                    and "home_team" in slate.columns
                    and "away_team" in slate.columns
                    and pd.to_numeric(slate.get("home_id"), errors="coerce").notna().all()
                    and pd.to_numeric(slate.get("away_id"), errors="coerce").notna().all()
                    and (~slate["home_team"].map(_bad_team_name)).all()
                    and (~slate["away_team"].map(_bad_team_name)).all()
                )
            except Exception:
                schedule_is_complete = False

        if (not schedule_is_complete) and "team_box_hist" in globals() and team_box_hist is not None and len(team_box_hist) > 0:
            tb = team_box_hist.copy()
            if {"game_id", "game_date_time"}.issubset(tb.columns):
                tb["game_id"] = tb["game_id"].astype(str)
                tb["game_date_time"] = pd.to_datetime(tb["game_date_time"], errors="coerce", utc=True)
                tb = tb.dropna(subset=["game_id", "game_date_time"]).copy()
                tb["game_dt_et"] = tb["game_date_time"].dt.tz_convert("America/New_York").dt.tz_localize(None)
                tb = tb[tb["game_dt_et"].dt.date == slate_date_et].copy()
                if len(tb) > 0:
                    id_to_name = _build_id_team_name_map(schedule_df, team_snaps)
                    def _pick_hist_team_name(row, suffix: str) -> str:
                        display_name = str(row.get(f"team_display_name{suffix}", "")).strip()
                        if not _bad_team_name(display_name):
                            return display_name

                        team_name = str(row.get(f"team_name{suffix}", "")).strip()
                        if not _bad_team_name(team_name):
                            return team_name

                        location = str(row.get(f"team_location{suffix}", "")).strip()
                        mascot = str(row.get(f"team_mascot{suffix}", "")).strip()
                        if not _bad_team_name(location) and not _bad_team_name(mascot):
                            return f"{location} {mascot}".strip()
                        if not _bad_team_name(location):
                            return location
                        if not _bad_team_name(mascot):
                            return mascot
                        return ""

                    if "team_name" not in tb.columns:
                        tb["team_name"] = np.nan
                    tb["team_name"] = tb["team_name"].astype(str).str.strip()

                    rows = []
                    if "team_home_away" in tb.columns:
                        home = tb[tb["team_home_away"].astype(str).str.lower().eq("home")].copy()
                        away = tb[tb["team_home_away"].astype(str).str.lower().eq("away")].copy()
                        if len(home) and len(away):
                            home = home.sort_values(["game_dt_et", "game_id"]).drop_duplicates(["game_id"], keep="last")
                            away = away.sort_values(["game_dt_et", "game_id"]).drop_duplicates(["game_id"], keep="last")
                            merged_tb = home.merge(
                                away,
                                on="game_id",
                                how="inner",
                                suffixes=("_home", "_away"),
                            )
                            for _, r in merged_tb.iterrows():
                                home_name = _pick_hist_team_name(r, "_home")
                                away_name = _pick_hist_team_name(r, "_away")
                                home_id = pd.to_numeric(pd.Series([r.get("team_id_home")]), errors="coerce").iloc[0]
                                away_id = pd.to_numeric(pd.Series([r.get("team_id_away")]), errors="coerce").iloc[0]
                                if _bad_team_name(home_name) and pd.notna(home_id):
                                    home_name = id_to_name.get(int(home_id), home_name)
                                if _bad_team_name(away_name) and pd.notna(away_id):
                                    away_name = id_to_name.get(int(away_id), away_name)
                                rows.append({
                                    "game_id": str(r["game_id"]),
                                    "game_dt_et": r.get("game_dt_et_home", r.get("game_dt_et_away")),
                                    "neutral_site": False,
                                    "home_id": home_id,
                                    "away_id": away_id,
                                    "home_team": home_name if not _bad_team_name(home_name) else "TBD",
                                    "away_team": away_name if not _bad_team_name(away_name) else "TBD",
                                    "home_short_display_name": home_name if not _bad_team_name(home_name) else "TBD",
                                    "away_short_display_name": away_name if not _bad_team_name(away_name) else "TBD",
                                    "home_score": pd.to_numeric(pd.Series([r.get("team_score_home")]), errors="coerce").iloc[0],
                                    "away_score": pd.to_numeric(pd.Series([r.get("team_score_away")]), errors="coerce").iloc[0],
                                    "status_type_completed": True,
                                    "status_type_state": "post",
                                    "status_type_name": "STATUS_FINAL",
                                    "status_type_short_detail": "Final",
                                })

                    if rows:
                        tb_slate = pd.DataFrame(rows).drop_duplicates(subset=["game_id"], keep="last")
                        if slate is None or len(slate) == 0:
                            slate = tb_slate.copy()
                        else:
                            slate["game_id"] = slate["game_id"].astype(str)
                            if {"home_team", "away_team"}.issubset(slate.columns):
                                bad_hist = (
                                    slate["home_team"].map(_bad_team_name)
                                    | slate["away_team"].map(_bad_team_name)
                                    | pd.to_numeric(slate.get("home_id"), errors="coerce").fillna(-1).le(0)
                                    | pd.to_numeric(slate.get("away_id"), errors="coerce").fillna(-1).le(0)
                                )
                                bad_ids = set(slate.loc[bad_hist, "game_id"].astype(str))
                                keep = slate.loc[~slate["game_id"].isin(bad_ids)].copy()
                            else:
                                bad_ids = set()
                                keep = slate.copy()
                            repl = tb_slate[tb_slate["game_id"].isin(bad_ids)].copy()
                            extras = tb_slate[~tb_slate["game_id"].isin(set(slate["game_id"].astype(str)))].copy()
                            slate = pd.concat([keep, repl, extras], ignore_index=True, sort=False)

    # fill partial schedule rows like "TBD vs Prairie View" using Rotowire
    if (not is_past_date) and slate is not None and len(slate) > 0:
        slate = _fill_tbd_schedule_from_rotowire(
            slate=slate,
            slate_date_et=slate_date_et,
            schedule_df=schedule_df,
            rotowire_dir=ROTOWIRE_DIR,
            team_snaps=team_snaps,
        )

    # if slate is still bad/incomplete, replace with full Rotowire slate
    if (not is_past_date) and (slate is None or len(slate) == 0):
        slate = _build_rotowire_fallback_slate(
            slate_date_et=slate_date_et,
            schedule_df=schedule_df,
            rotowire_dir=ROTOWIRE_DIR,
            team_snaps=team_snaps,
        )
    elif not is_past_date:
        bad_mask = (
            slate["home_team"].map(_bad_team_name)
            | slate["away_team"].map(_bad_team_name)
            | slate["home_id"].isna()
            | slate["away_id"].isna()
        )
        if bad_mask.any():
            rw_full = _build_rotowire_fallback_slate(
                slate_date_et=slate_date_et,
                schedule_df=schedule_df,
                rotowire_dir=ROTOWIRE_DIR,
                team_snaps=team_snaps,
            )
            if rw_full is not None and len(rw_full) > 0:
                slate = rw_full

    if slate is None or len(slate) == 0:
        return pd.DataFrame()

    slate = ensure_board_team_columns(slate)
    slate = _attach_schedule_tournament_context(
        slate, schedule_df, slate_date_et,
        debug_key=f"pregame_context_{slate_date_et}",
    )
    slate = _coerce_schedule_tournament_flags(slate, debug_key=f"pregame_{slate_date_et}")
    if slate_date_et < today_et:
        keep_mask = ~(slate["home_team"].map(_bad_team_name) | slate["away_team"].map(_bad_team_name))
        slate = slate[keep_mask].copy()

    if slate is None or len(slate) == 0:
        return pd.DataFrame()

    _set_build_progress("Preparing rolling team snapshot lookup...")
    snaps, use_roll_cols = _get_prepared_team_snaps(team_snaps, roll_cols)
    if len(snaps) == 0:
        _set_build_progress("No prepared team snapshots available for this slate.")
        return pd.DataFrame()

    def asof_team(team_ids, times, prefix):
        out = pd.DataFrame(index=np.arange(len(team_ids)))

        left = pd.DataFrame({
            "row_id": np.arange(len(team_ids), dtype="int64"),
            "team_id": pd.to_numeric(pd.Series(team_ids), errors="coerce"),
            "game_dt_et": pd.to_datetime(pd.Series(times), errors="coerce"),
        })

        left = left.dropna(subset=["team_id", "game_dt_et"]).copy()
        if len(left) == 0 or len(use_roll_cols) == 0:
            for c in use_roll_cols:
                out[f"{c}_{prefix}"] = np.nan
            return out

        # force exact dtypes for merge_asof
        left["team_id"] = left["team_id"].astype("int64")
        left["game_dt_et"] = pd.to_datetime(left["game_dt_et"], errors="coerce").astype("datetime64[ns]")
        left = left.sort_values(["game_dt_et", "team_id"], kind="mergesort").reset_index(drop=True)

        right = snaps[["team_id", "game_dt_et"] + use_roll_cols].copy()
        right["team_id"] = pd.to_numeric(right["team_id"], errors="coerce")
        right["game_dt_et"] = pd.to_datetime(right["game_dt_et"], errors="coerce")

        right = right.dropna(subset=["team_id", "game_dt_et"]).copy()
        if len(right) == 0:
            for c in use_roll_cols:
                out[f"{c}_{prefix}"] = np.nan
            return out

        right["team_id"] = right["team_id"].astype("int64")
        right["game_dt_et"] = right["game_dt_et"].astype("datetime64[ns]")
        right = right.sort_values(["game_dt_et", "team_id"], kind="mergesort").reset_index(drop=True)

        merged = pd.merge_asof(
            left,
            right,
            on="game_dt_et",
            by="team_id",
            direction="backward",
            allow_exact_matches=True,
        ).sort_values("row_id")

        for c in use_roll_cols:
            out[f"{c}_{prefix}"] = np.nan
            if c in merged.columns:
                out.loc[merged["row_id"].to_numpy(), f"{c}_{prefix}"] = merged[c].to_numpy()

        return out

    _set_build_progress("Merging home rolling features...")
    home_feats = asof_team(slate["home_id"].values, slate["game_dt_et"].values, "HOME")
    _set_build_progress("Merging away rolling features...")
    away_feats = asof_team(slate["away_id"].values, slate["game_dt_et"].values, "AWAY")

    base_cols = [
        "game_id", "game_dt_et", "neutral_site",
        "is_tournament", "is_conf_tourney", "is_ncaa_tourney",
        "home_id", "away_id",
        "home_team", "away_team",
        "home_short_display_name", "away_short_display_name",
        "home_score", "away_score",
        "status_type_completed", "status_type_state",
        "status_type_name", "status_type_short_detail",
    ]
    base_cols = [c for c in base_cols if c in slate.columns]
    joined = pd.concat([slate[base_cols].reset_index(drop=True), home_feats, away_feats], axis=1)

    joined = ensure_board_team_columns(joined)

    joined["home_id"] = pd.to_numeric(joined["home_id"], errors="coerce").astype(int)
    joined["away_id"] = pd.to_numeric(joined["away_id"], errors="coerce").astype(int)

    joined["teamA_id"] = np.minimum(joined["home_id"], joined["away_id"]).astype(int)
    joined["teamB_id"] = np.maximum(joined["home_id"], joined["away_id"]).astype(int)

    teamA_is_home = joined["teamA_id"].values == joined["home_id"].values

    TA, TB, DIFF = {}, {}, {}
    for c in use_roll_cols:
        h = f"{c}_HOME"
        a = f"{c}_AWAY"
        if h not in joined.columns or a not in joined.columns:
            continue

        ta = np.where(teamA_is_home, joined[h], joined[a])
        tb = np.where(teamA_is_home, joined[a], joined[h])

        TA[f"{c}_TA"] = ta
        TB[f"{c}_TB"] = tb
        DIFF[f"diff_{c}"] = ta - tb

    if DIFF:
        joined = pd.concat(
            [
                joined,
                pd.DataFrame(TA, index=joined.index),
                pd.DataFrame(TB, index=joined.index),
                pd.DataFrame(DIFF, index=joined.index),
            ],
            axis=1
        )

    diff_cols_local = [c for c in joined.columns if c.startswith("diff_")]
    if diff_cols_local:
        joined[diff_cols_local] = joined[diff_cols_local].apply(pd.to_numeric, errors="coerce")

    _set_build_progress("Attaching Elo and market context...")
    if elo_snap is not None and len(elo_snap) > 0:
        joined = add_elo_asof_features(joined, elo_snap)

    neutral = _coerce_bool_series(joined.get("neutral_site", False), joined.index)
    joined["home_court_A"] = np.where(neutral, 0.0, np.where(teamA_is_home, 1.0, -1.0))
    if (not _is_past_local_slate(slate_date_et)) or _has_exact_rotowire_file_for_date(slate_date_et, ROTOWIRE_DIR):
        joined = attach_rotowire_features_by_row_date(joined, date_col="game_dt_et")
    else:
        if "rw_spread_home" not in joined.columns:
            joined["rw_spread_home"] = np.nan
        if "rw_home_ml" not in joined.columns:
            joined["rw_home_ml"] = np.nan
        if "rw_away_ml" not in joined.columns:
            joined["rw_away_ml"] = np.nan
        if "rw_total" not in joined.columns:
            joined["rw_total"] = np.nan
        joined["rw_missing_reason"] = "No RW odds in file"
    joined = _add_hybrid_spread_features(joined)

    if joined.columns.duplicated().any():
        joined = joined.loc[:, ~joined.columns.duplicated()].copy()

    joined = ensure_board_team_columns(joined).reset_index(drop=True)
    return _dedupe_game_rows(joined)


def attach_rotowire_features_by_row_date(board: pd.DataFrame, date_col: str = "game_dt_et") -> pd.DataFrame:
    """Attach optional Rotowire market fields to a mixed-date frame by row date."""
    if board is None or len(board) == 0:
        return board

    out = board.copy()
    prior_rw_cols = [c for c in out.columns if str(c).endswith("_rw")]
    prior_rw_cols += [
        "rw_spread_home", "rw_home_ml", "rw_away_ml", "rw_total", "rw_missing_reason",
        "vegas_spread_home", "has_market_spread", "market_abs_spread", "market_home_fav",
        "vegas_total", "has_market_total",
    ]
    out = out.drop(columns=[c for c in prior_rw_cols if c in out.columns], errors="ignore")
    row_dates = pd.to_datetime(out.get(date_col), errors="coerce").dt.date
    out["_rw_row_date"] = row_dates

    default_cols = ["rw_spread_home", "rw_home_ml", "rw_away_ml", "rw_total", "rw_missing_reason"]
    for col in default_cols:
        if col not in out.columns:
            out[col] = "" if col == "rw_missing_reason" else np.nan

    valid_mask = out["_rw_row_date"].notna()
    if valid_mask.any():
        for d, idx in out.loc[valid_mask].groupby("_rw_row_date").groups.items():
            patched = _attach_rotowire_to_board(out.loc[idx].copy(), d)
            for col in default_cols:
                if col in patched.columns:
                    out.loc[idx, col] = patched[col].values

    return out.drop(columns=["_rw_row_date"], errors="ignore")


def _num_or_nan(df: pd.DataFrame, col: str) -> pd.Series:
    return pd.to_numeric(df.get(col, pd.Series(np.nan, index=df.index)), errors="coerce")


def _safe_rate(numer, denom, scale: float = 1.0) -> pd.Series:
    numer_s = pd.to_numeric(numer, errors="coerce")
    denom_s = pd.to_numeric(denom, errors="coerce").replace(0, np.nan)
    return scale * numer_s / denom_s


def _market_implied_home_margin(spread_home) -> pd.Series:
    """
    Convert sportsbook home spread convention into home-minus-away margin convention.
    Example: home -7.5 implies expected home margin +7.5.
    """
    return -pd.to_numeric(spread_home, errors="coerce")


def _first_existing_team_col(df: pd.DataFrame, templates: list[str]) -> str | None:
    for c in templates:
        if c in df.columns:
            return c
    return None


def _add_hybrid_spread_features(df: pd.DataFrame) -> pd.DataFrame:
    """
    Add spread-model features that keep working when market data is sparse.
    These columns intentionally do not start with diff_ so the winner model
    stays on its existing feature family unless explicitly changed.
    """
    if df is None or len(df) == 0:
        return df

    out = df.copy()

    if "vegas_spread_home" not in out.columns:
        out["vegas_spread_home"] = _num_or_nan(out, "rw_spread_home")
    else:
        out["vegas_spread_home"] = pd.to_numeric(out["vegas_spread_home"], errors="coerce")

    out["has_market_spread"] = out["vegas_spread_home"].notna().astype(float)
    out["market_abs_spread"] = out["vegas_spread_home"].abs()
    out["market_home_fav"] = (out["vegas_spread_home"] < 0).astype(float)
    out["vegas_total"] = _num_or_nan(out, "rw_total")
    out["has_market_total"] = out["vegas_total"].notna().astype(float)

    out["neutral_site_flag"] = _coerce_bool_series(out.get("neutral_site", False), out.index).astype(float)
    out["is_tournament"] = pd.to_numeric(out.get("is_tournament", pd.Series(0, index=out.index)), errors="coerce").fillna(0.0)
    out["is_conf_tourney"] = pd.to_numeric(out.get("is_conf_tourney", pd.Series(0, index=out.index)), errors="coerce").fillna(0.0)
    out["is_ncaa_tourney"] = pd.to_numeric(out.get("is_ncaa_tourney", pd.Series(0, index=out.index)), errors="coerce").fillna(0.0)
    out["neutral_tourney_flag"] = out["neutral_site_flag"] * out["is_tournament"]

    if "rest_diff" not in out.columns:
        if "diff_rest_days" in out.columns:
            out["rest_diff"] = _num_or_nan(out, "diff_rest_days")
        elif {"rest_days_HOME", "rest_days_AWAY"}.issubset(out.columns):
            out["rest_diff"] = _num_or_nan(out, "rest_days_HOME") - _num_or_nan(out, "rest_days_AWAY")

    trend_bases = [
        "points_for", "points_against", "point_diff", "field_goal_pct",
        "three_point_field_goal_pct", "free_throw_pct", "total_rebounds",
        "offensive_rebounds", "turnovers", "steals", "blocks",
    ]
    for base in trend_bases:
        r3 = f"diff_r3_mean_{base}"
        r10 = f"diff_r10_mean_{base}"
        if r3 in out.columns and r10 in out.columns:
            out[f"trend_{base}"] = _num_or_nan(out, r3) - _num_or_nan(out, r10)

    for base in ["point_diff", "points_for", "points_against"]:
        std_col = f"diff_r10_std_{base}"
        if std_col in out.columns:
            out[f"volatility_{base}"] = _num_or_nan(out, std_col)

    point_diff_a = _first_existing_team_col(out, ["r10_mean_point_diff_TA", "r10_mean_point_diff_A"])
    point_diff_b = _first_existing_team_col(out, ["r10_mean_point_diff_TB", "r10_mean_point_diff_B"])
    point_std_a = _first_existing_team_col(out, ["r10_std_point_diff_TA", "r10_std_point_diff_A"])
    point_std_b = _first_existing_team_col(out, ["r10_std_point_diff_TB", "r10_std_point_diff_B"])
    if point_diff_a and point_diff_b:
        a_pd = _num_or_nan(out, point_diff_a)
        b_pd = _num_or_nan(out, point_diff_b)
        if point_std_a and point_std_b:
            a_blow = (a_pd - _num_or_nan(out, point_std_a)).clip(lower=0)
            b_blow = (b_pd - _num_or_nan(out, point_std_b)).clip(lower=0)
            out["blowout_tendency_diff"] = a_blow - b_blow
        else:
            out["blowout_tendency_diff"] = a_pd - b_pd
    elif {"diff_r10_mean_point_diff", "diff_r10_std_point_diff"}.issubset(out.columns):
        out["blowout_tendency_diff"] = _num_or_nan(out, "diff_r10_mean_point_diff") - 0.5 * _num_or_nan(out, "diff_r10_std_point_diff")

    poss_a = _first_existing_team_col(out, [
        "r10_mean_possessions_TA", "r10_mean_estimated_possessions_TA", "r10_mean_pace_TA"
    ])
    poss_b = _first_existing_team_col(out, [
        "r10_mean_possessions_TB", "r10_mean_estimated_possessions_TB", "r10_mean_pace_TB"
    ])
    pf_a = _first_existing_team_col(out, ["r10_mean_points_for_TA"])
    pf_b = _first_existing_team_col(out, ["r10_mean_points_for_TB"])
    pa_a = _first_existing_team_col(out, ["r10_mean_points_against_TA"])
    pa_b = _first_existing_team_col(out, ["r10_mean_points_against_TB"])

    if poss_a and poss_b:
        possA = _num_or_nan(out, poss_a)
        possB = _num_or_nan(out, poss_b)
        out["pace_diff"] = possA - possB

        if pf_a and pf_b:
            off_eff_a = 100.0 * _num_or_nan(out, pf_a) / possA.replace(0, np.nan)
            off_eff_b = 100.0 * _num_or_nan(out, pf_b) / possB.replace(0, np.nan)
            out["off_eff_diff"] = off_eff_a - off_eff_b

        if pa_a and pa_b:
            def_eff_a = 100.0 * _num_or_nan(out, pa_a) / possA.replace(0, np.nan)
            def_eff_b = 100.0 * _num_or_nan(out, pa_b) / possB.replace(0, np.nan)
            out["def_eff_diff"] = def_eff_a - def_eff_b

        fga_a = _first_existing_team_col(out, ["r10_mean_field_goals_attempted_TA", "r10_mean_field_goals_attempted_A"])
        fga_b = _first_existing_team_col(out, ["r10_mean_field_goals_attempted_TB", "r10_mean_field_goals_attempted_B"])
        fgm_a = _first_existing_team_col(out, ["r10_mean_field_goals_made_TA", "r10_mean_field_goals_made_A"])
        fgm_b = _first_existing_team_col(out, ["r10_mean_field_goals_made_TB", "r10_mean_field_goals_made_B"])
        tpa_a = _first_existing_team_col(out, ["r10_mean_three_point_field_goals_attempted_TA", "r10_mean_three_point_field_goals_attempted_A"])
        tpa_b = _first_existing_team_col(out, ["r10_mean_three_point_field_goals_attempted_TB", "r10_mean_three_point_field_goals_attempted_B"])
        tpm_a = _first_existing_team_col(out, ["r10_mean_three_point_field_goals_made_TA", "r10_mean_three_point_field_goals_made_A"])
        tpm_b = _first_existing_team_col(out, ["r10_mean_three_point_field_goals_made_TB", "r10_mean_three_point_field_goals_made_B"])
        fta_a = _first_existing_team_col(out, ["r10_mean_free_throws_attempted_TA", "r10_mean_free_throws_attempted_A"])
        fta_b = _first_existing_team_col(out, ["r10_mean_free_throws_attempted_TB", "r10_mean_free_throws_attempted_B"])
        tov_a = _first_existing_team_col(out, ["r10_mean_turnovers_TA", "r10_mean_team_turnovers_A", "r10_mean_turnovers_A"])
        tov_b = _first_existing_team_col(out, ["r10_mean_turnovers_TB", "r10_mean_team_turnovers_B", "r10_mean_turnovers_B"])
        ast_a = _first_existing_team_col(out, ["r10_mean_assists_TA", "r10_mean_assists_A"])
        ast_b = _first_existing_team_col(out, ["r10_mean_assists_TB", "r10_mean_assists_B"])
        orb_a = _first_existing_team_col(out, ["r10_mean_offensive_rebounds_TA", "r10_mean_offensive_rebounds_A"])
        orb_b = _first_existing_team_col(out, ["r10_mean_offensive_rebounds_TB", "r10_mean_offensive_rebounds_B"])
        drb_a = _first_existing_team_col(out, ["r10_mean_defensive_rebounds_TA", "r10_mean_defensive_rebounds_A"])
        drb_b = _first_existing_team_col(out, ["r10_mean_defensive_rebounds_TB", "r10_mean_defensive_rebounds_B"])
        stl_a = _first_existing_team_col(out, ["r10_mean_steals_TA", "r10_mean_steals_A"])
        stl_b = _first_existing_team_col(out, ["r10_mean_steals_TB", "r10_mean_steals_B"])
        blk_a = _first_existing_team_col(out, ["r10_mean_blocks_TA", "r10_mean_blocks_A"])
        blk_b = _first_existing_team_col(out, ["r10_mean_blocks_TB", "r10_mean_blocks_B"])

        if all([fga_a, fga_b, fgm_a, fgm_b, tpm_a, tpm_b]):
            efg_a = _safe_rate(_num_or_nan(out, fgm_a) + 0.5 * _num_or_nan(out, tpm_a), _num_or_nan(out, fga_a))
            efg_b = _safe_rate(_num_or_nan(out, fgm_b) + 0.5 * _num_or_nan(out, tpm_b), _num_or_nan(out, fga_b))
            out["shooting_efficiency_diff"] = efg_a - efg_b

        if all([pf_a, pf_b, fga_a, fga_b, fta_a, fta_b]):
            ts_a = _safe_rate(_num_or_nan(out, pf_a), 2.0 * (_num_or_nan(out, fga_a) + 0.44 * _num_or_nan(out, fta_a)))
            ts_b = _safe_rate(_num_or_nan(out, pf_b), 2.0 * (_num_or_nan(out, fga_b) + 0.44 * _num_or_nan(out, fta_b)))
            out["true_shooting_diff"] = ts_a - ts_b

        if all([tpa_a, tpa_b, fga_a, fga_b]):
            tpa_rate_a = _safe_rate(_num_or_nan(out, tpa_a), _num_or_nan(out, fga_a))
            tpa_rate_b = _safe_rate(_num_or_nan(out, tpa_b), _num_or_nan(out, fga_b))
            out["three_point_rate_diff"] = tpa_rate_a - tpa_rate_b

        if all([fta_a, fta_b, fga_a, fga_b]):
            ft_rate_a = _safe_rate(_num_or_nan(out, fta_a), _num_or_nan(out, fga_a))
            ft_rate_b = _safe_rate(_num_or_nan(out, fta_b), _num_or_nan(out, fga_b))
            out["free_throw_rate_diff"] = ft_rate_a - ft_rate_b

        if all([tov_a, tov_b]):
            tov_rate_a = _safe_rate(_num_or_nan(out, tov_a), possA)
            tov_rate_b = _safe_rate(_num_or_nan(out, tov_b), possB)
            out["turnover_rate_diff"] = tov_rate_a - tov_rate_b

        if all([ast_a, ast_b, fgm_a, fgm_b]):
            ast_rate_a = _safe_rate(_num_or_nan(out, ast_a), _num_or_nan(out, fgm_a))
            ast_rate_b = _safe_rate(_num_or_nan(out, ast_b), _num_or_nan(out, fgm_b))
            out["assist_rate_diff"] = ast_rate_a - ast_rate_b

        if all([orb_a, orb_b, drb_a, drb_b]):
            orb_rate_a = _safe_rate(_num_or_nan(out, orb_a), _num_or_nan(out, orb_a) + _num_or_nan(out, drb_b))
            orb_rate_b = _safe_rate(_num_or_nan(out, orb_b), _num_or_nan(out, orb_b) + _num_or_nan(out, drb_a))
            drb_rate_a = _safe_rate(_num_or_nan(out, drb_a), _num_or_nan(out, drb_a) + _num_or_nan(out, orb_b))
            drb_rate_b = _safe_rate(_num_or_nan(out, drb_b), _num_or_nan(out, drb_b) + _num_or_nan(out, orb_a))
            out["off_rebound_rate_diff"] = orb_rate_a - orb_rate_b
            out["def_rebound_rate_diff"] = drb_rate_a - drb_rate_b

        if all([stl_a, stl_b]):
            stl_rate_a = _safe_rate(_num_or_nan(out, stl_a), possA)
            stl_rate_b = _safe_rate(_num_or_nan(out, stl_b), possB)
            out["steal_rate_diff"] = stl_rate_a - stl_rate_b

        if all([blk_a, blk_b]):
            blk_rate_a = _safe_rate(_num_or_nan(out, blk_a), possA)
            blk_rate_b = _safe_rate(_num_or_nan(out, blk_b), possB)
            out["block_rate_diff"] = blk_rate_a - blk_rate_b

        if "off_eff_diff" in out.columns and "def_eff_diff" in out.columns:
            out["matchup_off_edge"] = 0.5 * out["off_eff_diff"] - 0.5 * out["def_eff_diff"]
            out["efficiency_matchup_edge"] = out["off_eff_diff"] - out["def_eff_diff"]

        if all([pf_a, pf_b, pa_a, pa_b]):
            out["opponent_adjusted_scoring_edge"] = (
                (_num_or_nan(out, pf_a) - _num_or_nan(out, pa_b)) -
                (_num_or_nan(out, pf_b) - _num_or_nan(out, pa_a))
            )

        if "three_point_rate_diff" in out.columns and "free_throw_rate_diff" in out.columns and "turnover_rate_diff" in out.columns:
            out["shot_profile_edge"] = (
                0.8 * _num_or_nan(out, "three_point_rate_diff") +
                0.6 * _num_or_nan(out, "free_throw_rate_diff") -
                0.8 * _num_or_nan(out, "turnover_rate_diff")
            )

    return out

# ============================================================
# CELL 8b: SAFETY PATCH FOR DOWNSTREAM
# ============================================================
def normalize_board_for_downstream(board: pd.DataFrame) -> pd.DataFrame:
    b = ensure_board_team_columns(board)

    # keep these mirrored so old code doesn't break
    if "home_short_display_name" not in b.columns:
        b["home_short_display_name"] = b["home_team"]
    if "away_short_display_name" not in b.columns:
        b["away_short_display_name"] = b["away_team"]

    return b



# ============================================================
# CELL 9: TRAINING DATASET BUILDER (FULL REWRITE)
# ============================================================

def build_game_dataset_from_team_box(
    team_box: pd.DataFrame,
    schedule_df: pd.DataFrame,
    window: int = ROLL_WINDOW,
    elo_df: pd.DataFrame = None,
    team_snaps: pd.DataFrame = None,
    precomputed_roll_cols: list = None,
) -> pd.DataFrame:
    """
    Builds the per-game labeled dataset for model training.
    TeamA = min(team_id, opponent_team_id), TeamB = max.
    y_margin = TeamA score - TeamB score.
    y_win    = 1 if TeamA wins.

    Includes:
    - rolling diff features
    - Elo diff
    - home_court_A
    """
    tb = team_box.copy()
    tb["game_id"] = tb["game_id"].astype(str)
    tb["game_date_time"] = pd.to_datetime(tb["game_date_time"], errors="coerce", utc=True)
    tb["team_id"] = pd.to_numeric(tb["team_id"], errors="coerce")
    tb["opponent_team_id"] = pd.to_numeric(tb["opponent_team_id"], errors="coerce")
    tb["team_score"] = pd.to_numeric(tb["team_score"], errors="coerce")
    tb["opp_score"] = pd.to_numeric(tb["opponent_team_score"], errors="coerce")

    tb = tb.dropna(subset=[
        "team_id", "opponent_team_id", "team_score", "opp_score", "game_date_time"
    ]).copy()

    tb["team_id"] = tb["team_id"].astype(int)
    tb["opponent_team_id"] = tb["opponent_team_id"].astype(int)
    tb["game_dt_et"] = tb["game_date_time"].dt.tz_convert("America/New_York").dt.tz_localize(None)

    exclude = {
        "game_id", "season", "season_type", "game_date", "game_date_time", "game_dt_et",
        "team_id", "team_uid", "opponent_team_id", "opponent_team_uid",
        "team_score", "opp_score", "opponent_team_score",
    }

    num_cols = [
        c for c in tb.columns
        if c not in exclude
        and not str(c).startswith("opponent_")
        and pd.api.types.is_numeric_dtype(tb[c])
    ]

    for c in num_cols:
        tb[c] = pd.to_numeric(tb[c], errors="coerce")

    tb = tb.sort_values(["team_id", "game_dt_et"]).copy()

    # check_and_retrain() already computed these leakage-safe snapshots for
    # the prediction board. Reuse them here instead of recalculating 3 rolling
    # windows for every numeric column a second time.
    supplied_roll_cols = [
        c for c in (precomputed_roll_cols or [])
        if c in (team_snaps.columns if team_snaps is not None else [])
    ]
    if team_snaps is not None and len(team_snaps) > 0 and supplied_roll_cols:
        snap_cols = ["game_id", "team_id"] + supplied_roll_cols
        snap = team_snaps[snap_cols].copy()
        snap["game_id"] = snap["game_id"].astype(str)
        snap["team_id"] = pd.to_numeric(snap["team_id"], errors="coerce")
        snap = snap.dropna(subset=["game_id", "team_id"])
        snap["team_id"] = snap["team_id"].astype(int)
        snap = snap.drop_duplicates(["game_id", "team_id"], keep="last")
        tb = tb.drop(columns=supplied_roll_cols, errors="ignore")
        tb = tb.merge(snap, on=["game_id", "team_id"], how="left", sort=False)
        roll_cols = supplied_roll_cols
    else:
        roll_data = {}
        for c in num_cols:
            roll_data[f"r{window}_mean_{c}"] = (
                tb.groupby("team_id")[c]
                  .rolling(window, min_periods=3).mean()
                  .shift(1).reset_index(level=0, drop=True)
            )
            roll_data[f"r3_mean_{c}"] = (
                tb.groupby("team_id")[c]
                  .rolling(3, min_periods=2).mean()
                  .shift(1).reset_index(level=0, drop=True)
            )
            roll_data[f"r{window}_std_{c}"] = (
                tb.groupby("team_id")[c]
                  .rolling(window, min_periods=3).std()
                  .shift(1).reset_index(level=0, drop=True)
            )

        roll_data[f"r{window}_gp"] = (
            tb.groupby("team_id")["team_id"]
              .rolling(window, min_periods=1).count()
              .shift(1).reset_index(level=0, drop=True)
        )

        for k, v in roll_data.items():
            tb[k] = v

        roll_cols = list(roll_data.keys())

    lo = np.minimum(tb["team_id"], tb["opponent_team_id"])
    hi = np.maximum(tb["team_id"], tb["opponent_team_id"])
    tb["teamA_id"] = lo
    tb["teamB_id"] = hi
    tb["teamA_is_team"] = (tb["team_id"] == tb["teamA_id"])

    A = tb[tb["teamA_is_team"]].copy()
    B = tb[~tb["teamA_is_team"]].copy()

    keep_A = ["game_id", "season", "game_dt_et", "teamA_id", "teamB_id", "team_score", "opp_score"] + roll_cols
    keep_B = ["game_id"] + roll_cols

    A = A[[c for c in keep_A if c in A.columns]].copy()
    B = B[[c for c in keep_B if c in B.columns]].copy()

    A = A.rename(columns={c: f"{c}_A" for c in roll_cols})
    B = B.rename(columns={c: f"{c}_B" for c in roll_cols})

    merged = A.merge(B, on="game_id", how="inner")

    merged["y_margin"] = merged["team_score"] - merged["opp_score"]
    merged["y_win"] = (merged["y_margin"] > 0).astype(int)

    diff_cols = []
    for c in roll_cols:
        ca, cb = f"{c}_A", f"{c}_B"
        if ca in merged.columns and cb in merged.columns:
            dc = f"diff_{c}"
            merged[dc] = merged[ca] - merged[cb]
            diff_cols.append(dc)

    if elo_df is not None and len(elo_df) > 0:
        elo_map = (
            elo_df.sort_values(["team_id", "game_dt_et"])
                  .drop_duplicates(subset=["game_id", "team_id"], keep="last")
                  .set_index(["game_id", "team_id"])["elo_before"]
        )

        def _get_elo(gid, tid, default=ELO_INIT):
            try:
                return float(elo_map.loc[(str(gid), int(tid))])
            except Exception:
                return default

        merged["elo_A"] = [_get_elo(r["game_id"], r["teamA_id"]) for _, r in merged.iterrows()]
        merged["elo_B"] = [_get_elo(r["game_id"], r["teamB_id"]) for _, r in merged.iterrows()]
        merged["diff_elo"] = merged["elo_A"] - merged["elo_B"]
        diff_cols.append("diff_elo")

    sched = schedule_df.copy()
    sched["game_id"] = sched["game_id"].astype(str)
    sched["home_id"] = pd.to_numeric(sched.get("home_id"), errors="coerce")
    sched["away_id"] = pd.to_numeric(sched.get("away_id"), errors="coerce")

    sched = ensure_board_team_columns(sched)

    keep_sched = [c for c in [
        "game_id", "home_id", "away_id", "neutral_site", "season_type",
        "home_team", "away_team", "home_short_display_name", "away_short_display_name",
        "status_type_name", "status_type_short_detail", "note", "notes",
        "game_note", "game_name", "name", "event_name", "game_dt_et", "game_date_time"
    ] if c in sched.columns]
    sched = sched[keep_sched].copy()

    merged = merged.merge(sched, on="game_id", how="left")
    merged = _coerce_schedule_tournament_flags(merged, debug_key="training_dataset")

    neutral = merged.get("neutral_site", pd.Series(False, index=merged.index))
    if neutral.dtype == object:
        neutral = neutral.astype(str).str.lower().isin(["true", "1", "yes", "y"])

    teamA_is_home = merged["teamA_id"] == pd.to_numeric(merged["home_id"], errors="coerce")
    merged["home_court_A"] = np.where(neutral, 0, np.where(teamA_is_home, 1, -1)).astype(float)
    diff_cols.append("home_court_A")
    merged["actual_home_margin"] = np.where(teamA_is_home, merged["y_margin"], -merged["y_margin"]).astype(float)

    merged = attach_injury_features_by_row_date(merged, INJURY_DIR, date_col="game_dt_et")
    merged = attach_rotowire_features_by_row_date(merged, date_col="game_dt_et")
    merged = _add_hybrid_spread_features(merged)
    for c in ["diff_injury_impact", "diff_inj_out"]:
        if c in merged.columns:
            diff_cols.append(c)

    merged[diff_cols] = merged[diff_cols].fillna(0.0)

    spread_extra_cols = [
        c for c in [
            "actual_home_margin",
            "vegas_spread_home", "has_market_spread", "market_abs_spread", "market_home_fav",
            "vegas_total", "has_market_total",
            "rest_diff", "neutral_site_flag", "neutral_tourney_flag",
            "trend_points_for", "trend_points_against", "trend_point_diff",
            "trend_field_goal_pct", "trend_three_point_field_goal_pct", "trend_free_throw_pct",
            "trend_total_rebounds", "trend_offensive_rebounds", "trend_turnovers", "trend_steals", "trend_blocks",
            "volatility_point_diff", "volatility_points_for", "volatility_points_against",
            "blowout_tendency_diff", "pace_diff", "off_eff_diff", "def_eff_diff",
            "shooting_efficiency_diff", "true_shooting_diff", "three_point_rate_diff", "free_throw_rate_diff",
            "turnover_rate_diff", "assist_rate_diff", "off_rebound_rate_diff", "def_rebound_rate_diff",
            "steal_rate_diff", "block_rate_diff", "matchup_off_edge", "efficiency_matchup_edge",
            "opponent_adjusted_scoring_edge", "shot_profile_edge",
        ] if c in merged.columns
    ]

    keep = [
        "game_id", "season", "game_dt_et", "teamA_id", "teamB_id",
        "home_id", "away_id",
        "y_margin", "y_win"
    ] + diff_cols + spread_extra_cols + [c for c in ["is_tournament", "is_conf_tourney", "is_ncaa_tourney"] if c in merged.columns]

    return merged[[c for c in keep if c in merged.columns]].copy()


# ============================================================
# CELL 10: MODEL TRAINING (FULL REWRITE)
# ============================================================

SEASON_WEIGHT_DECAY_RATE = 0.5


def season_weights(season_series, current_season=CURRENT_SEASON, decay_rate: float = SEASON_WEIGHT_DECAY_RATE):
    season_vals = pd.to_numeric(season_series, errors="coerce").fillna(current_season).astype(float)
    age = (float(current_season) - season_vals).clip(lower=0)
    return np.exp(-float(decay_rate) * age).astype(float).values


def _print_sample_weight_debug(
    season_series,
    raw_weights,
    final_weights,
    label: str = "training",
):
    seasons = pd.to_numeric(pd.Series(season_series).reset_index(drop=True), errors="coerce")
    raw_w = pd.to_numeric(pd.Series(raw_weights).reset_index(drop=True), errors="coerce")
    final_w = pd.to_numeric(pd.Series(final_weights).reset_index(drop=True), errors="coerce")
    dbg = pd.DataFrame({
        "season": seasons,
        "raw_weight": raw_w,
        "final_weight": final_w,
    }).dropna(subset=["season"]).copy()

    if len(dbg) == 0:
        print(f"{label.title()} sample weights: no valid season rows available")
        return

    dbg["season"] = dbg["season"].astype(int)
    season_summary = (
        dbg.groupby("season", as_index=False)
        .agg(
            rows=("season", "size"),
            raw_mean=("raw_weight", "mean"),
            raw_min=("raw_weight", "min"),
            raw_max=("raw_weight", "max"),
            final_mean=("final_weight", "mean"),
            final_min=("final_weight", "min"),
            final_max=("final_weight", "max"),
            zero_rows=("final_weight", lambda s: int(np.isclose(pd.to_numeric(s, errors="coerce").fillna(0.0), 0.0).sum())),
        )
        .sort_values("season")
    )

    lines = [f"{label.title()} season weight summary:"]
    for _, row in season_summary.iterrows():
        lines.append(
            f"{int(row['season'])}: rows={int(row['rows'])} "
            f"raw_mean={float(row['raw_mean']):.4f} raw_min={float(row['raw_min']):.4f} raw_max={float(row['raw_max']):.4f} "
            f"final_mean={float(row['final_mean']):.4f} final_min={float(row['final_min']):.4f} final_max={float(row['final_max']):.4f}"
        )
        if int(row["zero_rows"]) >= int(row["rows"]):
            lines.append(f"WARNING: season {int(row['season'])} has all-zero sample weights")

    global_min = float(final_w.min()) if len(final_w) else float("nan")
    global_max = float(final_w.max()) if len(final_w) else float("nan")
    zero_rows = int(np.isclose(final_w.fillna(0.0), 0.0).sum()) if len(final_w) else 0
    lines.append(f"Global weights: min={global_min:.4f} max={global_max:.4f} zero_rows={zero_rows}")
    print("\n".join(lines))


def _get_ats_edge_threshold(default: float = ATS_EDGE_THRESHOLD) -> float:
    try:
        return float(globals().get("ATS_EDGE_THRESHOLD", default))
    except Exception:
        return float(default)


def _get_spread_ensemble_weight(default: float = SPREAD_ENSEMBLE_WEIGHT_LGB) -> float:
    try:
        return float(globals().get("SPREAD_ENSEMBLE_WEIGHT_LGB", default))
    except Exception:
        return float(default)


def _get_market_blend(default: float = MARKET_BLEND) -> float:
    try:
        return float(globals().get("MARKET_BLEND", default))
    except Exception:
        return float(default)


def _summarize_spread_predictions(pred_margin_home, actual_home_margin, vegas_spread_home=None) -> dict:
    pred = pd.to_numeric(pd.Series(pred_margin_home), errors="coerce")
    actual = pd.to_numeric(pd.Series(actual_home_margin), errors="coerce")
    valid = pred.notna() & actual.notna()
    if not valid.any():
        return {
            "games": 0,
            "cover_acc": np.nan,
            "side_acc": np.nan,
            "mae": np.nan,
            "within3": np.nan,
            "within5": np.nan,
            "ats_acc": np.nan,
            "ats_games": 0,
        }

    pred_v = pred[valid].to_numpy(dtype=float)
    actual_v = actual[valid].to_numpy(dtype=float)
    err = np.abs(pred_v - actual_v)
    summary = {
        "games": int(valid.sum()),
        "cover_acc": float(np.mean(np.where(pred_v > 0, actual_v > pred_v, np.where(pred_v < 0, actual_v < pred_v, actual_v == 0)))),
        "side_acc": float(np.mean(np.where(pred_v > 0, actual_v > 0, np.where(pred_v < 0, actual_v < 0, actual_v == 0)))),
        "mae": float(np.mean(err)),
        "within3": float(np.mean(err <= 3.0)),
        "within5": float(np.mean(err <= 5.0)),
        "ats_acc": np.nan,
        "ats_games": 0,
    }
    if vegas_spread_home is not None:
        rw = pd.to_numeric(pd.Series(vegas_spread_home), errors="coerce")
        rw = rw.reindex(pred.index)
        ats_valid = valid & rw.notna()
        if ats_valid.any():
            cover = actual[ats_valid].to_numpy(dtype=float) + rw[ats_valid].to_numpy(dtype=float)
            edge = pred[ats_valid].to_numpy(dtype=float) + rw[ats_valid].to_numpy(dtype=float)
            non_push = np.abs(cover) > 1e-9
            if non_push.any():
                cover = cover[non_push]
                edge = edge[non_push]
                summary["ats_acc"] = float(np.mean(np.where(edge > 0, cover > 0, cover < 0)))
                summary["ats_games"] = int(len(cover))
    return summary


def _spread_selection_score(summary: dict) -> float:
    cover_acc = float(summary.get("cover_acc", np.nan))
    side_acc = float(summary.get("side_acc", np.nan))
    within5 = float(summary.get("within5", np.nan))
    mae = float(summary.get("mae", np.nan))
    ats_acc = float(summary.get("ats_acc", np.nan))
    ats_games = int(summary.get("ats_games", 0) or 0)
    score = 0.0
    if np.isfinite(cover_acc):
        score += 100.0 * cover_acc
    if np.isfinite(side_acc):
        score += 40.0 * side_acc
    if np.isfinite(within5):
        score += 20.0 * within5
    if np.isfinite(mae):
        score -= 2.5 * mae
    if np.isfinite(ats_acc) and ats_games >= 75:
        score += 18.0 * ats_acc
    return float(score)


def _select_spread_ensemble_weight(xgb_pred_ab, lgb_pred_ab, teamA_is_home, actual_home_margin, thresholds=None) -> tuple[float, dict]:
    candidates = thresholds or SPREAD_ENSEMBLE_CANDIDATES
    best_weight = float(_get_spread_ensemble_weight())
    best_summary = {}
    best_score = float("-inf")
    summaries = {}
    xgb_pred_ab = np.asarray(xgb_pred_ab, dtype=float)
    lgb_pred_ab = np.asarray(lgb_pred_ab, dtype=float)
    teamA_is_home = np.asarray(teamA_is_home, dtype=bool)
    actual_home_margin = np.asarray(actual_home_margin, dtype=float)
    for weight in candidates:
        pred_ab = (1.0 - float(weight)) * xgb_pred_ab + float(weight) * lgb_pred_ab
        pred_home = np.where(teamA_is_home, pred_ab, -pred_ab)
        summary = _summarize_spread_predictions(pred_home, actual_home_margin)
        summaries[float(weight)] = summary
        score = _spread_selection_score(summary)
        if score > best_score:
            best_score = score
            best_weight = float(weight)
            best_summary = summary
    return best_weight, {"best_summary": best_summary, "candidates": summaries}


def _select_market_blend(market_margin_home, market_implied_home_margin, actual_home_margin, vegas_spread_home, thresholds=None) -> tuple[float, dict]:
    candidates = thresholds or MARKET_BLEND_CANDIDATES
    best_blend = float(_get_market_blend())
    best_summary = {}
    best_score = float("-inf")
    summaries = {}
    market_margin_home = np.asarray(market_margin_home, dtype=float)
    market_implied_home_margin = np.asarray(market_implied_home_margin, dtype=float)
    actual_home_margin = np.asarray(actual_home_margin, dtype=float)
    vegas_spread_home = np.asarray(vegas_spread_home, dtype=float)
    for blend in candidates:
        pred_home = (1.0 - float(blend)) * market_margin_home + float(blend) * market_implied_home_margin
        summary = _summarize_spread_predictions(pred_home, actual_home_margin, vegas_spread_home=vegas_spread_home)
        summaries[float(blend)] = summary
        score = _spread_selection_score(summary)
        if score > best_score:
            best_score = score
            best_blend = float(blend)
            best_summary = summary
    return best_blend, {"best_summary": best_summary, "candidates": summaries}


def _wilson_lower_bound(wins: int, total: int, z: float = 1.0) -> float:
    if total <= 0:
        return float("-inf")
    p = float(wins) / float(total)
    denom = 1.0 + (z * z) / total
    center = p + (z * z) / (2.0 * total)
    adj = z * np.sqrt((p * (1.0 - p) + (z * z) / (4.0 * total)) / total)
    return float((center - adj) / denom)


def _build_ats_backtest_frame(
    pred_margin_home,
    actual_home_margin,
    vegas_spread_home,
    game_dt=None,
) -> pd.DataFrame:
    backtest = pd.DataFrame({
        "pred_margin_home": pd.to_numeric(pd.Series(pred_margin_home).reset_index(drop=True), errors="coerce"),
        "actual_home_margin": pd.to_numeric(pd.Series(actual_home_margin).reset_index(drop=True), errors="coerce"),
        "vegas_spread_home": pd.to_numeric(pd.Series(vegas_spread_home).reset_index(drop=True), errors="coerce"),
    })
    if game_dt is not None:
        backtest["game_dt_et"] = pd.to_datetime(pd.Series(game_dt).reset_index(drop=True), errors="coerce")
    else:
        backtest["game_dt_et"] = pd.NaT

    backtest = backtest.dropna(subset=["pred_margin_home", "actual_home_margin", "vegas_spread_home"]).copy()
    if len(backtest) == 0:
        return backtest

    backtest["edge"] = backtest["pred_margin_home"] + backtest["vegas_spread_home"]
    backtest["cover_margin"] = backtest["actual_home_margin"] + backtest["vegas_spread_home"]
    backtest = backtest[backtest["cover_margin"] != 0].copy()
    if len(backtest) == 0:
        return backtest

    backtest["abs_edge"] = backtest["edge"].abs()
    backtest["ats_win"] = np.where(backtest["edge"] > 0, backtest["cover_margin"] > 0, backtest["cover_margin"] < 0).astype(int)
    return backtest.reset_index(drop=True)


def _summarize_ats_threshold(backtest: pd.DataFrame, threshold: float) -> dict:
    threshold = float(threshold)
    if backtest is None or len(backtest) == 0:
        return {
            "threshold": threshold,
            "games": 0,
            "wins": 0,
            "ats_acc": np.nan,
            "lower_bound": float("-inf"),
            "avg_abs_edge": np.nan,
        }

    sample = backtest[backtest["abs_edge"] >= threshold].copy()
    total = int(len(sample))
    if total == 0:
        return {
            "threshold": threshold,
            "games": 0,
            "wins": 0,
            "ats_acc": np.nan,
            "lower_bound": float("-inf"),
            "avg_abs_edge": np.nan,
        }

    wins = int(pd.to_numeric(sample["ats_win"], errors="coerce").fillna(0).sum())
    acc = float(wins / total)
    return {
        "threshold": threshold,
        "games": total,
        "wins": wins,
        "ats_acc": acc,
        "lower_bound": _wilson_lower_bound(wins, total, z=1.0),
        "avg_abs_edge": float(pd.to_numeric(sample["abs_edge"], errors="coerce").mean()),
    }


def _select_best_ats_threshold(
    backtest: pd.DataFrame,
    thresholds=None,
    min_games: int = ATS_EDGE_MIN_GAMES,
) -> tuple[float, list[dict]]:
    thresholds = [float(t) for t in (thresholds or ATS_EDGE_CANDIDATES)]
    summaries = [_summarize_ats_threshold(backtest, t) for t in thresholds]
    eligible = [s for s in summaries if s["games"] >= int(min_games)]
    if not eligible:
        eligible = [s for s in summaries if s["games"] > 0]
    if not eligible:
        return float(_get_ats_edge_threshold()), summaries

    best = max(
        eligible,
        key=lambda s: (
            float(s["lower_bound"]),
            float(s["ats_acc"]) if pd.notna(s["ats_acc"]) else float("-inf"),
            int(s["games"]),
            float(s["threshold"]),
        ),
    )
    return float(best["threshold"]), summaries


def _walk_forward_threshold_tuning(
    backtest: pd.DataFrame,
    thresholds=None,
    min_games: int = ATS_EDGE_MIN_GAMES,
) -> dict:
    thresholds = [float(t) for t in (thresholds or ATS_EDGE_CANDIDATES)]
    empty = {
        "selected_threshold": float(_get_ats_edge_threshold()),
        "selected_summary": _summarize_ats_threshold(backtest, _get_ats_edge_threshold()),
        "candidate_summaries": [_summarize_ats_threshold(backtest, t) for t in thresholds],
        "folds": [],
        "walk_forward_acc": np.nan,
        "walk_forward_games": 0,
    }
    if backtest is None or len(backtest) < max(20, int(min_games)):
        return empty

    work = backtest.copy()
    if "game_dt_et" not in work.columns or work["game_dt_et"].isna().all():
        return empty

    work["game_day"] = pd.to_datetime(work["game_dt_et"], errors="coerce").dt.floor("D")
    work = work.dropna(subset=["game_day"]).sort_values("game_day").reset_index(drop=True)
    unique_days = work["game_day"].drop_duplicates().tolist()
    if len(unique_days) < 6:
        return empty

    n_chunks = min(5, len(unique_days))
    day_chunks = [list(chunk) for chunk in np.array_split(unique_days, n_chunks) if len(chunk) > 0]
    if len(day_chunks) < 3:
        return empty

    fold_rows = []
    wf_wins = 0
    wf_games = 0
    for i in range(1, len(day_chunks)):
        tune_days = {d for chunk in day_chunks[:i] for d in chunk}
        test_days = set(day_chunks[i])
        tune_df = work[work["game_day"].isin(tune_days)].copy()
        test_df = work[work["game_day"].isin(test_days)].copy()
        if len(test_df) == 0:
            continue

        chosen_threshold, _ = _select_best_ats_threshold(tune_df, thresholds=thresholds, min_games=min_games)
        test_summary = _summarize_ats_threshold(test_df, chosen_threshold)
        if test_summary["games"] > 0:
            wf_wins += int(test_summary["wins"])
            wf_games += int(test_summary["games"])
        fold_rows.append({
            "fold": int(i),
            "threshold": float(chosen_threshold),
            "games": int(test_summary["games"]),
            "wins": int(test_summary["wins"]),
            "ats_acc": test_summary["ats_acc"],
        })

    selected_threshold, candidate_summaries = _select_best_ats_threshold(work, thresholds=thresholds, min_games=min_games)
    selected_summary = _summarize_ats_threshold(work, selected_threshold)
    return {
        "selected_threshold": float(selected_threshold),
        "selected_summary": selected_summary,
        "candidate_summaries": candidate_summaries,
        "folds": fold_rows,
        "walk_forward_acc": (float(wf_wins / wf_games) if wf_games > 0 else np.nan),
        "walk_forward_games": int(wf_games),
    }


def _fit_winner_isotonic_oof(
    X: pd.DataFrame,
    y: pd.Series,
    weights,
    dates: pd.Series,
    params: dict,
    feature_names: list[str],
    num_boost_round: int = 2500,
    early_stopping_rounds: int = 100,
    min_train_rows: int = 4000,
    n_folds: int = 4,
):
    empty_iso = IsotonicRegression(out_of_bounds="clip")
    work = pd.DataFrame({
        "y": pd.to_numeric(y, errors="coerce"),
        "w": pd.to_numeric(pd.Series(weights).reset_index(drop=True), errors="coerce"),
        "game_dt_et": pd.to_datetime(pd.Series(dates).reset_index(drop=True), errors="coerce"),
    })
    X_work = X.reset_index(drop=True).copy()
    valid = work["y"].notna() & work["game_dt_et"].notna()
    if valid.sum() < max(min_train_rows + 500, 2000):
        return None, "holdout_fallback"

    X_work = X_work.loc[valid].reset_index(drop=True)
    work = work.loc[valid].reset_index(drop=True)
    unique_days = work["game_dt_et"].dt.floor("D").drop_duplicates().tolist()
    if len(unique_days) < n_folds + 2:
        return None, "holdout_fallback"

    day_chunks = [list(chunk) for chunk in np.array_split(unique_days, n_folds + 1) if len(chunk) > 0]
    preds = pd.Series(np.nan, index=work.index, dtype=float)

    for fold_idx in range(1, len(day_chunks)):
        fold_train_days = {d for chunk in day_chunks[:fold_idx] for d in chunk}
        fold_valid_days = set(day_chunks[fold_idx])
        fold_train_mask = work["game_dt_et"].dt.floor("D").isin(fold_train_days)
        fold_valid_mask = work["game_dt_et"].dt.floor("D").isin(fold_valid_days)
        if int(fold_train_mask.sum()) < int(min_train_rows) or int(fold_valid_mask.sum()) < 100:
            continue

        dtrain_fold = xgb.DMatrix(
            X_work.loc[fold_train_mask, feature_names],
            label=work.loc[fold_train_mask, "y"],
            weight=work.loc[fold_train_mask, "w"],
            feature_names=feature_names,
        )
        dvalid_fold = xgb.DMatrix(
            X_work.loc[fold_valid_mask, feature_names],
            label=work.loc[fold_valid_mask, "y"],
            weight=work.loc[fold_valid_mask, "w"],
            feature_names=feature_names,
        )
        booster_fold = xgb.train(
            params=params,
            dtrain=dtrain_fold,
            num_boost_round=num_boost_round,
            evals=[(dvalid_fold, "valid")],
            early_stopping_rounds=early_stopping_rounds,
            verbose_eval=False,
        )
        preds.loc[fold_valid_mask] = booster_fold.predict(
            dvalid_fold,
            iteration_range=(0, booster_fold.best_iteration + 1),
        )

    oof_mask = preds.notna() & work["y"].notna()
    if int(oof_mask.sum()) < 500 or work.loc[oof_mask, "y"].nunique() < 2:
        return None, "holdout_fallback"

    iso = IsotonicRegression(out_of_bounds="clip")
    iso.fit(preds.loc[oof_mask].to_numpy(), work.loc[oof_mask, "y"].to_numpy())
    return iso, f"oof_{int(oof_mask.sum())}_rows"


def _weighted_mean(values, weights=None) -> float:
    vals = np.asarray(values, dtype=float)
    if vals.size == 0:
        return np.nan
    if weights is None:
        return float(np.nanmean(vals))
    w = np.asarray(weights, dtype=float)
    valid = np.isfinite(vals) & np.isfinite(w) & (w > 0)
    if not valid.any():
        return float(np.nanmean(vals))
    return float(np.average(vals[valid], weights=w[valid]))


def train_models(dataset_all: pd.DataFrame, current_season: int = CURRENT_SEASON):
    global ATS_EDGE_THRESHOLD, SPREAD_ENSEMBLE_WEIGHT_LGB, MARKET_BLEND
    """
    Trains:
      1. Raw margin regression fallback (existing path, improved features)
      2. Optional market-edge regression on rows with spread history
      3. Winner model (kept on the existing feature family)
      4. LightGBM companions for spread models
      5. Isotonic calibration on win probability
    """
    train = dataset_all[dataset_all["season"] < current_season].copy()
    current = dataset_all[dataset_all["season"] == current_season].copy()

    if len(train) < 100:
        raise ValueError("Not enough historical training data to fit models.")

    winner_base_cols = [c for c in dataset_all.columns if c.startswith("diff_") or c == "home_court_A"]
    winner_base_cols = [c for c in winner_base_cols if c in train.columns]

    spread_extra_cols = [
        c for c in [
            "rest_diff", "neutral_site_flag", "neutral_tourney_flag",
            "is_tournament", "is_conf_tourney", "is_ncaa_tourney",
            "trend_points_for", "trend_points_against", "trend_point_diff",
            "trend_field_goal_pct", "trend_three_point_field_goal_pct", "trend_free_throw_pct",
            "trend_total_rebounds", "trend_offensive_rebounds", "trend_turnovers", "trend_steals", "trend_blocks",
            "volatility_point_diff", "volatility_points_for", "volatility_points_against",
            "blowout_tendency_diff", "pace_diff", "off_eff_diff", "def_eff_diff",
            "shooting_efficiency_diff", "true_shooting_diff", "three_point_rate_diff", "free_throw_rate_diff",
            "turnover_rate_diff", "assist_rate_diff", "off_rebound_rate_diff", "def_rebound_rate_diff",
            "steal_rate_diff", "block_rate_diff", "matchup_off_edge", "efficiency_matchup_edge",
            "opponent_adjusted_scoring_edge", "shot_profile_edge",
            "vegas_spread_home", "has_market_spread", "market_abs_spread", "market_home_fav",
            "vegas_total", "has_market_total",
        ]
        if c in dataset_all.columns
    ]
    spread_base_cols = list(dict.fromkeys(winner_base_cols + spread_extra_cols))

    for c in spread_base_cols:
        dataset_all[c + "__na"] = dataset_all[c].isna().astype("int8")
        train[c + "__na"] = train[c].isna().astype("int8")
        if len(current) > 0:
            current[c + "__na"] = current[c].isna().astype("int8")

    imp = SimpleImputer(strategy="median")
    train[spread_base_cols] = imp.fit_transform(train[spread_base_cols])
    if len(current) > 0:
        current[spread_base_cols] = imp.transform(current[spread_base_cols])

    spread_feature_cols_all = spread_base_cols + [c + "__na" for c in spread_base_cols]
    winner_feature_cols_all = winner_base_cols + [c + "__na" for c in winner_base_cols]

    var = train[spread_feature_cols_all].var()
    keep_cols = var[var > 1e-8].index.tolist()
    spread_feature_cols = [c for c in spread_feature_cols_all if c in keep_cols]
    winner_feature_cols = [c for c in winner_feature_cols_all if c in keep_cols]

    print(
        "\n".join([
            "MODEL FEATURES",
            f"Winner features after variance filter: {len(winner_feature_cols)}",
            f"Spread features after variance filter: {len(spread_feature_cols)}",
        ])
    )

    train_sorted = train.sort_values("game_dt_et").copy()
    if len(train_sorted) < 500:
        split_n = max(1, int(len(train_sorted) * 0.85))
        tr_idx = train_sorted.iloc[:split_n].index
        va_idx = train_sorted.iloc[split_n:].index
    else:
        cut = train_sorted["game_dt_et"].max() - pd.Timedelta(days=30)
        tr_idx = train_sorted[train_sorted["game_dt_et"] < cut].index
        va_idx = train_sorted[train_sorted["game_dt_et"] >= cut].index
        if len(tr_idx) == 0 or len(va_idx) == 0:
            split_n = max(1, int(len(train_sorted) * 0.85))
            tr_idx = train_sorted.iloc[:split_n].index
            va_idx = train_sorted.iloc[split_n:].index

    X_tr_spread = train.loc[tr_idx, spread_feature_cols].copy()
    X_va_spread = train.loc[va_idx, spread_feature_cols].copy()
    X_tr_winner = train.loc[tr_idx, winner_feature_cols].copy()
    X_va_winner = train.loc[va_idx, winner_feature_cols].copy()

    y_tr_m = train.loc[tr_idx, "y_margin"].clip(-30, 30)
    y_va_m = train.loc[va_idx, "y_margin"].clip(-30, 30)
    y_tr_w = train.loc[tr_idx, "y_win"]
    y_va_w = train.loc[va_idx, "y_win"]

    recency_tr = np.exp(-((train.loc[tr_idx, "game_dt_et"].max() - train.loc[tr_idx, "game_dt_et"]).dt.days.fillna(0).clip(lower=0)) / 120.0)
    recency_va = np.exp(-((train.loc[va_idx, "game_dt_et"].max() - train.loc[va_idx, "game_dt_et"]).dt.days.fillna(0).clip(lower=0)) / 120.0)
    season_w_tr = season_weights(train.loc[tr_idx, "season"], current_season)
    season_w_va = season_weights(train.loc[va_idx, "season"], current_season)
    w_tr = season_w_tr * recency_tr.to_numpy()
    w_va = season_w_va * recency_va.to_numpy()
    w_tr = np.asarray(w_tr, dtype=float)
    w_va = np.asarray(w_va, dtype=float)
    _print_sample_weight_debug(train.loc[tr_idx, "season"], season_w_tr, w_tr, label="training")
    _print_sample_weight_debug(train.loc[va_idx, "season"], season_w_va, w_va, label="validation")

    if len(X_tr_spread) == 0 or len(X_va_spread) == 0:
        raise ValueError("Training/validation split is empty. Check dataset size and split logic.")

    params_reg = {
        "objective": "reg:pseudohubererror",
        "eval_metric": "mae",
        "eta": 0.02,
        "max_depth": 4,
        "min_child_weight": 5,
        "subsample": 0.85,
        "colsample_bytree": 0.80,
        "lambda": 1.5,
        "alpha": 0.1,
        "seed": 42,
    }
    params_clf = {
        "objective": "binary:logistic",
        "eval_metric": "logloss",
        "eta": 0.02,
        "max_depth": 3,
        "min_child_weight": 10,
        "subsample": 0.80,
        "colsample_bytree": 0.75,
        "lambda": 3.0,
        "alpha": 0.5,
        "seed": 42,
    }
    lgb_params = {
        "objective": "huber",
        "alpha": 0.9,
        "metric": "mae",
        "learning_rate": 0.02,
        "num_leaves": 31,
        "min_data_in_leaf": 20,
        "feature_fraction": 0.8,
        "bagging_fraction": 0.85,
        "bagging_freq": 5,
        "lambda_l1": 0.1,
        "lambda_l2": 1.0,
        "verbose": -1,
        "seed": 42,
    }
    lgb_callbacks = [
        lgb.early_stopping(100, verbose=False),
        lgb.log_evaluation(period=-1),
    ]

    dtrain = xgb.DMatrix(X_tr_spread, label=y_tr_m, weight=w_tr, feature_names=spread_feature_cols)
    dvalid = xgb.DMatrix(X_va_spread, label=y_va_m, weight=w_va, feature_names=spread_feature_cols)
    spread_booster = xgb.train(
        params=params_reg,
        dtrain=dtrain,
        num_boost_round=5000,
        evals=[(dvalid, "valid")],
        early_stopping_rounds=150,
        verbose_eval=False,
    )

    dtrain_w = xgb.DMatrix(X_tr_winner, label=y_tr_w, weight=w_tr, feature_names=winner_feature_cols)
    dvalid_w = xgb.DMatrix(X_va_winner, label=y_va_w, weight=w_va, feature_names=winner_feature_cols)
    winner_booster = xgb.train(
        params=params_clf,
        dtrain=dtrain_w,
        num_boost_round=5000,
        evals=[(dvalid_w, "valid")],
        early_stopping_rounds=150,
        verbose_eval=False,
    )

    lgb_train = lgb.Dataset(X_tr_spread, label=y_tr_m, weight=w_tr, feature_name=spread_feature_cols)
    lgb_valid = lgb.Dataset(X_va_spread, label=y_va_m, weight=w_va, reference=lgb_train, feature_name=spread_feature_cols)
    lgb_spread = lgb.train(
        lgb_params,
        lgb_train,
        num_boost_round=3000,
        valid_sets=[lgb_valid],
        callbacks=lgb_callbacks,
    )

    spread_edge_booster = None
    lgb_spread_edge = None
    market_train = train.loc[tr_idx].copy()
    market_valid = train.loc[va_idx].copy()
    market_train = market_train[market_train["vegas_spread_home"].notna()].copy()
    market_valid = market_valid[market_valid["vegas_spread_home"].notna()].copy()
    if len(market_train) >= 75 and len(market_valid) >= 20:
        X_tr_edge = market_train[spread_feature_cols].copy()
        X_va_edge = market_valid[spread_feature_cols].copy()
        y_tr_edge = (market_train["actual_home_margin"] - _market_implied_home_margin(market_train["vegas_spread_home"])).clip(-25, 25)
        y_va_edge = (market_valid["actual_home_margin"] - _market_implied_home_margin(market_valid["vegas_spread_home"])).clip(-25, 25)
        recency_tr_edge = np.exp(-((market_train["game_dt_et"].max() - market_train["game_dt_et"]).dt.days.fillna(0).clip(lower=0)) / 120.0)
        recency_va_edge = np.exp(-((market_valid["game_dt_et"].max() - market_valid["game_dt_et"]).dt.days.fillna(0).clip(lower=0)) / 120.0)
        season_w_tr_edge = season_weights(market_train["season"], current_season)
        season_w_va_edge = season_weights(market_valid["season"], current_season)
        w_tr_edge = season_w_tr_edge * recency_tr_edge.to_numpy()
        w_va_edge = season_w_va_edge * recency_va_edge.to_numpy()
        _print_sample_weight_debug(market_train["season"], season_w_tr_edge, w_tr_edge, label="market-edge training")
        _print_sample_weight_debug(market_valid["season"], season_w_va_edge, w_va_edge, label="market-edge validation")

        dtrain_edge = xgb.DMatrix(X_tr_edge, label=y_tr_edge, weight=w_tr_edge, feature_names=spread_feature_cols)
        dvalid_edge = xgb.DMatrix(X_va_edge, label=y_va_edge, weight=w_va_edge, feature_names=spread_feature_cols)
        spread_edge_booster = xgb.train(
            params=params_reg,
            dtrain=dtrain_edge,
            num_boost_round=4000,
            evals=[(dvalid_edge, "valid")],
            early_stopping_rounds=125,
            verbose_eval=False,
        )

        lgb_train_edge = lgb.Dataset(X_tr_edge, label=y_tr_edge, weight=w_tr_edge, feature_name=spread_feature_cols)
        lgb_valid_edge = lgb.Dataset(X_va_edge, label=y_va_edge, weight=w_va_edge, reference=lgb_train_edge, feature_name=spread_feature_cols)
        lgb_spread_edge = lgb.train(
            lgb_params,
            lgb_train_edge,
            num_boost_round=2500,
            valid_sets=[lgb_valid_edge],
            callbacks=lgb_callbacks,
        )
        print(
            "\n".join([
                "MODEL FIT STATUS",
                f"XGB Raw Margin best_iter: {spread_booster.best_iteration}",
                f"XGB Win best_iter: {winner_booster.best_iteration}",
                f"LGB Raw Margin best_iter: {lgb_spread.best_iteration}",
                f"XGB Market Edge best_iter: {spread_edge_booster.best_iteration}",
                f"LGB Market Edge best_iter: {lgb_spread_edge.best_iteration}",
            ])
        )
    else:
        print(
            "\n".join([
                "MODEL FIT STATUS",
                f"XGB Raw Margin best_iter: {spread_booster.best_iteration}",
                f"XGB Win best_iter: {winner_booster.best_iteration}",
                f"LGB Raw Margin best_iter: {lgb_spread.best_iteration}",
                f"Market spread history is sparse ({len(market_train)} train / {len(market_valid)} valid rows). Using raw-margin fallback model only.",
            ])
        )

    raw_va_w = winner_booster.predict(
        dvalid_w,
        iteration_range=(0, winner_booster.best_iteration + 1)
    )
    recency_train_all = np.exp(-((train["game_dt_et"].max() - train["game_dt_et"]).dt.days.fillna(0).clip(lower=0)) / 120.0)
    season_w_train_all = season_weights(train["season"], current_season)
    w_train_all = np.asarray(season_w_train_all * recency_train_all.to_numpy(), dtype=float)
    iso, calibration_source = _fit_winner_isotonic_oof(
        X=train[winner_feature_cols].copy(),
        y=train["y_win"].copy(),
        weights=w_train_all,
        dates=train["game_dt_et"].copy(),
        params=params_clf,
        feature_names=winner_feature_cols,
        num_boost_round=2500,
        early_stopping_rounds=100,
        min_train_rows=4000,
        n_folds=4,
    )
    if iso is None:
        iso = IsotonicRegression(out_of_bounds="clip")
        iso.fit(raw_va_w, y_va_w.values)
        calibration_source = "single_holdout_fallback"

    raw_va_w_clip = np.clip(np.asarray(raw_va_w, dtype=float), 1e-6, 1 - 1e-6)
    cal_va_w = np.clip(np.asarray(iso.transform(raw_va_w), dtype=float), 1e-6, 1 - 1e-6)
    y_va_w_arr = np.asarray(y_va_w, dtype=float)
    cal_brier = _weighted_mean((cal_va_w - y_va_w_arr) ** 2, w_va)
    raw_brier = _weighted_mean((raw_va_w_clip - y_va_w_arr) ** 2, w_va)
    cal_std = float(np.nanstd(cal_va_w))
    raw_std = float(np.nanstd(raw_va_w_clip))
    if (
        not np.isfinite(cal_brier) or
        (np.isfinite(raw_brier) and cal_brier > raw_brier + 1e-4) or
        (np.isfinite(cal_std) and np.isfinite(raw_std) and raw_std > 1e-6 and cal_std < raw_std * 0.35)
    ):
        iso = None
        calibration_source = f"{calibration_source}_disabled_holdout_guard"

    raw_pred_ab_xgb = spread_booster.predict(dvalid, iteration_range=(0, spread_booster.best_iteration + 1))
    raw_pred_ab_lgb = lgb_spread.predict(X_va_spread.values)
    teamA_is_home_va = (pd.to_numeric(train.loc[va_idx, "teamA_id"], errors="coerce") == pd.to_numeric(train.loc[va_idx, "home_id"], errors="coerce")).to_numpy()
    SPREAD_ENSEMBLE_WEIGHT_LGB, spread_weight_tuning = _select_spread_ensemble_weight(
        raw_pred_ab_xgb,
        raw_pred_ab_lgb,
        teamA_is_home_va,
        np.where(teamA_is_home_va, y_va_m.to_numpy(), -y_va_m.to_numpy()),
    )
    raw_pred_ab = (1.0 - SPREAD_ENSEMBLE_WEIGHT_LGB) * raw_pred_ab_xgb + SPREAD_ENSEMBLE_WEIGHT_LGB * raw_pred_ab_lgb
    raw_pred_home = np.where(teamA_is_home_va, raw_pred_ab, -raw_pred_ab)
    actual_home_margin_va = np.where(teamA_is_home_va, y_va_m.to_numpy(), -y_va_m.to_numpy())
    raw_summary = _summarize_spread_predictions(raw_pred_home, actual_home_margin_va)
    raw_mae = float(raw_summary["mae"])
    raw_w3 = float(raw_summary["within3"])
    raw_w5 = float(raw_summary["within5"])
    calibration_status = (
        f"Isotonic calibration disabled ({calibration_source})"
        if iso is None else
        f"Isotonic calibration fitted ({calibration_source})"
    )
    eval_lines = [
        "MODEL EVAL",
        calibration_status,
        f"Winner calibration holdout Brier: raw={raw_brier:.4f} | calibrated={cal_brier:.4f}",
        f"Spread ensemble LGB weight tuned: {SPREAD_ENSEMBLE_WEIGHT_LGB:.2f}",
        f"Spread validation (raw fallback): MAE={raw_mae:.3f} | within3={raw_w3:.3%} | within5={raw_w5:.3%}",
        f"Spread validation (raw fallback side/cover): side={float(raw_summary['side_acc']):.3%} | cover={float(raw_summary['cover_acc']):.3%}",
    ]

    if spread_edge_booster is not None and lgb_spread_edge is not None and len(market_valid) > 0:
        X_va_edge = market_valid[spread_feature_cols].copy()
        dvalid_edge_eval = xgb.DMatrix(X_va_edge, feature_names=spread_feature_cols)
        edge_pred_xgb = spread_edge_booster.predict(dvalid_edge_eval, iteration_range=(0, spread_edge_booster.best_iteration + 1))
        edge_pred_lgb = lgb_spread_edge.predict(X_va_edge.values)
        market_margin_base = _market_implied_home_margin(market_valid["vegas_spread_home"]).to_numpy(dtype=float)
        market_margin = market_margin_base + ((1.0 - SPREAD_ENSEMBLE_WEIGHT_LGB) * edge_pred_xgb + SPREAD_ENSEMBLE_WEIGHT_LGB * edge_pred_lgb)
        MARKET_BLEND, market_blend_tuning = _select_market_blend(
            market_margin,
            market_margin_base,
            market_valid["actual_home_margin"].to_numpy(),
            market_valid["vegas_spread_home"].to_numpy(),
        )
        edge_pred_home = (1.0 - MARKET_BLEND) * market_margin + MARKET_BLEND * market_margin_base
        actual_home_margin_edge = market_valid["actual_home_margin"].to_numpy()
        edge_summary = _summarize_spread_predictions(
            edge_pred_home,
            actual_home_margin_edge,
            vegas_spread_home=market_valid["vegas_spread_home"].to_numpy(),
        )
        edge_mae = float(edge_summary["mae"])
        edge_w3 = float(edge_summary["within3"])
        edge_w5 = float(edge_summary["within5"])
        raw_pred_home_series = pd.Series(raw_pred_home, index=va_idx, dtype=float)
        raw_market_pred_home = raw_pred_home_series.reindex(market_valid.index).to_numpy(dtype=float)
        raw_market_summary = _summarize_spread_predictions(
            raw_market_pred_home,
            actual_home_margin_edge,
            vegas_spread_home=market_valid["vegas_spread_home"].to_numpy(),
        )
        raw_market_mae = float(raw_market_summary["mae"])
        raw_market_w3 = float(raw_market_summary["within3"])
        raw_market_w5 = float(raw_market_summary["within5"])

        eval_lines.append(f"Spread validation (raw on market rows): MAE={raw_market_mae:.3f} | within3={raw_market_w3:.3%} | within5={raw_market_w5:.3%}")
        eval_lines.append(f"Spread validation (market-aware): MAE={edge_mae:.3f} | within3={edge_w3:.3%} | within5={edge_w5:.3%}")
        eval_lines.append(f"Spread validation (raw on market rows side/cover): side={float(raw_market_summary['side_acc']):.3%} | cover={float(raw_market_summary['cover_acc']):.3%}")
        eval_lines.append(f"Spread validation (market-aware side/cover): side={float(edge_summary['side_acc']):.3%} | cover={float(edge_summary['cover_acc']):.3%}")
        eval_lines.append(f"Market blend tuned: {MARKET_BLEND:.2f}")

        cover = actual_home_margin_edge + market_valid["vegas_spread_home"].to_numpy()
        raw_pred_edge = raw_market_pred_home + market_valid["vegas_spread_home"].to_numpy()
        pred_edge = edge_pred_home + market_valid["vegas_spread_home"].to_numpy()
        raw_ats_mask = np.abs(raw_pred_edge) > 1.0
        ats_mask = np.abs(pred_edge) > 1.0
        raw_ats_rate = np.nan
        raw_ats_games = 0
        if raw_ats_mask.any():
            raw_ats_wins = np.where(raw_pred_edge[raw_ats_mask] > 0, cover[raw_ats_mask] > 0, cover[raw_ats_mask] < 0)
            raw_ats_rate = float(np.mean(raw_ats_wins))
            raw_ats_games = int(raw_ats_mask.sum())
            eval_lines.append(f"ATS validation (raw on market rows, |edge|>1): {raw_ats_rate:.3%} on {raw_ats_games} games")
        else:
            eval_lines.append("ATS validation (raw on market rows, |edge|>1): n/a")
        if ats_mask.any():
            ats_wins = np.where(pred_edge[ats_mask] > 0, cover[ats_mask] > 0, cover[ats_mask] < 0)
            edge_ats_rate = float(np.mean(ats_wins))
            edge_ats_games = int(ats_mask.sum())
            eval_lines.append(f"ATS validation (market-aware, |edge|>1): {edge_ats_rate:.3%} on {edge_ats_games} games")
        else:
            edge_ats_rate = np.nan
            edge_ats_games = 0
            eval_lines.append("ATS validation (market-aware, |edge|>1): n/a")

        keep_market_edge = _spread_selection_score(edge_summary) >= _spread_selection_score(raw_market_summary)
        if keep_market_edge:
            eval_lines.append("Market-edge deployment: enabled (validated improvement over raw spread model)")
        else:
            spread_edge_booster = None
            lgb_spread_edge = None
            eval_lines.append("Market-edge deployment: disabled (raw spread model validated better)")

        deployed_pred_home = edge_pred_home if keep_market_edge else raw_market_pred_home
        threshold_tuning = _walk_forward_threshold_tuning(
            _build_ats_backtest_frame(
                pred_margin_home=deployed_pred_home,
                actual_home_margin=actual_home_margin_edge,
                vegas_spread_home=market_valid["vegas_spread_home"].to_numpy(),
                game_dt=market_valid["game_dt_et"],
            ),
            thresholds=ATS_EDGE_CANDIDATES,
            min_games=ATS_EDGE_MIN_GAMES,
        )
        ATS_EDGE_THRESHOLD = float(threshold_tuning["selected_threshold"])
        tuned_summary = threshold_tuning["selected_summary"]
        eval_lines.append(f"ATS tuned edge threshold: {ATS_EDGE_THRESHOLD:.1f}")
        if int(threshold_tuning["walk_forward_games"]) > 0 and pd.notna(threshold_tuning["walk_forward_acc"]):
            eval_lines.append(
                f"Walk-forward ATS (tuned threshold): {float(threshold_tuning['walk_forward_acc']):.3%} on {int(threshold_tuning['walk_forward_games'])} games"
            )
        else:
            eval_lines.append("Walk-forward ATS (tuned threshold): insufficient dated validation windows")
        if int(tuned_summary["games"]) > 0 and pd.notna(tuned_summary["ats_acc"]):
            eval_lines.append(
                f"Full validation ATS (|edge|>={ATS_EDGE_THRESHOLD:.1f}): {float(tuned_summary['ats_acc']):.3%} on {int(tuned_summary['games'])} games"
            )
    else:
        ATS_EDGE_THRESHOLD = float(_get_ats_edge_threshold())

    print("\n".join(eval_lines))

    diff_cols2 = winner_feature_cols
    feature_cols = spread_feature_cols
    return spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp, diff_cols2, feature_cols


def save_models(spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp, model_dir: str):
    import pickle
    spread_booster.save_model(os.path.join(model_dir, "spread_booster.json"))
    if spread_edge_booster is not None:
        spread_edge_booster.save_model(os.path.join(model_dir, "spread_edge_booster.json"))
    else:
        with contextlib.suppress(OSError):
            os.remove(os.path.join(model_dir, "spread_edge_booster.json"))
    winner_booster.save_model(os.path.join(model_dir, "winner_booster.json"))
    lgb_spread.save_model(os.path.join(model_dir, "lgb_spread.txt"))
    if lgb_spread_edge is not None:
        lgb_spread_edge.save_model(os.path.join(model_dir, "lgb_spread_edge.txt"))
    else:
        with contextlib.suppress(OSError):
            os.remove(os.path.join(model_dir, "lgb_spread_edge.txt"))
    with open(os.path.join(model_dir, "iso_calibrator.pkl"), "wb") as f:
        pickle.dump(iso, f)
    with open(os.path.join(model_dir, "imputer.pkl"), "wb") as f:
        pickle.dump(imp, f)
    print(f"Models saved to {model_dir}")


def load_models(model_dir: str):
    import pickle

    spread_booster = xgb.Booster()
    spread_booster.load_model(os.path.join(model_dir, "spread_booster.json"))

    spread_edge_booster = None
    spread_edge_path = os.path.join(model_dir, "spread_edge_booster.json")
    if os.path.exists(spread_edge_path):
        spread_edge_booster = xgb.Booster()
        spread_edge_booster.load_model(spread_edge_path)

    winner_booster = xgb.Booster()
    winner_booster.load_model(os.path.join(model_dir, "winner_booster.json"))

    lgb_spread = lgb.Booster(model_file=os.path.join(model_dir, "lgb_spread.txt"))
    lgb_edge_path = os.path.join(model_dir, "lgb_spread_edge.txt")
    lgb_spread_edge = lgb.Booster(model_file=lgb_edge_path) if os.path.exists(lgb_edge_path) else None

    with open(os.path.join(model_dir, "iso_calibrator.pkl"), "rb") as f:
        iso = pickle.load(f)

    with open(os.path.join(model_dir, "imputer.pkl"), "rb") as f:
        imp = pickle.load(f)

    print("Models loaded from disk")
    return spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp



# ============================================================
# CELL 10A: R / hoopR DATA REFRESH PIPELINE
# MUST RUN BEFORE PYTHON LOADS team_box / schedule
# ============================================================

# One-time setup for Colab runtime
# !apt-get -qq update
# !apt-get -qq install -y r-base
# !pip -q install rpy2 pyarrow pandas

import os
from rpy2.robjects import r

def run_hoopr_refresh(
    raw_dir: str,
    current_season: int,
    seasons=None,
    force: bool = False,
    check_changes_for_current: bool = True,
    export=None,
):
    """
    Runs the user's hoopR -> parquet export pipeline in R.
    This updates schedule/team_box/etc before Python reloads them.
    """
    import rpy2.robjects as ro
    from rpy2.robjects import pandas2ri
    from rpy2.robjects.conversion import localconverter

    if seasons is None:
        seasons = list(range(2020, current_season + 1))

    if export is None:
        export = {
            "schedule": True,
            "team_box": True,
            "player_box": True,
            "pbp": True,
            "teams": True,
            "standings": True,
            "rankings": True,
            "team_stats": True,
            "player_stats": True,
        }

    os.makedirs(raw_dir, exist_ok=True)

    r_code = r'''
    options(warn = -1)

    pkgs <- c("hoopR","dplyr","arrow","lubridate","data.table","stringr","progressr","digest")
    for (p in pkgs) {
      if (!requireNamespace(p, quietly = TRUE)) {
        install.packages(p, repos="https://cloud.r-project.org")
      }
      suppressPackageStartupMessages(library(p, character.only = TRUE))
    }

    if (!exists("CURRENT_SEASON")) CURRENT_SEASON <- max(SEASONS)
    CHECK_CURRENT_FOR_CHANGES <- CHECK_CHANGES_FOR_CURRENT
    CHECK_STATIC_FOR_CHANGES  <- FALSE

    dir.create(RAW_DIR, recursive=TRUE, showWarnings=FALSE)

    manifest_path <- file.path(RAW_DIR, "_manifest.csv")

    manifest <- NULL
    if (file.exists(manifest_path) && !FORCE) {
      manifest <- tryCatch(read.csv(manifest_path, stringsAsFactors = FALSE), error=function(e) NULL)
    }

    log_row <- function(dataset, season, season_type, path, status, message="", data_hash="") {
      row <- data.frame(
        ts = as.character(Sys.time()),
        dataset = dataset,
        season = ifelse(is.null(season), "", as.character(season)),
        season_type = ifelse(is.null(season_type), "", as.character(season_type)),
        path = path,
        status = status,
        data_hash = data_hash,
        message = message,
        stringsAsFactors = FALSE
      )
      if (is.null(manifest)) manifest <<- row else manifest <<- rbind(manifest, row)
      write.csv(manifest, manifest_path, row.names = FALSE)
    }

    clean_hash <- function(x) {
      if (length(x) == 0) return("")
      if (is.na(x)) return("")
      as.character(x)
    }

    last_ok_hash <- function(dataset, season=NULL, season_type=NULL, path=NULL) {
      if (is.null(manifest)) return("")
      m <- manifest
      cond <- m$dataset == dataset & m$status == "ok"
      if (!is.null(season))      cond <- cond & m$season == as.character(season)
      if (!is.null(season_type)) cond <- cond & m$season_type == as.character(season_type)
      if (!is.null(path))        cond <- cond & m$path == path
      if (!any(cond)) return("")
      idx <- which(cond)
      clean_hash(m$data_hash[idx[length(idx)]])
    }

    out_path <- function(rel) file.path(RAW_DIR, rel)

    write_one <- function(df, path) {
      dir.create(dirname(path), recursive=TRUE, showWarnings=FALSE)
      arrow::write_parquet(df, path)
      cat("wrote", path, "\n")
    }

    safe_call <- function(fn) {
      tryCatch(fn(), error=function(e) e)
    }

    hash_df <- function(df) {
      if (!is.data.frame(df)) return("")
      dt <- data.table::as.data.table(df)
      data.table::setcolorder(dt, sort(names(dt)))
      if ("game_id" %in% names(dt)) data.table::setorder(dt, game_id)
      digest::digest(dt, algo="xxhash64")
    }

    should_change_check <- function(dataset, season) {
      if (is.null(season)) return(isTRUE(CHECK_STATIC_FOR_CHANGES))
      if (as.integer(season) == as.integer(CURRENT_SEASON)) return(isTRUE(CHECK_CURRENT_FOR_CHANGES))
      FALSE
    }

    call_with_year_or_season <- function(fn, yr, season_type) {
      fmls <- names(formals(fn))
      if ("season" %in% fmls) {
        fn(season = yr, season_type = season_type)
      } else if ("year" %in% fmls) {
        fn(year = yr, season_type = season_type)
      } else if ("season_end_year" %in% fmls) {
        fn(season_end_year = yr, season_type = season_type)
      } else {
        stop("Function does not accept season/year arguments in this hoopR version.")
      }
    }

    load_mbb_team_box_with_recent_fallback <- function(yr) {
      normalize_team_box_ids <- function(df) {
        if (!is.data.frame(df) || nrow(df) == 0) return(df)
        if ("game_id" %in% names(df)) df$game_id <- as.character(df$game_id)
        for (nm in c("team_id", "opponent_team_id")) {
          if (nm %in% names(df)) df[[nm]] <- suppressWarnings(as.numeric(df[[nm]]))
        }
        df
      }

      base <- tryCatch(hoopR::load_mbb_team_box(season=yr), error=function(e) data.frame())
      if (!is.data.frame(base)) base <- data.frame()
      base <- normalize_team_box_ids(base)
      if (as.integer(yr) != as.integer(CURRENT_SEASON)) return(base)

      sched <- tryCatch(hoopR::load_mbb_schedule(season=yr), error=function(e) data.frame())
      if (!is.data.frame(sched) || nrow(sched) == 0 || !"game_id" %in% names(sched)) return(base)

      completed <- rep(FALSE, nrow(sched))
      if ("status_type_completed" %in% names(sched)) {
        completed <- completed | tolower(as.character(sched$status_type_completed)) %in% c("true","1","yes")
      }
      if ("status_type_state" %in% names(sched)) {
        completed <- completed | tolower(as.character(sched$status_type_state)) %in% c("post","postgame","final")
      }
      if (all(c("home_score", "away_score") %in% names(sched))) {
        completed <- completed | (!is.na(sched$home_score) & !is.na(sched$away_score))
      }
      if ("game_date_time" %in% names(sched)) {
        gdt <- suppressWarnings(as.POSIXct(sched$game_date_time, tz="UTC"))
        completed <- completed & (is.na(gdt) | gdt >= (Sys.time() - 45*24*60*60))
      }

      missing_ids <- unique(as.character(sched$game_id[completed]))
      missing_ids <- missing_ids[!is.na(missing_ids) & missing_ids != ""]
      if ("game_id" %in% names(base)) {
        missing_ids <- setdiff(missing_ids, unique(as.character(base$game_id)))
      }
      if (length(missing_ids) == 0) return(base)

      pull_one <- function(gid) {
        tryCatch({
          x <- suppressMessages(suppressWarnings(hoopR::espn_mbb_team_box(as.numeric(gid))))
          if (!is.data.frame(x) || nrow(x) == 0) return(data.frame())
          normalize_team_box_ids(x)
        }, error=function(e) data.frame())
      }

      extra <- dplyr::bind_rows(lapply(missing_ids, pull_one))
      if (!is.data.frame(extra) || nrow(extra) == 0) return(base)
      extra <- normalize_team_box_ids(extra)

      out <- dplyr::bind_rows(base, extra)
      if (all(c("game_id", "team_id") %in% names(out))) {
        out <- out %>%
          dplyr::arrange(game_id, team_id) %>%
          dplyr::distinct(game_id, team_id, .keep_all = TRUE)
      }
      out
    }

    run_task <- function(dataset, season=NULL, season_type=NULL, path, fn) {
      file_exists <- file.exists(path)

      if (!file_exists) {
        cat("missing -> fetch:", dataset, season, season_type, "\n")
        res <- safe_call(fn)
        if (inherits(res, "error")) {
          msg <- conditionMessage(res)
          cat("FAIL:", msg, "\n")
          log_row(dataset, season, season_type, path, "fail", msg, "")
          return(invisible(NULL))
        }
        if (is.null(res) || (is.data.frame(res) && nrow(res)==0)) {
          cat("EMPTY\n")
          log_row(dataset, season, season_type, path, "fail", "empty result", "")
          return(invisible(NULL))
        }
        h <- clean_hash(hash_df(res))
        write_one(res, path)
        log_row(dataset, season, season_type, path, "ok", "missing -> wrote", h)
        return(invisible(NULL))
      }

      if (FORCE) {
        cat("FORCE overwrite:", dataset, season, season_type, "\n")
        res <- safe_call(fn)
        if (inherits(res, "error") || is.null(res) || (is.data.frame(res) && nrow(res)==0)) {
          msg <- if (inherits(res,"error")) conditionMessage(res) else "empty result"
          cat("FAIL:", msg, "\n")
          log_row(dataset, season, season_type, path, "fail", msg, "")
          return(invisible(NULL))
        }
        h <- clean_hash(hash_df(res))
        write_one(res, path)
        log_row(dataset, season, season_type, path, "ok", "forced overwrite", h)
        return(invisible(NULL))
      }

      if (!should_change_check(dataset, season)) {
        cat("skip (exists):", dataset, season, season_type, "\n")
        log_row(dataset, season, season_type, path, "skip", "exists (no change-check)", "")
        return(invisible(NULL))
      }

      cat("check-changes:", dataset, season, season_type, "\n")
      res <- safe_call(fn)
      if (inherits(res, "error")) {
        msg <- conditionMessage(res)
        cat("FAIL:", msg, "\n")
        log_row(dataset, season, season_type, path, "fail", msg, "")
        return(invisible(NULL))
      }
      if (is.null(res) || (is.data.frame(res) && nrow(res)==0)) {
        cat("EMPTY\n")
        log_row(dataset, season, season_type, path, "fail", "empty result", "")
        return(invisible(NULL))
      }

      new_hash <- clean_hash(hash_df(res))
      old_hash <- clean_hash(last_ok_hash(dataset, season, season_type, path))

      if (old_hash == "" || new_hash != old_hash) {
        cat("changed -> overwrite:", dataset, season, season_type, "\n")
        write_one(res, path)
        log_row(dataset, season, season_type, path, "ok", "changed overwrite", new_hash)
      } else {
        cat("unchanged:", dataset, season, season_type, "\n")
        log_row(dataset, season, season_type, path, "skip", "unchanged", new_hash)
      }

      invisible(NULL)
    }

    if (EXPORT_TEAMS) {
      run_task("teams", NULL, NULL, out_path("teams/mbb_teams.parquet"),
               function() hoopR::espn_mbb_teams())
    }
    if (EXPORT_STANDINGS) {
      run_task("standings", NULL, NULL, out_path("standings/mbb_standings.parquet"),
               function() hoopR::espn_mbb_standings())
    }
    if (EXPORT_RANKINGS) {
      run_task("rankings", NULL, NULL, out_path("rankings/mbb_rankings.parquet"),
               function() hoopR::espn_mbb_rankings())
    }

    for (yr in SEASONS) {
      cat("\n=============================\n")
      cat("Season end year:", yr, "\n")
      cat("=============================\n")

      if (EXPORT_SCHEDULE) {
        run_task("schedule", yr, NULL, out_path(sprintf("schedule/mbb_schedule_%s.parquet", yr)),
                 function() hoopR::load_mbb_schedule(season=yr))
      }

      if (EXPORT_TEAM_BOX) {
        run_task("team_box", yr, NULL, out_path(sprintf("team_box/mbb_team_box_%s.parquet", yr)),
                 function() load_mbb_team_box_with_recent_fallback(yr))
      }

      if (EXPORT_PLAYER_BOX) {
        run_task("player_box", yr, NULL, out_path(sprintf("player_box/mbb_player_box_%s.parquet", yr)),
                 function() hoopR::load_mbb_player_box(season=yr))
      }

      if (EXPORT_TEAM_STATS) {
        for (stype in c("regular","postseason")) {
          run_task("team_stats", yr, stype, out_path(sprintf("team_stats/mbb_team_stats_%s_%s.parquet", yr, stype)),
                   function() call_with_year_or_season(hoopR::espn_mbb_team_stats, yr, stype))
        }
      }

      if (EXPORT_PLAYER_STATS) {
        for (stype in c("regular","postseason")) {
          run_task("player_stats", yr, stype, out_path(sprintf("player_stats/mbb_player_stats_%s_%s.parquet", yr, stype)),
                   function() call_with_year_or_season(hoopR::espn_mbb_player_stats, yr, stype))
        }
      }

      if (EXPORT_PBP) {
        run_task("pbp", yr, NULL, out_path(sprintf("pbp/mbb_pbp_%s.parquet", yr)),
                 function() hoopR::load_mbb_pbp(season=yr))
      }
    }

    cat("\nDONE exporting hoopR Parquet (missing-or-changed)\n")
    cat("Manifest:", manifest_path, "\n")
    '''

    with suppress_r_console():
        with localconverter(ro.default_converter + pandas2ri.converter):
            ro.globalenv["RAW_DIR"] = raw_dir
            ro.globalenv["SEASONS"] = seasons
            ro.globalenv["FORCE"] = force
            ro.globalenv["CURRENT_SEASON"] = current_season
            ro.globalenv["CHECK_CHANGES_FOR_CURRENT"] = check_changes_for_current

            ro.globalenv["EXPORT_SCHEDULE"] = export["schedule"]
            ro.globalenv["EXPORT_TEAM_BOX"] = export["team_box"]
            ro.globalenv["EXPORT_PLAYER_BOX"] = export["player_box"]
            ro.globalenv["EXPORT_PBP"] = export["pbp"]
            ro.globalenv["EXPORT_TEAMS"] = export["teams"]
            ro.globalenv["EXPORT_STANDINGS"] = export["standings"]
            ro.globalenv["EXPORT_RANKINGS"] = export["rankings"]
            ro.globalenv["EXPORT_TEAM_STATS"] = export["team_stats"]
            ro.globalenv["EXPORT_PLAYER_STATS"] = export["player_stats"]
            ro.r(r_code)


# ============================================================
# CELL 10B: DATA LOADERS + ROLLING SNAPSHOTS
# REQUIRED BY CELL 11 SCHEDULER
# ============================================================

def _read_any_table(path: str) -> pd.DataFrame:
    ext = os.path.splitext(path)[1].lower()
    try:
        if ext == ".parquet":
            return pd.read_parquet(path)
        if ext in [".csv", ".txt"]:
            return pd.read_csv(path, low_memory=False)
        if ext in [".xlsx", ".xls"]:
            return pd.read_excel(path)
    except Exception as e:
        print(f"Failed reading {os.path.basename(path)}: {e}")
    return pd.DataFrame()


def _find_files_recursive(base_dir: str, exts=(".parquet", ".csv", ".xlsx", ".xls")) -> list:
    hits = []
    for root, _, files in os.walk(base_dir):
        for fn in files:
            if fn.lower().endswith(exts):
                hits.append(os.path.join(root, fn))
    return sorted(hits)


def _normalize_team_box_columns(df: pd.DataFrame) -> pd.DataFrame:
    """
    Make team_box columns consistent enough for training/snapshots.
    """
    if df is None or len(df) == 0:
        return pd.DataFrame()

    x = df.copy()
    x.columns = [str(c).strip() for c in x.columns]

    # common aliases
    rename_map = {}

    colset = {c.lower(): c for c in x.columns}

    def pick(*names):
        for n in names:
            if n.lower() in colset:
                return colset[n.lower()]
        return None

    game_id_col = pick("game_id", "id")
    if game_id_col and game_id_col != "game_id":
        rename_map[game_id_col] = "game_id"

    season_col = pick("season", "season_year")
    if season_col and season_col != "season":
        rename_map[season_col] = "season"

    game_dt_col = pick("game_date_time", "start_date", "date", "game_date")
    if game_dt_col and game_dt_col != "game_date_time":
        rename_map[game_dt_col] = "game_date_time"

    team_id_col = pick("team_id", "team.id", "teamid")
    if team_id_col and team_id_col != "team_id":
        rename_map[team_id_col] = "team_id"

    opp_id_col = pick("opponent_team_id", "opponent_id", "opponent.id", "opponentteamid")
    if opp_id_col and opp_id_col != "opponent_team_id":
        rename_map[opp_id_col] = "opponent_team_id"

    team_score_col = pick("team_score", "score", "points")
    if team_score_col and team_score_col != "team_score":
        rename_map[team_score_col] = "team_score"

    opp_score_col = pick("opponent_team_score", "opp_score", "opponent_score", "points_against")
    if opp_score_col and opp_score_col != "opponent_team_score":
        rename_map[opp_score_col] = "opponent_team_score"

    team_name_col = pick("team_name", "team_display_name", "display_name", "team")
    if team_name_col and team_name_col != "team_name":
        rename_map[team_name_col] = "team_name"

    x = x.rename(columns=rename_map)

    # required core columns
    required = [
        "game_id", "season", "game_date_time",
        "team_id", "opponent_team_id",
        "team_score", "opponent_team_score"
    ]
    for c in required:
        if c not in x.columns:
            x[c] = np.nan

    # numeric coercions
    for c in ["team_id", "opponent_team_id", "team_score", "opponent_team_score", "season"]:
        x[c] = pd.to_numeric(x[c], errors="coerce")

    x["game_date_time"] = pd.to_datetime(x["game_date_time"], errors="coerce", utc=True)

    # add team_name if absent
    if "team_name" not in x.columns:
        x["team_name"] = np.nan

    x = x.dropna(subset=["game_id", "team_id", "opponent_team_id", "game_date_time"]).copy()

    x["game_id"] = x["game_id"].astype(str)
    x["team_id"] = x["team_id"].astype(int)
    x["opponent_team_id"] = x["opponent_team_id"].astype(int)

    return x.reset_index(drop=True)


def load_team_box_history(team_box_dir: str, seasons: list) -> pd.DataFrame:
    """
    Loads all team-box history files from TEAM_BOX_DIR recursively.
    Accepts parquet/csv/xlsx.
    Filters to requested seasons when season column exists.
    """
    files = _find_files_recursive(team_box_dir, exts=(".parquet", ".csv", ".xlsx", ".xls"))
    if not files:
        raise FileNotFoundError(f"No team_box files found in {team_box_dir}")

    dfs = []
    for f in files:
        df = _read_any_table(f)
        if len(df) == 0:
            continue
        df = _normalize_team_box_columns(df)
        if len(df) == 0:
            continue
        dfs.append(df)

    if not dfs:
        raise ValueError(f"No readable team_box data found in {team_box_dir}")

    out = pd.concat(dfs, ignore_index=True)

    if "season" in out.columns:
        out = out[out["season"].isin(seasons)].copy()

    out = out.sort_values(["game_date_time", "game_id", "team_id"]).reset_index(drop=True)
    out = out.drop_duplicates(subset=["game_id", "team_id"], keep="last").reset_index(drop=True)

    return out


def _normalize_schedule_columns(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or len(df) == 0:
        return pd.DataFrame()

    x = df.copy()
    x.columns = [str(c).strip() for c in x.columns]
    colset = {c.lower(): c for c in x.columns}

    def pick(*names):
        for n in names:
            if n.lower() in colset:
                return colset[n.lower()]
        return None

    rename_map = {}

    for target, options in {
        "game_id": ["game_id", "id"],
        "season": ["season", "season_year"],
        "game_date_time": ["game_date_time", "start_date", "date", "game_date"],
        "home_id": ["home_id", "home_team_id", "home.id"],
        "away_id": ["away_id", "away_team_id", "away.id"],
        "home_team": ["home_team", "home_display_name", "home_name"],
        "away_team": ["away_team", "away_display_name", "away_name"],
        "home_short_display_name": ["home_short_display_name", "home_short_name"],
        "away_short_display_name": ["away_short_display_name", "away_short_name"],
        "home_score": ["home_score"],
        "away_score": ["away_score"],
        "neutral_site": ["neutral_site", "neutral"],
        "status_type_completed": ["status_type_completed"],
        "status_type_state": ["status_type_state"],
        "status_type_name": ["status_type_name"],
        "status_type_short_detail": ["status_type_short_detail"],
    }.items():
        src = pick(*options)
        if src and src != target:
            rename_map[src] = target

    x = x.rename(columns=rename_map)

    for c in [
        "game_id", "season", "game_date_time", "home_id", "away_id",
        "home_team", "away_team", "home_short_display_name", "away_short_display_name",
        "home_score", "away_score", "neutral_site",
        "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"
    ]:
        if c not in x.columns:
            x[c] = np.nan

    x["game_date_time"] = pd.to_datetime(x["game_date_time"], errors="coerce", utc=True)
    for c in ["season", "home_id", "away_id", "home_score", "away_score"]:
        x[c] = pd.to_numeric(x[c], errors="coerce")

    x["game_id"] = x["game_id"].astype(str)
    x = x.dropna(subset=["game_id", "game_date_time"]).copy()

    return x.reset_index(drop=True)


def load_schedule(schedule_dir: str, season: int) -> pd.DataFrame:
    """
    Loads schedule files recursively and returns the requested season.
    """
    files = _find_files_recursive(schedule_dir, exts=(".parquet", ".csv", ".xlsx", ".xls"))
    if not files:
        raise FileNotFoundError(f"No schedule files found in {schedule_dir}")

    dfs = []
    for f in files:
        df = _read_any_table(f)
        if len(df) == 0:
            continue
        df = _normalize_schedule_columns(df)
        if len(df) == 0:
            continue
        dfs.append(df)

    if not dfs:
        raise ValueError(f"No readable schedule data found in {schedule_dir}")

    out = pd.concat(dfs, ignore_index=True)

    if "season" in out.columns and out["season"].notna().any():
        out = out[out["season"] == season].copy()

    out = out.sort_values(["game_date_time", "game_id"]).reset_index(drop=True)
    out = out.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)

    return out


def load_schedule_history(schedule_dir: str, seasons: list) -> pd.DataFrame:
    """
    Loads schedule files recursively and returns the requested seasons.
    """
    files = _find_files_recursive(schedule_dir, exts=(".parquet", ".csv", ".xlsx", ".xls"))
    if not files:
        raise FileNotFoundError(f"No schedule files found in {schedule_dir}")

    dfs = []
    for f in files:
        df = _read_any_table(f)
        if len(df) == 0:
            continue
        df = _normalize_schedule_columns(df)
        if len(df) == 0:
            continue
        dfs.append(df)

    if not dfs:
        raise ValueError(f"No readable schedule data found in {schedule_dir}")

    out = pd.concat(dfs, ignore_index=True)

    if "season" in out.columns and out["season"].notna().any():
        out = out[out["season"].isin(seasons)].copy()

    out = out.sort_values(["game_date_time", "game_id"]).reset_index(drop=True)
    out = out.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)

    return out


def build_team_rolling_snapshots(team_box_all: pd.DataFrame, window: int = ROLL_WINDOW):
    """
    Builds one row per team per played game with leakage-safe rolling features.
    These snapshots are later merge_asof'd into upcoming slates.
    """
    tb = team_box_all.copy()
    if len(tb) == 0:
        return pd.DataFrame(), []

    tb["game_date_time"] = pd.to_datetime(tb["game_date_time"], errors="coerce", utc=True)
    tb["game_dt_et"] = tb["game_date_time"].dt.tz_convert("America/New_York").dt.tz_localize(None)

    # useful fallback stat creation
    if "points_for" not in tb.columns:
        tb["points_for"] = pd.to_numeric(tb["team_score"], errors="coerce")
    if "points_against" not in tb.columns:
        tb["points_against"] = pd.to_numeric(tb["opponent_team_score"], errors="coerce")

    if "point_diff" not in tb.columns:
        tb["point_diff"] = pd.to_numeric(tb["points_for"], errors="coerce") - pd.to_numeric(tb["points_against"], errors="coerce")

    # keep numeric non-ID columns
    exclude = {
        "game_id", "season", "game_date", "game_date_time", "game_dt_et",
        "team_id", "team_uid", "team_slug",
        "opponent_team_id", "opponent_team_uid", "opponent_team_slug",
    }

    numeric_cols = []
    for c in tb.columns:
        if c in exclude:
            continue
        if str(c).startswith("opponent_"):
            continue
        if pd.api.types.is_numeric_dtype(tb[c]):
            numeric_cols.append(c)

    # make sure these core stats exist
    for c in ["points_for", "points_against", "point_diff"]:
        if c not in numeric_cols and c in tb.columns:
            numeric_cols.append(c)

    tb = tb.sort_values(["team_id", "game_dt_et", "game_id"]).reset_index(drop=True)
    for c in numeric_cols:
        tb[c] = pd.to_numeric(tb[c], errors="coerce")

    roll_cols = []
    if numeric_cols:
        grouped_numeric = tb.groupby("team_id", sort=False)[numeric_cols]

        rolling_mean_long = (
            grouped_numeric.rolling(window, min_periods=3).mean()
            .groupby(level=0, sort=False).shift(1)
        )
        rolling_mean = rolling_mean_long.reset_index(level=0, drop=True)
        rolling_mean.columns = [f"r{window}_mean_{c}" for c in numeric_cols]

        rolling_mean3_long = (
            grouped_numeric.rolling(3, min_periods=2).mean()
            .groupby(level=0, sort=False).shift(1)
        )
        rolling_mean3 = rolling_mean3_long.reset_index(level=0, drop=True)
        rolling_mean3.columns = [f"r3_mean_{c}" for c in numeric_cols]

        rolling_std_long = (
            grouped_numeric.rolling(window, min_periods=3).std()
            .groupby(level=0, sort=False).shift(1)
        )
        rolling_std = rolling_std_long.reset_index(level=0, drop=True)
        rolling_std.columns = [f"r{window}_std_{c}" for c in numeric_cols]

        rolling_frames = [rolling_mean, rolling_mean3, rolling_std]
        tb = pd.concat([tb] + rolling_frames, axis=1)
        roll_cols.extend(list(rolling_mean.columns) + list(rolling_mean3.columns) + list(rolling_std.columns))

    tb[f"r{window}_gp"] = tb.groupby("team_id", sort=False).cumcount().astype(float)
    tb[f"r{window}_gp"] = tb[f"r{window}_gp"].clip(upper=window)
    tb.loc[tb[f"r{window}_gp"].eq(0), f"r{window}_gp"] = np.nan
    roll_cols.append(f"r{window}_gp")

    # rest days
    tb["prev_game_dt_et"] = tb.groupby("team_id")["game_dt_et"].shift(1)
    tb["rest_days"] = (tb["game_dt_et"] - tb["prev_game_dt_et"]).dt.total_seconds() / 86400.0
    tb["rest_days"] = tb["rest_days"].clip(lower=0)
    roll_cols.append("rest_days")

    keep_cols = ["team_id", "game_id", "game_dt_et"]
    if "team_name" in tb.columns:
        keep_cols.append("team_name")

    out = tb[keep_cols + [c for c in roll_cols if c in tb.columns]].copy()
    out = out.sort_values(["game_dt_et", "team_id"]).reset_index(drop=True)

    return out, [c for c in roll_cols if c in out.columns]


# ============================================================
# CELL 11: AUTO-RETRAINING SCHEDULER
# FULL REWRITE matches CELL 5 + CELL 8 + CELL 9
# ============================================================

def check_and_retrain(force_data: bool = False, force_model: bool = False):
    """
    Checks retraining timestamps and retrains as needed.
    - Data refresh: every RETRAIN_DATA_HOURS
    - Model refit: every RETRAIN_MODEL_DAYS
    """
    global team_snaps, roll_cols, spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp, ATS_EDGE_THRESHOLD, SPREAD_ENSEMBLE_WEIGHT_LGB, MARKET_BLEND
    global diff_cols, diff_cols2, feature_cols, dataset_all, schedule_cur, elo_snap, cur2
    global team_box_hist

    meta = _load_metadata()
    now_str = datetime.utcnow().isoformat()
    print(
        "\n".join([
            "RETRAIN CHECK",
            f"force_data={bool(force_data)} | force_model={bool(force_model)}",
        ])
    )
    _dashboard_log("retrain_check", status="start", force_data=bool(force_data), force_model=bool(force_model))

    need_data = force_data or _hours_since(meta.get("last_data_refresh")) >= RETRAIN_DATA_HOURS
    need_model = force_model or _days_since(meta.get("last_model_fit")) >= RETRAIN_MODEL_DAYS
    training_rows = 0
    injury_cols_in_dataset = []
    injury_cols_in_features = []

    if need_data:
        print(f"DATA REFRESH\nTriggered (last: {meta.get('last_data_refresh', 'never')})")

        run_hoopr_refresh(
            raw_dir=RAW_DIR,
            current_season=CURRENT_SEASON,
            seasons=HIST_SEASONS,
            force=bool(force_data),
            check_changes_for_current=True,
            export={
                "schedule": True,
                "team_box": True,
                "player_box": True,
                "pbp": True,
                "teams": True,
                "standings": True,
                "rankings": True,
                "team_stats": True,
                "player_stats": True,
            },
        )

        meta["last_data_refresh"] = now_str
        meta["last_data_refresh_action"] = "executed"
        _save_metadata(meta)
    else:
        print(f"DATA REFRESH\nSkipped (last: {meta.get('last_data_refresh', 'never')})")
        meta["last_data_refresh_action"] = "skipped"

    team_box_hist = load_team_box_history(TEAM_BOX_DIR, HIST_SEASONS)
    tb_hist = team_box_hist.copy()
    schedule_cur = load_schedule(SCHEDULE_DIR, CURRENT_SEASON)
    try:
        schedule_hist = load_schedule_history(SCHEDULE_DIR, HIST_SEASONS)
    except Exception:
        schedule_hist = schedule_cur.copy()
    current_training_sig = _training_input_signature(TEAM_BOX_DIR, SCHEDULE_DIR)
    dataset_cache_sig = _training_dataset_cache_signature(current_training_sig, CURRENT_SEASON)
    print(
        "\n".join([
            "DATA LOAD",
            f"team_box rows: {len(tb_hist):,} | schedule rows: {len(schedule_cur):,}",
            "Building rolling snapshots + Elo...",
        ])
    )
    team_snaps, roll_cols = build_team_rolling_snapshots(tb_hist, window=ROLL_WINDOW)
    elo_snap = compute_elo_ratings(tb_hist)
    SEASON_VIZ_CACHE.clear()
    OVERVIEW_VIZ_CACHE.clear()
    if "_refresh_matchup_team_options" in globals():
        _refresh_matchup_team_options()
    if "_refresh_season_viz_options" in globals():
        _refresh_season_viz_options(force=True)

    if not force_model and need_model:
        saved_training_sig = meta.get("training_input_signature")
        model_paths = [
            os.path.join(MODEL_DIR, "spread_booster.json"),
            os.path.join(MODEL_DIR, "winner_booster.json"),
            os.path.join(MODEL_DIR, "lgb_spread.txt"),
            os.path.join(MODEL_DIR, "iso_calibrator.pkl"),
            os.path.join(MODEL_DIR, "imputer.pkl"),
        ]
        if saved_training_sig and saved_training_sig == current_training_sig and all(os.path.exists(p) for p in model_paths):
            need_model = False

    if need_model:
        retrain_lines = [
            "MODEL RETRAIN",
            f"Triggered (last: {meta.get('last_model_fit', 'never')})",
        ]
        dataset_all = _load_training_dataset_cache(dataset_cache_sig)
        if dataset_all is not None and len(dataset_all) > 0:
            retrain_lines.append(f"Loaded engineered training dataset cache ({len(dataset_all):,} rows)")
        else:
            retrain_lines.append("Building training dataset...")
            dataset_all = build_game_dataset_from_team_box(
                team_box=tb_hist,
                schedule_df=schedule_hist,
                window=ROLL_WINDOW,
                elo_df=elo_snap,
                team_snaps=team_snaps,
                precomputed_roll_cols=roll_cols,
            )
            dataset_all = dataset_all.sort_values("game_dt_et").reset_index(drop=True)
            _save_training_dataset_cache(dataset_all, dataset_cache_sig)
            retrain_lines.append(f"Saved engineered training dataset cache ({len(dataset_all):,} rows)")

        dataset_all = dataset_all.sort_values("game_dt_et").reset_index(drop=True)
        training_rows = int(len(dataset_all))
        injury_cols_in_dataset = [c for c in ["diff_injury_impact", "diff_inj_out"] if c in dataset_all.columns]
        retrain_lines.append(f"Training rows: {training_rows:,}")
        retrain_lines.append(f"Injury columns in dataset: {injury_cols_in_dataset if injury_cols_in_dataset else 'none'}")
        print("\n".join(retrain_lines))

        spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp, diff_cols2, feature_cols = train_models(dataset_all, CURRENT_SEASON)

        diff_cols = [c for c in diff_cols2 if not c.endswith("__na")]

        save_models(spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp, MODEL_DIR)
        spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp = load_models(MODEL_DIR)
        injury_cols_in_features = [c for c in ["diff_injury_impact", "diff_inj_out"] if c in list(feature_cols or [])]
        meta["last_model_fit"] = now_str
        meta["feature_cols"] = feature_cols
        meta["training_input_signature"] = current_training_sig
        meta["last_training_rows"] = training_rows
        meta["injury_feature_cols"] = injury_cols_in_features
        meta["market_edge_model_version"] = MARKET_EDGE_MODEL_VERSION
        meta["ats_edge_threshold"] = float(_get_ats_edge_threshold())
        meta["spread_ensemble_weight_lgb"] = float(_get_spread_ensemble_weight())
        meta["market_blend"] = float(_get_market_blend())
        meta["last_model_refresh_action"] = "executed"
        _save_metadata(meta)
        with contextlib.suppress(OSError):
            os.remove(SEASON_ACC_CACHE_PATH)
        for cache_name in ["BOARD_CACHE", "HC_FILTER_CACHE", "MATCHUP_SNAPSHOT_CACHE", "FILTERED_BOARD_CACHE", "_BRACKET_MATCHUP_CACHE"]:
            globals().get(cache_name, {}).clear()
        if "SEASON_ACC" in globals():
            globals()["SEASON_ACC"] = None
        if "SEASON_ACC_DATE" in globals():
            globals()["SEASON_ACC_DATE"] = None
        if "LAST_BOARD" in globals():
            globals()["LAST_BOARD"] = None
        if "LAST_DATE" in globals():
            globals()["LAST_DATE"] = None
        if "HC_REPORT_CACHE" in globals():
            globals()["HC_REPORT_CACHE"] = None
        if "HC_REPORT_DATE" in globals():
            globals()["HC_REPORT_DATE"] = None
        print("MODEL STATUS\nModel retrain complete")
    else:
        print(f"MODEL STATUS\nModel is fresh (last fit: {meta.get('last_model_fit', 'never')}). Loading from disk.")
        meta["last_model_refresh_action"] = "skipped"
        try:
            spread_booster, spread_edge_booster, winner_booster, lgb_spread, lgb_spread_edge, iso, imp = load_models(MODEL_DIR)
            meta_cols = meta.get("feature_cols", [])
            diff_cols2 = meta_cols
            diff_cols = [c for c in meta_cols if not c.endswith("__na")]
            feature_cols = meta_cols
            injury_cols_in_features = [c for c in ["diff_injury_impact", "diff_inj_out"] if c in list(feature_cols or [])]
            meta["injury_feature_cols"] = injury_cols_in_features
            ATS_EDGE_THRESHOLD = float(meta.get("ats_edge_threshold", _get_ats_edge_threshold()))
            SPREAD_ENSEMBLE_WEIGHT_LGB = float(meta.get("spread_ensemble_weight_lgb", _get_spread_ensemble_weight()))
            MARKET_BLEND = float(meta.get("market_blend", _get_market_blend()))
            if int(meta.get("market_edge_model_version", 0) or 0) < MARKET_EDGE_MODEL_VERSION:
                spread_edge_booster = None
                lgb_spread_edge = None
                meta["market_edge_model_status"] = "disabled_stale_retrain_required"
                print("MODEL STATUS\nMarket edge models were trained with an older spread convention and have been disabled. Run Force Retrain to refresh them.")
            else:
                meta["market_edge_model_status"] = "ready"
            _save_metadata(meta)
        except Exception as e:
            print(f"Could not load saved models ({e}). Triggering fresh model train...")
            _dashboard_log("retrain_check", status="load_failed", error=str(e))
            return check_and_retrain(force_data=False, force_model=True)

    cur2 = None
    _dashboard_log(
        "retrain_check",
        status="completed",
        force_data=bool(force_data),
        force_model=bool(force_model),
        data_refresh=meta.get("last_data_refresh_action", "unknown"),
        model_refresh=meta.get("last_model_refresh_action", "unknown"),
    )
    print("RETRAIN COMPLETE\nScheduler complete. All globals ready.")
    return {
        "data_refresh_action": meta.get("last_data_refresh_action", "unknown"),
        "model_refresh_action": meta.get("last_model_refresh_action", "unknown"),
        "last_data_refresh": meta.get("last_data_refresh", ""),
        "last_model_fit": meta.get("last_model_fit", ""),
        "training_rows": training_rows,
        "injury_cols_in_dataset": injury_cols_in_dataset,
        "injury_cols_in_features": injury_cols_in_features,
        "training_input_signature": current_training_sig,
        "ats_edge_threshold": float(meta.get("ats_edge_threshold", _get_ats_edge_threshold())),
        "spread_ensemble_weight_lgb": float(meta.get("spread_ensemble_weight_lgb", _get_spread_ensemble_weight())),
        "market_blend": float(meta.get("market_blend", _get_market_blend())),
    }

# ============================================================
# CELL 12: PREDICTION ENGINE
# ============================================================

def make_xgb_matrix(pregame: pd.DataFrame, booster, imp_ref=None) -> xgb.DMatrix:
    """Builds an XGBoost DMatrix matching the booster's feature names."""
    fnames = list(booster.feature_names)
    base_cols = [c for c in fnames if not c.endswith("__na")]
    na_cols   = [c for c in fnames if c.endswith("__na")]

    X = pregame.copy()
    if "home_court_A" in fnames and "home_court_A" not in X.columns:
        neutral = _coerce_bool_series(X.get("neutral_site", False), X.index)
        if {"teamA_id", "home_id"}.issubset(X.columns):
            teamA_is_home = (
                pd.to_numeric(X["teamA_id"], errors="coerce") ==
                pd.to_numeric(X["home_id"], errors="coerce")
            )
            X["home_court_A"] = np.where(neutral, 0.0, np.where(teamA_is_home, 1.0, -1.0))
        else:
            X["home_court_A"] = np.where(neutral, 0.0, 0.0)
    for c in base_cols:
        if c not in X.columns:
            X[c] = np.nan

    if na_cols:
        flags = pd.DataFrame(index=X.index)
        for nc in na_cols:
            bc = nc[:-4]
            if nc not in X.columns:
                flags[nc] = X[bc].isna().astype("int8")
        X = pd.concat([X, flags], axis=1)

    if imp_ref is not None and base_cols:
        imp_cols = list(getattr(imp_ref, "feature_names_in_", base_cols))
        for c in imp_cols:
            if c not in X.columns:
                X[c] = np.nan
        X_imp = X.reindex(columns=imp_cols)
        X_imp = pd.DataFrame(
            imp_ref.transform(X_imp),
            columns=imp_cols,
            index=X.index,
        )
        for c in imp_cols:
            X[c] = X_imp[c]

    X = X.reindex(columns=fnames, fill_value=0.0)
    if X.columns.duplicated().any():
        X = X.loc[:, ~X.columns.duplicated()]
    return xgb.DMatrix(X, feature_names=fnames)


def predict_slate(
    pregame: pd.DataFrame,
    spread_booster, winner_booster, lgb_spread,
    iso, imp, feature_cols,
    ensemble_weight_lgb: float = None,    # blend weight for LGB margin
    spread_edge_booster=None,
    lgb_spread_edge=None,
    market_blend: float = None,
) -> pd.DataFrame:
    """
    Runs ensemble prediction on a pregame DataFrame.
    Returns pregame with columns added:
      pred_margin_home, p_home_win, winner_pick, pick_conf, spread_pick
    """
    if pregame is None or len(pregame) == 0:
        return pd.DataFrame()
    if ensemble_weight_lgb is None:
        ensemble_weight_lgb = float(_get_spread_ensemble_weight())
    if market_blend is None:
        market_blend = float(_get_market_blend())

    model_pregame = pregame.copy()
    if "home_court_A" not in model_pregame.columns:
        neutral = _coerce_bool_series(model_pregame.get("neutral_site", False), model_pregame.index)
        if {"teamA_id", "home_id"}.issubset(model_pregame.columns):
            teamA_is_home = (
                pd.to_numeric(model_pregame["teamA_id"], errors="coerce") ==
                pd.to_numeric(model_pregame["home_id"], errors="coerce")
            )
            model_pregame["home_court_A"] = np.where(neutral, 0.0, np.where(teamA_is_home, 1.0, -1.0))
        else:
            model_pregame["home_court_A"] = np.where(neutral, 0.0, 0.0)

    dcur_spread = make_xgb_matrix(model_pregame, spread_booster, imp)
    dcur_winner = make_xgb_matrix(model_pregame, winner_booster, imp)

    xgb_margin = spread_booster.predict(dcur_spread, iteration_range=(0, spread_booster.best_iteration + 1))

    # LGB margin using same feature set
    fnames = list(spread_booster.feature_names)
    lgb_fnames = list(lgb_spread.feature_name()) if hasattr(lgb_spread, "feature_name") else fnames
    X_lgb = model_pregame.reindex(columns=lgb_fnames or fnames, fill_value=0.0)
    lgb_margin = lgb_spread.predict(X_lgb.values)

    # Ensemble raw TeamA margin fallback
    pred_margin_ab = (1 - ensemble_weight_lgb) * xgb_margin + ensemble_weight_lgb * lgb_margin

    raw_pA = winner_booster.predict(dcur_winner, iteration_range=(0, winner_booster.best_iteration + 1))
    pred_pA = iso.transform(raw_pA) if iso is not None else raw_pA

    # Home/Away conversion
    teamA_is_home = (model_pregame["teamA_id"].astype(int) == model_pregame["home_id"].astype(int)).values
    pred_margin_home_raw = np.where(teamA_is_home, pred_margin_ab, -pred_margin_ab).astype(float)
    p_home_win_raw   = np.where(teamA_is_home, pred_pA, 1 - pred_pA).astype(float)
    p_home_win_uncal = np.where(teamA_is_home, raw_pA, 1 - raw_pA).astype(float)

    pred_margin_home = pred_margin_home_raw.copy()
    vegas_spread_src = model_pregame.get("vegas_spread_home")
    if vegas_spread_src is None:
        vegas_spread_src = model_pregame.get("rw_spread_home")
    if vegas_spread_src is None:
        vegas_spread_home = pd.Series(np.nan, index=model_pregame.index, dtype=float)
    else:
        vegas_spread_home = pd.Series(
            pd.to_numeric(vegas_spread_src, errors="coerce"),
            index=model_pregame.index,
            dtype=float,
        )
    market_implied_home_margin = _market_implied_home_margin(vegas_spread_home)
    has_market_spread = vegas_spread_home.notna().to_numpy()
    pred_edge_home = np.full(len(model_pregame), np.nan, dtype=float)
    pred_margin_home_market = np.full(len(model_pregame), np.nan, dtype=float)

    if spread_edge_booster is not None and lgb_spread_edge is not None and has_market_spread.any():
        dcur_edge = make_xgb_matrix(model_pregame, spread_edge_booster, imp)
        xgb_edge = spread_edge_booster.predict(dcur_edge, iteration_range=(0, spread_edge_booster.best_iteration + 1))
        lgb_edge_fnames = list(lgb_spread_edge.feature_name()) if hasattr(lgb_spread_edge, "feature_name") else list(spread_edge_booster.feature_names)
        X_lgb_edge = model_pregame.reindex(columns=lgb_edge_fnames or list(spread_edge_booster.feature_names), fill_value=0.0)
        lgb_edge = lgb_spread_edge.predict(X_lgb_edge.values)
        pred_edge_home = ((1 - ensemble_weight_lgb) * xgb_edge + ensemble_weight_lgb * lgb_edge).astype(float)
        market_margin_home = market_implied_home_margin.to_numpy(dtype=float) + pred_edge_home
        pred_margin_home_market = market_margin_home.copy()
        pred_margin_home = np.where(
            has_market_spread,
            (1.0 - market_blend) * market_margin_home + market_blend * market_implied_home_margin.to_numpy(dtype=float),
            pred_margin_home_raw,
        )

    neutral = _coerce_bool_series(model_pregame.get("neutral_site", False), model_pregame.index)
    is_tournament = pd.to_numeric(
        model_pregame.get("is_tournament", pd.Series(0, index=model_pregame.index)),
        errors="coerce"
    ).fillna(0).astype(int).eq(1)
    tournament_neutral = neutral & is_tournament
    tournament_mode_enabled = False
    try:
        tournament_mode_enabled = bool(globals().get("tournament_mode").value)
    except Exception:
        tournament_mode_enabled = False

    tournament_mode_applied = np.zeros(len(model_pregame), dtype=int)
    if tournament_mode_enabled and tournament_neutral.any():
        tournament_mask = tournament_neutral.to_numpy(dtype=bool)
        abs_margin = np.abs(pred_margin_home_raw).astype(float)
        damp_scale = np.where(
            abs_margin >= 20.0, TOURNEY_SPREAD_DAMP_STRONG,
            np.where(
                abs_margin >= 12.0, TOURNEY_SPREAD_DAMP_MEDIUM,
                np.where(abs_margin >= 8.0, TOURNEY_SPREAD_DAMP_LIGHT, TOURNEY_SPREAD_DAMP_SMALL)
            )
        ).astype(float)
        # Tournament Mode removes market influence from the displayed spread and
        # instead dampens the raw model margin toward zero for neutral-site games.
        damped_margin = (pred_margin_home_raw * damp_scale).astype(float)
        pred_margin_home = np.where(tournament_mask, damped_margin, pred_margin_home).astype(float)
        tournament_mode_applied = tournament_mask.astype(int)

    # Clip for display (never show 0% / 100%)
    EPS = 0.02
    p_home_win = np.clip(p_home_win_raw, EPS, 1 - EPS)

    pred_margin_home = np.round(pred_margin_home, 1)
    pred_margin_home[np.abs(pred_margin_home) < 0.05] = 0.0
    pred_margin_home_final = pred_margin_home.copy()

    if tournament_neutral.any():
        neutral_scale = np.where(np.abs(pred_margin_home) < 10, 0.84, 0.88)
        p_home_win = np.where(
            tournament_neutral,
            0.5 + (p_home_win - 0.5) * neutral_scale,
            p_home_win,
        )
        p_home_win = np.clip(p_home_win, EPS, 1 - EPS)

    winner_pick = np.where(p_home_win_uncal >= 0.5, model_pregame["home_team"].values, model_pregame["away_team"].values)
    pick_conf   = np.where(p_home_win >= 0.5, p_home_win, 1 - p_home_win)
    spread_pick = np.where(pred_margin_home >= 0, model_pregame["home_team"].values, model_pregame["away_team"].values)

    model_line = np.where(
        np.abs(pred_margin_home) < 0.05,
        "PK",
        np.where(
            pred_margin_home > 0,
            model_pregame["home_team"].values + " -" + np.abs(pred_margin_home).round(1).astype(str),
            model_pregame["away_team"].values + " -" + np.abs(pred_margin_home).round(1).astype(str),
        )
    )
    ml_spread_disagree = (winner_pick != spread_pick) & (np.abs(pred_margin_home) >= 0.05)
    if DEV_MODE and np.any(ml_spread_disagree):
        try:
            _dashboard_log(
                "pred_sign_debug",
                status="ml_spread_disagree",
                games=int(np.sum(ml_spread_disagree)),
                samples=model_pregame.loc[ml_spread_disagree, ["home_team", "away_team"]].head(5).to_dict("records"),
            )
        except Exception:
            pass

    return model_pregame.assign(
        pred_margin_home=pred_margin_home,
        pred_margin_home_raw=pred_margin_home_raw,
        pred_edge_home=pred_edge_home,
        vegas_spread_home=vegas_spread_home.to_numpy(dtype=float),
        market_implied_home_margin=market_implied_home_margin.to_numpy(dtype=float),
        pred_margin_home_market=pred_margin_home_market,
        pred_margin_home_final=pred_margin_home_final,
        has_market_spread=has_market_spread.astype(int),
        tournament_mode_applied=tournament_mode_applied.astype(int),
        p_home_win=p_home_win,
        p_home_win_raw=p_home_win_raw,
        winner_pick=winner_pick,
        pick_conf=pick_conf,
        spread_pick=spread_pick,
        model_line_text=model_line,
        ml_spread_disagree=ml_spread_disagree.astype(int),
    ).copy()


# ============================================================
# CELL 13: BOARD BUILDER
# ============================================================

def build_board_for_date(
    date_et,
    schedule_df, team_snaps, roll_cols,
    spread_booster, winner_booster, lgb_spread,
    iso, imp, feature_cols,
    spread_edge_booster=None, lgb_spread_edge=None,
    elo_snap=None,
    verbose=False,
) -> pd.DataFrame:
    """Full pipeline: pregame features predictions actual score backfill injury merge."""
    _set_build_progress("Preparing slate features...")
    with (suppress_stdout_stderr() if not verbose else contextlib.nullcontext()):
        pregame = build_pregame_dataset_for_slate(
            schedule_df=schedule_df,
            team_snaps=team_snaps,
            roll_cols=roll_cols,
            slate_date_et=date_et,
            window=ROLL_WINDOW,
            elo_snap=elo_snap,
        )

    if pregame is None or len(pregame) == 0:
        return pd.DataFrame()

    _set_build_progress("Normalizing pregame slate...")
    pregame = normalize_board_for_downstream(pregame)
    pregame = _attach_schedule_tournament_context(
        pregame, schedule_df, date_et,
        debug_key=f"pregame_context_{pd.Timestamp(date_et).date()}",
    )
    pregame = _coerce_schedule_tournament_flags(pregame, debug_key=f"pregame_board_{pd.Timestamp(date_et).date()}")
    use_optional_inj = (not _is_past_local_slate(date_et)) or _has_exact_injury_file_for_date(date_et, INJURY_DIR)
    use_optional_rw = (not _is_past_local_slate(date_et)) or _has_exact_rotowire_file_for_date(date_et, ROTOWIRE_DIR)
    if use_optional_inj:
        pregame = attach_injury_features_to_board(pregame, date_et, INJURY_DIR)
    else:
        for col in ["home_injury_impact", "away_injury_impact", "diff_injury_impact", "home_inj_out", "away_inj_out", "injury_impact_A", "injury_impact_B", "inj_out_A", "inj_out_B", "diff_inj_out"]:
            pregame[col] = np.nan
    if use_optional_rw:
        pregame = _attach_rotowire_to_board(pregame, date_et)
    else:
        pregame["rw_missing_reason"] = "No RW odds in file"
    pregame = _add_hybrid_spread_features(pregame)
    pregame = normalize_board_for_downstream(pregame)

    _set_build_progress("Running prediction models...")
    board = predict_slate(
        pregame, spread_booster, winner_booster, lgb_spread,
        iso, imp, feature_cols,
        spread_edge_booster=spread_edge_booster,
        lgb_spread_edge=lgb_spread_edge,
    )

    _set_build_progress("Applying schedule context...")
    board = normalize_board_for_downstream(board)
    board = _attach_schedule_tournament_context(
        board, schedule_df, date_et,
        debug_key=f"board_context_{pd.Timestamp(date_et).date()}",
    )
    board = _coerce_schedule_tournament_flags(board, debug_key=f"board_{pd.Timestamp(date_et).date()}")

    # first try schedule backfill
    _set_build_progress("Backfilling schedule scores...")
    board = attach_actual_scores_from_schedule(board, schedule_df, date_et)
    board = normalize_board_for_downstream(board)

    # then fill any remaining missing finals from team_box history
    if "team_box_hist" in globals() and team_box_hist is not None and len(team_box_hist) > 0:
        _set_build_progress("Backfilling team-box scores...")
        board = attach_actual_scores_from_team_box(board, team_box_hist, date_et)
        board = normalize_board_for_downstream(board)

    # then patch stale same-day / prior-day finals from ESPN scoreboard data
    _set_build_progress("Patching final scores...")
    board = attach_espn_scoreboard_finals_patch(board, date_et)
    board = normalize_board_for_downstream(board)

    _set_build_progress("Checking fresh live scores...")
    board = attach_fresh_scores_from_hoopr(board, date_et)

    # Attach final scores for completed games
    board["home_final"] = pd.to_numeric(board.get("home_score"), errors="coerce")
    board["away_final"] = pd.to_numeric(board.get("away_score"), errors="coerce")

    completed_bool = pd.Series(False, index=board.index)
    for col, vals in [
        ("status_type_completed", ["true", "1", "yes"]),
        ("status_type_state", ["post", "postgame", "final"]),
    ]:
        if col in board.columns:
            completed_bool |= board[col].astype(str).str.lower().isin(vals)

    if "status_type_short_detail" in board.columns:
        completed_bool |= board["status_type_short_detail"].astype(str).str.contains("Final", case=False, na=False)

    finished = completed_bool & board["home_final"].notna() & board["away_final"].notna()

    board["final_score"] = ""
    if finished.any():
        away_p = board.loc[finished, "away_final"].round(0).astype(int).astype(str)
        home_p = board.loc[finished, "home_final"].round(0).astype(int).astype(str)
        board.loc[finished, "final_score"] = (
            board.loc[finished, "away_team"] + " " + away_p + " - " +
            board.loc[finished, "home_team"] + " " + home_p
        )

    # Attach injury features
    if use_optional_inj:
        board = attach_injury_features_to_board(board, date_et, INJURY_DIR)
    else:
        for col in ["home_injury_impact", "away_injury_impact", "diff_injury_impact", "home_inj_out", "away_inj_out", "injury_impact_A", "injury_impact_B", "inj_out_A", "inj_out_B", "diff_inj_out"]:
            board[col] = np.nan
    board = normalize_board_for_downstream(board)
    board = _attach_schedule_tournament_context(
        board, schedule_df, date_et,
        debug_key=f"board_final_context_{pd.Timestamp(date_et).date()}",
    )
    board = _coerce_schedule_tournament_flags(board, debug_key=f"board_final_{pd.Timestamp(date_et).date()}")

    _set_build_progress("Finalizing board rows...")
    # dedupe
    board = _dedupe_game_rows(board)

    return board


def _attach_rotowire_to_board(board: pd.DataFrame, slate_date_et) -> pd.DataFrame:
    """Attaches Rotowire odds to board with home/away flip protection."""
    outb = board.copy()
    rw_cols = ["rw_spread_home", "rw_home_ml", "rw_away_ml", "rw_total", "rw_missing_reason"]
    prior_rw_cols = [c for c in outb.columns if str(c).endswith("_rw")]
    prior_rw_cols += [
        "vegas_spread_home", "has_market_spread", "market_abs_spread", "market_home_fav",
        "vegas_total", "has_market_total",
    ]
    outb = outb.drop(columns=[c for c in (rw_cols + prior_rw_cols) if c in outb.columns], errors="ignore")

    mkt = load_rotowire_all_for_date(slate_date_et, ROTOWIRE_DIR)
    if mkt is None or len(mkt) == 0:
        api = fetch_odds(
            "basketball_ncaab",
            pd.Timestamp(slate_date_et, tz="UTC"),
            pd.Timestamp(slate_date_et, tz="UTC") + pd.Timedelta(days=1),
        )
        if not api.empty:
            mkt = api.rename(columns={
                "odds_api_away_ml": "rw_away_ml",
                "odds_api_home_ml": "rw_home_ml",
                "odds_api_spread_home": "rw_spread_home",
                "odds_api_total": "rw_total",
            })
    debug_date_key = str(pd.Timestamp(slate_date_et).date())
    debug_files = [os.path.basename(f) for f in find_rotowire_files_for_date(slate_date_et, ROTOWIRE_DIR)]
    target_key = "||".join(sorted([canonical_team("Howard Bison"), canonical_team("Michigan Wolverines")]))
    if mkt is None or len(mkt) == 0:
        ROTOWIRE_ATTACH_DEBUG[debug_date_key] = {
            "files": debug_files,
            "raw_parsed_row": [],
            "board_before_attach": [],
            "board_after_attach": [],
        }
        outb["rw_missing_reason"] = "No Rotowire or Odds API odds"
        return outb

    b = outb.copy()
    m = mkt.copy()
    b["k_away"] = b["away_team"].map(canonical_team)
    b["k_home"] = b["home_team"].map(canonical_team)
    m["k_away"] = m["away_team"].map(canonical_team)
    m["k_home"] = m["home_team"].map(canonical_team)
    if "schedule_cur" in globals():
        name_to_id = _build_team_id_name_map(schedule_cur, globals().get("team_snaps"))
        m["away_id"] = m["k_away"].map(name_to_id)
        m["home_id"] = m["k_home"].map(name_to_id)
        b["away_id"] = pd.to_numeric(b.get("away_id"), errors="coerce")
        b["home_id"] = pd.to_numeric(b.get("home_id"), errors="coerce")
        m["away_id"] = pd.to_numeric(m.get("away_id"), errors="coerce")
        m["home_id"] = pd.to_numeric(m.get("home_id"), errors="coerce")
    else:
        b["away_id"] = pd.to_numeric(b.get("away_id"), errors="coerce")
        b["home_id"] = pd.to_numeric(b.get("home_id"), errors="coerce")
        m["away_id"] = np.nan
        m["home_id"] = np.nan
    b["k_game"] = b.apply(lambda r: "||".join(sorted([r["k_away"], r["k_home"]])), axis=1)
    m["k_game"] = m.apply(lambda r: "||".join(sorted([r["k_away"], r["k_home"]])), axis=1)

    debug_raw = m.loc[m["k_game"].eq(target_key), [
        c for c in ["away_team", "home_team", "rw_away_ml", "rw_home_ml", "rw_spread_home", "rw_total", "away_id", "home_id"] if c in m.columns
    ]].copy()
    debug_before = b.loc[b["k_game"].eq(target_key), [
        c for c in ["away_team", "home_team", "away_id", "home_id", "k_away", "k_home"] if c in b.columns
    ]].copy()

    m = m.drop_duplicates("k_game", keep="last")

    merged = b.merge(
        m[["k_game","rw_spread_home","rw_home_ml","rw_away_ml","rw_total","k_home","k_away"]],
        on="k_game", how="left", suffixes=("", "_rw")
    )
    merged["_rw_id_exact_match"] = False
    if {"home_id", "away_id"}.issubset(merged.columns) and {"home_id", "away_id"}.issubset(m.columns):
        has_rw_any = _normalize_bool_mask(
            merged[["rw_spread_home","rw_home_ml","rw_away_ml","rw_total"]].notna().any(axis=1),
            label="has_rw_any",
            context="_attach_rotowire_to_board",
        )
        missing_mask = _normalize_bool_mask(
            ~has_rw_any,
            label="missing_mask",
            context="_attach_rotowire_to_board",
        )
        if missing_mask.any():
            m_id = m.dropna(subset=["home_id", "away_id"]).copy()
            if len(m_id):
                m_id["home_id"] = m_id["home_id"].astype(int)
                m_id["away_id"] = m_id["away_id"].astype(int)
                m_id = m_id.drop_duplicates(subset=["home_id", "away_id"], keep="last")

                left = merged.loc[missing_mask].copy()
                left["home_id"] = pd.to_numeric(left["home_id"], errors="coerce")
                left["away_id"] = pd.to_numeric(left["away_id"], errors="coerce")
                left_valid = left["home_id"].notna() & left["away_id"].notna()
                if left_valid.any():
                    left_valid_df = left.loc[left_valid].copy()
                    left_valid_df["_row_ix"] = left_valid_df.index
                    left_valid_df["home_id"] = left_valid_df["home_id"].astype(int)
                    left_valid_df["away_id"] = left_valid_df["away_id"].astype(int)
                    fix = left_valid_df.merge(
                        m_id[["home_id", "away_id", "rw_spread_home", "rw_home_ml", "rw_away_ml", "rw_total", "k_home", "k_away"]],
                        on=["home_id", "away_id"],
                        how="left",
                        suffixes=("", "_id"),
                    )
                    for c in ["rw_spread_home", "rw_home_ml", "rw_away_ml", "rw_total"]:
                        cid = f"{c}_id"
                        if cid in fix.columns:
                            merged.loc[fix["_row_ix"], c] = merged.loc[fix["_row_ix"], c].where(
                                merged.loc[fix["_row_ix"], c].notna(),
                                fix[cid].values,
                            )
                    if "k_home_id" in fix.columns:
                        merged.loc[fix["_row_ix"], "k_home_rw"] = merged.loc[fix["_row_ix"], "k_home_rw"].where(
                            merged.loc[fix["_row_ix"], "k_home_rw"].notna(),
                            fix["k_home_id"].values,
                        )
                    if "k_away_id" in fix.columns:
                        merged.loc[fix["_row_ix"], "k_away_rw"] = merged.loc[fix["_row_ix"], "k_away_rw"].where(
                            merged.loc[fix["_row_ix"], "k_away_rw"].notna(),
                            fix["k_away_id"].values,
                        )
                    matched_fix = fix[fix["rw_spread_home_id"].notna() | fix["rw_home_ml_id"].notna() | fix["rw_away_ml_id"].notna() | fix["rw_total_id"].notna()]
                    if len(matched_fix):
                        merged.loc[matched_fix["_row_ix"], "_rw_id_exact_match"] = True

    missing_rw = _normalize_bool_mask(
        merged[["rw_spread_home","rw_home_ml","rw_away_ml","rw_total"]].notna().any(axis=1),
        label="missing_rw_has_odds",
        context="_attach_rotowire_to_board",
    )
    for _, row in merged.loc[~missing_rw].head(10).iterrows():
        _record_canonical_mismatch("rotowire_board_unmatched", {
            "date": str(pd.Timestamp(slate_date_et).date()),
            "away_team": row.get("away_team"),
            "home_team": row.get("home_team"),
            "away_canon": row.get("k_away"),
            "home_canon": row.get("k_home"),
            "k_game": row.get("k_game"),
        })

    if "k_home_rw" in merged.columns:
        same_home = _normalize_bool_mask(
            merged["home_team"].map(canonical_team) == merged["k_home_rw"],
            label="same_home_compare",
            context="_attach_rotowire_to_board",
        )
        same_home = _normalize_bool_mask(
            same_home | _normalize_bool_mask(
                merged["_rw_id_exact_match"],
                label="rw_id_exact_match",
                context="_attach_rotowire_to_board",
            ),
            label="same_home",
            context="_attach_rotowire_to_board",
        )
        has_rw = _normalize_bool_mask(
            merged[["rw_spread_home","rw_home_ml","rw_away_ml","rw_total"]].notna().any(axis=1),
            label="has_rw",
            context="_attach_rotowire_to_board",
        )
        flip_mask = _normalize_bool_mask(
            has_rw & (~same_home),
            label="flip_mask",
            context="_attach_rotowire_to_board",
        )
        merged.loc[flip_mask, "rw_spread_home"] = -pd.to_numeric(merged.loc[flip_mask, "rw_spread_home"], errors="coerce")
        old_hml = merged["rw_home_ml"].copy()
        old_aml = merged["rw_away_ml"].copy()
        merged.loc[flip_mask, "rw_home_ml"] = old_aml.loc[flip_mask]
        merged.loc[flip_mask, "rw_away_ml"] = old_hml.loc[flip_mask]

    debug_after = merged.loc[merged["k_game"].eq(target_key), [
        c for c in ["away_team", "home_team", "away_id", "home_id", "rw_away_ml", "rw_home_ml", "rw_spread_home", "rw_total", "k_away", "k_home", "k_away_rw", "k_home_rw", "_rw_id_exact_match"] if c in merged.columns
    ]].copy()
    ROTOWIRE_ATTACH_DEBUG[debug_date_key] = {
        "files": debug_files,
        "raw_parsed_row": debug_raw.to_dict("records"),
        "board_before_attach": debug_before.to_dict("records"),
        "board_after_attach": debug_after.to_dict("records"),
    }

    merged = merged.drop(columns=["k_away","k_home","k_game","k_home_rw","k_away_rw","home_id_rw","away_id_rw","_rw_id_exact_match"], errors="ignore")
    has_rw = _normalize_bool_mask(
        merged[["rw_spread_home","rw_home_ml","rw_away_ml","rw_total"]].notna().any(axis=1),
        label="has_rw_final",
        context="_attach_rotowire_to_board",
    )
    merged["rw_missing_reason"] = np.where(has_rw, "", "No Rotowire or Odds API odds")
    return merged


# ============================================================
# CELL 13B: BACKFILL ACTUAL FINAL SCORES FROM SCHEDULE
# ============================================================

def attach_actual_scores_from_schedule(board: pd.DataFrame, schedule_df: pd.DataFrame, slate_date_et) -> pd.DataFrame:
    """
    Backfill completed scores/status from schedule onto a board built from
    schedule rows or Rotowire fallback rows.

    Matching priority:
      1) exact game_id
      2) same-date exact oriented canonical away/home teams
      3) same-date unordered canonical matchup, with score flip if needed
    """
    if board is None or len(board) == 0:
        return pd.DataFrame()

    out = normalize_board_for_downstream(board.copy())
    if schedule_df is None or len(schedule_df) == 0:
        return out

    sched = schedule_df.copy()

    # -----------------------------
    # normalize schedule datetime
    # -----------------------------
    dt_col = None
    for c in ["game_dt_et", "game_date_time", "start_date", "date"]:
        if c in sched.columns:
            dt_col = c
            break
    if dt_col is None:
        return out

    sched[dt_col] = pd.to_datetime(sched[dt_col], errors="coerce", utc=True)
    if pd.api.types.is_datetime64tz_dtype(sched[dt_col]):
        sched["game_dt_et"] = sched[dt_col].dt.tz_convert("America/New_York").dt.tz_localize(None)
    else:
        sched["game_dt_et"] = pd.to_datetime(sched[dt_col], errors="coerce")

    sched = sched.dropna(subset=["game_dt_et"]).copy()
    sched["slate_date_et"] = sched["game_dt_et"].dt.date
    sched = sched[sched["slate_date_et"] == pd.Timestamp(slate_date_et).date()].copy()

    if len(sched) == 0:
        return out

    # -----------------------------
    # standardize schedule columns
    # -----------------------------
    if "game_id" in sched.columns:
        sched["game_id"] = sched["game_id"].astype(str)

    for c in ["home_score", "away_score", "home_id", "away_id"]:
        if c in sched.columns:
            sched[c] = pd.to_numeric(sched[c], errors="coerce")
        if c in out.columns:
            out[c] = pd.to_numeric(out[c], errors="coerce")

    if "home_team" not in sched.columns:
        if "home_short_display_name" in sched.columns:
            sched["home_team"] = sched["home_short_display_name"].astype(str)
        else:
            sched["home_team"] = "TBD"

    if "away_team" not in sched.columns:
        if "away_short_display_name" in sched.columns:
            sched["away_team"] = sched["away_short_display_name"].astype(str)
        else:
            sched["away_team"] = "TBD"

    sched["home_team"] = sched["home_team"].astype(str)
    sched["away_team"] = sched["away_team"].astype(str)

    out["home_team"] = out["home_team"].astype(str)
    out["away_team"] = out["away_team"].astype(str)

    # canonical keys
    sched["k_home"] = sched["home_team"].map(canonical_team)
    sched["k_away"] = sched["away_team"].map(canonical_team)
    sched["k_game"] = sched.apply(lambda r: "||".join(sorted([r["k_away"], r["k_home"]])), axis=1)

    out["k_home"] = out["home_team"].map(canonical_team)
    out["k_away"] = out["away_team"].map(canonical_team)
    out["k_game"] = out.apply(lambda r: "||".join(sorted([r["k_away"], r["k_home"]])), axis=1)
    out["slate_date_et"] = pd.to_datetime(out["game_dt_et"], errors="coerce").dt.date

    # prefer rows that actually have finals
    sched["has_scores"] = sched["home_score"].notna() & sched["away_score"].notna()
    sched = sched.sort_values(["has_scores", "game_dt_et"], ascending=[False, True]).copy()

    # preserve original board scores/status so we can coalesce cleanly
    for c in ["home_score", "away_score", "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
        if c not in out.columns:
            out[c] = np.nan

    # -----------------------------
    # 1) exact game_id match
    # -----------------------------
    if "game_id" in out.columns and "game_id" in sched.columns:
        gid_lookup = (
            sched.drop_duplicates(subset=["game_id"], keep="first")
                 [["game_id", "home_score", "away_score",
                   "status_type_completed", "status_type_state",
                   "status_type_name", "status_type_short_detail"]]
                 .copy()
        )

        out = out.merge(gid_lookup, on="game_id", how="left", suffixes=("", "_gid"))

        for c in ["home_score", "away_score", "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
            cg = f"{c}_gid"
            if cg in out.columns:
                out[c] = out[c].where(out[c].notna(), out[cg])

        out = out.drop(columns=[c for c in out.columns if c.endswith("_gid")], errors="ignore")

    # -----------------------------
    # 2) exact oriented ID match
    # -----------------------------
    still_missing = out["home_score"].isna() | out["away_score"].isna()
    if still_missing.any():
        orient_id_lookup = (
            sched.dropna(subset=["home_id", "away_id"])
                 .drop_duplicates(subset=["slate_date_et", "home_id", "away_id"], keep="first")
                 [["slate_date_et", "home_id", "away_id",
                   "home_score", "away_score",
                   "status_type_completed", "status_type_state",
                   "status_type_name", "status_type_short_detail"]]
                 .copy()
        )

        tmp = out.loc[still_missing].merge(
            orient_id_lookup,
            on=["slate_date_et", "home_id", "away_id"],
            how="left",
            suffixes=("", "_id")
        )

        for c in ["home_score", "away_score", "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
            ci = f"{c}_id"
            if ci in tmp.columns:
                tmp[c] = tmp[c].where(tmp[c].notna(), tmp[ci])

        out.loc[still_missing, ["home_score", "away_score", "status_type_completed",
                                "status_type_state", "status_type_name", "status_type_short_detail"]] = \
            tmp[["home_score", "away_score", "status_type_completed",
                 "status_type_state", "status_type_name", "status_type_short_detail"]].values

    # -----------------------------
    # 3) exact oriented team match
    # -----------------------------
    still_missing = out["home_score"].isna() | out["away_score"].isna()
    if still_missing.any():
        orient_lookup = (
            sched.drop_duplicates(subset=["slate_date_et", "k_away", "k_home"], keep="first")
                 [["slate_date_et", "k_away", "k_home",
                   "home_score", "away_score",
                   "status_type_completed", "status_type_state",
                   "status_type_name", "status_type_short_detail"]]
                 .copy()
        )

        tmp = out.loc[still_missing].merge(
            orient_lookup,
            on=["slate_date_et", "k_away", "k_home"],
            how="left",
            suffixes=("", "_orient")
        )

        for c in ["home_score", "away_score", "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
            co = f"{c}_orient"
            if co in tmp.columns:
                tmp[c] = tmp[c].where(tmp[c].notna(), tmp[co])

        out.loc[still_missing, ["home_score", "away_score", "status_type_completed",
                                "status_type_state", "status_type_name", "status_type_short_detail"]] = \
            tmp[["home_score", "away_score", "status_type_completed",
                 "status_type_state", "status_type_name", "status_type_short_detail"]].values

    # -----------------------------
    # 4) unordered matchup fallback
    # -----------------------------
    still_missing = out["home_score"].isna() | out["away_score"].isna()
    if still_missing.any():
        unordered_lookup = (
            sched.drop_duplicates(subset=["slate_date_et", "k_game"], keep="first")
                 [["slate_date_et", "k_game", "k_home", "k_away",
                   "home_score", "away_score",
                   "status_type_completed", "status_type_state",
                   "status_type_name", "status_type_short_detail"]]
                 .copy()
        )

        tmp = out.loc[still_missing].merge(
            unordered_lookup,
            on=["slate_date_et", "k_game"],
            how="left",
            suffixes=("", "_unord")
        )

        same_home = tmp["k_home"] == tmp["k_home_unord"]

        # if schedule home matches board home, keep scores as-is; otherwise flip them
        tmp["home_score_fix"] = np.where(same_home, tmp["home_score_unord"], tmp["away_score_unord"])
        tmp["away_score_fix"] = np.where(same_home, tmp["away_score_unord"], tmp["home_score_unord"])

        out.loc[still_missing, "home_score"] = out.loc[still_missing, "home_score"].where(
            out.loc[still_missing, "home_score"].notna(), tmp["home_score_fix"].values
        )
        out.loc[still_missing, "away_score"] = out.loc[still_missing, "away_score"].where(
            out.loc[still_missing, "away_score"].notna(), tmp["away_score_fix"].values
        )

        for c in ["status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
            cu = f"{c}_unord"
            if cu in tmp.columns:
                out.loc[still_missing, c] = out.loc[still_missing, c].where(
                    out.loc[still_missing, c].notna(), tmp[cu].values
                )

    out = out.drop(columns=["k_home", "k_away", "k_game", "slate_date_et"], errors="ignore")
    return out


# ============================================================
# CELL 13C: BACKFILL ACTUAL SCORES FROM TEAM BOX HISTORY
# ============================================================

def _get_team_box_game_lookup(team_box_df: pd.DataFrame) -> pd.DataFrame:
    global TEAM_BOX_GAME_LOOKUP_CACHE

    if team_box_df is None or len(team_box_df) == 0:
        return pd.DataFrame()

    cache_key = (id(team_box_df), int(len(team_box_df)))
    cached = TEAM_BOX_GAME_LOOKUP_CACHE.get(cache_key)
    if cached is not None:
        return cached.copy()

    tb = team_box_df.copy()
    tb["game_id"] = tb["game_id"].astype(str)
    tb["game_date_time"] = pd.to_datetime(tb["game_date_time"], errors="coerce", utc=True)
    tb = tb.dropna(subset=["game_id", "game_date_time"]).copy()

    tb["game_dt_et"] = tb["game_date_time"].dt.tz_convert("America/New_York").dt.tz_localize(None)
    tb["game_date_et"] = tb["game_dt_et"].dt.date

    tb["team_id"] = pd.to_numeric(tb["team_id"], errors="coerce")
    tb["opponent_team_id"] = pd.to_numeric(tb["opponent_team_id"], errors="coerce")
    tb["team_score"] = pd.to_numeric(tb["team_score"], errors="coerce")
    tb["opponent_team_score"] = pd.to_numeric(tb["opponent_team_score"], errors="coerce")

    tb = tb.dropna(subset=[
        "team_id", "opponent_team_id", "team_score", "opponent_team_score"
    ]).copy()

    if len(tb) == 0:
        return pd.DataFrame()

    tb["team_id"] = tb["team_id"].astype("int64")
    tb["opponent_team_id"] = tb["opponent_team_id"].astype("int64")
    tb["id_low"] = np.minimum(tb["team_id"], tb["opponent_team_id"]).astype("int64")
    tb["id_high"] = np.maximum(tb["team_id"], tb["opponent_team_id"]).astype("int64")
    tb = tb.sort_values(["game_dt_et", "game_id", "team_id"]).drop_duplicates(
        subset=["game_id", "team_id"], keep="last"
    )

    a = tb[["game_id", "game_dt_et", "game_date_et", "id_low", "id_high", "team_id", "team_score"]].copy()
    b = tb[["game_id", "team_id", "team_score"]].copy()
    a = a.rename(columns={"team_id": "team1_id", "team_score": "team1_score"})
    b = b.rename(columns={"team_id": "team2_id", "team_score": "team2_score"})

    games = a.merge(b, on="game_id", how="inner")
    games = games[games["team1_id"] != games["team2_id"]].copy()
    games = games.drop_duplicates(subset=["game_id", "id_low", "id_high"], keep="last").copy()

    TEAM_BOX_GAME_LOOKUP_CACHE[cache_key] = games.copy()
    if len(TEAM_BOX_GAME_LOOKUP_CACHE) > 3:
        stale = [k for k in TEAM_BOX_GAME_LOOKUP_CACHE if k != cache_key]
        for k in stale[:-2]:
            TEAM_BOX_GAME_LOOKUP_CACHE.pop(k, None)
    return games.copy()


def _get_prepared_team_snaps(team_snaps_df: pd.DataFrame, roll_cols: list) -> tuple[pd.DataFrame, list]:
    global TEAM_SNAPS_PREP_CACHE

    if team_snaps_df is None or len(team_snaps_df) == 0:
        return pd.DataFrame(), []

    cache_key = (id(team_snaps_df), int(len(team_snaps_df)), tuple(sorted(str(c) for c in (roll_cols or []))))
    cached = TEAM_SNAPS_PREP_CACHE.get(cache_key)
    if cached is not None:
        snaps_cached, use_roll_cols_cached = cached
        return snaps_cached.copy(), list(use_roll_cols_cached)

    snaps = team_snaps_df.copy()
    snaps["team_id"] = pd.to_numeric(snaps.get("team_id"), errors="coerce")
    snaps["game_dt_et"] = pd.to_datetime(snaps.get("game_dt_et"), errors="coerce")
    snaps = snaps.dropna(subset=["team_id", "game_dt_et"]).copy()
    if len(snaps) == 0:
        TEAM_SNAPS_PREP_CACHE[cache_key] = (pd.DataFrame(), [])
        return pd.DataFrame(), []

    snaps["team_id"] = snaps["team_id"].astype("int64")
    snaps["game_dt_et"] = snaps["game_dt_et"].astype("datetime64[ns]")
    snaps = snaps.sort_values(["game_dt_et", "team_id"], kind="mergesort").reset_index(drop=True)
    use_roll_cols = [c for c in (roll_cols or []) if c in snaps.columns]

    TEAM_SNAPS_PREP_CACHE[cache_key] = (snaps.copy(), list(use_roll_cols))
    if len(TEAM_SNAPS_PREP_CACHE) > 3:
        stale = [k for k in TEAM_SNAPS_PREP_CACHE if k != cache_key]
        for k in stale[:-2]:
            TEAM_SNAPS_PREP_CACHE.pop(k, None)
    return snaps.copy(), list(use_roll_cols)


def attach_actual_scores_from_team_box(board: pd.DataFrame, team_box_df: pd.DataFrame, slate_date_et) -> pd.DataFrame:
    """
    Backfill finals from team_box history using TEAM IDS and nearest-date matching.
    This avoids exact-date misses caused by timezone/date parsing differences.
    """
    if board is None or len(board) == 0:
        return pd.DataFrame()
    if team_box_df is None or len(team_box_df) == 0:
        return board.copy()

    out = normalize_board_for_downstream(board.copy())
    target_date = pd.Timestamp(slate_date_et).date()

    games = _get_team_box_game_lookup(team_box_df)
    if len(games) == 0:
        return out

    games = games.copy()
    games["date_diff_days"] = (pd.to_datetime(games["game_date_et"]) - pd.Timestamp(target_date)).dt.days.abs()
    games = games[games["date_diff_days"] <= 2].copy()

    if len(games) == 0:
        return out

    hs0 = pd.to_numeric(out.get("home_score"), errors="coerce")
    aw0 = pd.to_numeric(out.get("away_score"), errors="coerce")
    completed0 = out.get("status_type_completed", pd.Series(False, index=out.index)).astype(str).str.lower().isin(["true", "1", "yes"])
    state0 = out.get("status_type_state", pd.Series("", index=out.index)).astype(str).str.lower()
    detail0 = out.get("status_type_short_detail", pd.Series("", index=out.index)).astype(str)
    final0 = completed0 | state0.isin(["post", "postgame", "final"]) | detail0.str.contains("Final", case=False, na=False)
    replace_mask = hs0.isna() | aw0.isna() | ((hs0 == 0) & (aw0 == 0) & ~final0)

    if "game_id" in out.columns:
        out["game_id"] = out["game_id"].astype(str)
        tmp = out.merge(
            games[["game_id", "team1_id", "team2_id", "team1_score", "team2_score", "game_date_et"]],
            on="game_id",
            how="left",
            suffixes=("", "_tb_gid")
        )
        tmp["home_id"] = pd.to_numeric(tmp.get("home_id"), errors="coerce")
        tmp["away_id"] = pd.to_numeric(tmp.get("away_id"), errors="coerce")
        tmp["team1_id"] = pd.to_numeric(tmp.get("team1_id"), errors="coerce")
        tmp["team2_id"] = pd.to_numeric(tmp.get("team2_id"), errors="coerce")
        tmp["home_score_gid"] = np.where(
            tmp["home_id"] == tmp["team1_id"],
            tmp["team1_score"],
            np.where(tmp["home_id"] == tmp["team2_id"], tmp["team2_score"], np.nan)
        )
        tmp["away_score_gid"] = np.where(
            tmp["away_id"] == tmp["team1_id"],
            tmp["team1_score"],
            np.where(tmp["away_id"] == tmp["team2_id"], tmp["team2_score"], np.nan)
        )
        gid_match = (
            ((tmp["home_id"] == tmp["team1_id"]) & (tmp["away_id"] == tmp["team2_id"])) |
            ((tmp["home_id"] == tmp["team2_id"]) & (tmp["away_id"] == tmp["team1_id"]))
        )
        gid_match = gid_match.fillna(False) if hasattr(gid_match, "fillna") else gid_match

        use_gid = replace_mask & gid_match
        if use_gid.any():
            out.loc[use_gid, "home_score"] = tmp.loc[use_gid, "home_score_gid"].values
            out.loc[use_gid, "away_score"] = tmp.loc[use_gid, "away_score_gid"].values

            if "status_type_completed" not in out.columns:
                out["status_type_completed"] = False
            if "status_type_state" not in out.columns:
                out["status_type_state"] = ""
            if "status_type_short_detail" not in out.columns:
                out["status_type_short_detail"] = ""

            out.loc[use_gid, "status_type_completed"] = True
            out.loc[use_gid, "status_type_state"] = "post"
            out.loc[use_gid, "status_type_short_detail"] = "Final"

    # normalize board ids
    out["home_id"] = pd.to_numeric(out["home_id"], errors="coerce")
    out["away_id"] = pd.to_numeric(out["away_id"], errors="coerce")
    out = out.dropna(subset=["home_id", "away_id"]).copy()

    out["home_id"] = out["home_id"].astype("int64")
    out["away_id"] = out["away_id"].astype("int64")
    out["game_date_et"] = pd.to_datetime(out["game_dt_et"], errors="coerce").dt.date
    out["id_low"] = np.minimum(out["home_id"], out["away_id"]).astype("int64")
    out["id_high"] = np.maximum(out["home_id"], out["away_id"]).astype("int64")

    # for each board row, choose nearest matching completed game
    filled_home = []
    filled_away = []
    filled_done = []

    for _, r in out.iterrows():
        cand = games[
            (games["id_low"] == r["id_low"]) &
            (games["id_high"] == r["id_high"]) &
            (games["game_date_et"] == r["game_date_et"])
        ].copy()

        if len(cand) == 0:
            cand = games[(games["id_low"] == r["id_low"]) & (games["id_high"] == r["id_high"])].copy()

        if len(cand) == 0:
            filled_home.append(np.nan)
            filled_away.append(np.nan)
            filled_done.append(False)
            continue

        cand = cand.sort_values(["date_diff_days", "game_dt_et", "game_id"]).copy()
        g = cand.iloc[0]

        home_is_team1 = int(r["home_id"]) == int(g["team1_id"])
        if home_is_team1:
            hs = g["team1_score"]
            aw = g["team2_score"]
        else:
            hs = g["team2_score"]
            aw = g["team1_score"]

        filled_home.append(hs)
        filled_away.append(aw)
        filled_done.append(pd.notna(hs) and pd.notna(aw))

    hs1 = pd.to_numeric(out.get("home_score"), errors="coerce")
    aw1 = pd.to_numeric(out.get("away_score"), errors="coerce")
    completed1 = out.get("status_type_completed", pd.Series(False, index=out.index)).astype(str).str.lower().isin(["true", "1", "yes"])
    state1 = out.get("status_type_state", pd.Series("", index=out.index)).astype(str).str.lower()
    detail1 = out.get("status_type_short_detail", pd.Series("", index=out.index)).astype(str)
    final1 = completed1 | state1.isin(["post", "postgame", "final"]) | detail1.str.contains("Final", case=False, na=False)
    miss = hs1.isna() | aw1.isna() | ((hs1 == 0) & (aw1 == 0) & ~final1)

    out.loc[miss, "home_score"] = out.loc[miss, "home_score"].where(
        out.loc[miss, "home_score"].notna(), pd.Series(filled_home, index=out.index)[miss]
    )
    out.loc[miss, "away_score"] = out.loc[miss, "away_score"].where(
        out.loc[miss, "away_score"].notna(), pd.Series(filled_away, index=out.index)[miss]
    )

    done_mask = pd.Series(filled_done, index=out.index) & miss

    if "status_type_completed" not in out.columns:
        out["status_type_completed"] = False
    if "status_type_state" not in out.columns:
        out["status_type_state"] = ""
    if "status_type_short_detail" not in out.columns:
        out["status_type_short_detail"] = ""

    out.loc[done_mask, "status_type_completed"] = True
    out.loc[done_mask, "status_type_state"] = "post"
    out.loc[done_mask, "status_type_short_detail"] = "Final"

    out = out.drop(columns=["id_low", "id_high", "game_date_et"], errors="ignore")
    return out

# ============================================================
# CELL 13D: YESTERDAY / SAME-DAY FINAL SCORE FALLBACK VIA hoopR
# Uses hoopR game-level ESPN summary endpoints for fresher finals
# PATCHED:
#   - suppresses noisy R console warnings
#   - removes duplicate function definitions
#   - dedupes scoreboard / fresh games cleanly
# ============================================================

from rpy2.robjects import r
import rpy2.rinterface_lib.callbacks as rcb
from contextlib import contextmanager


@contextmanager
def suppress_r_console():
    """
    Temporarily suppress R console output forwarded through rpy2.
    """
    old_print = rcb.consolewrite_print
    old_warn = rcb.consolewrite_warnerror
    rcb.consolewrite_print = lambda x: None
    rcb.consolewrite_warnerror = lambda x: None
    try:
        yield
    finally:
        rcb.consolewrite_print = old_print
        rcb.consolewrite_warnerror = old_warn


def _run_r_dataframe(r_code: str, assigns: dict | None = None) -> pd.DataFrame:
    """
    Execute R code and convert the result to a plain pandas DataFrame using
    an explicit local converter context each time. This avoids relying on
    ambient rpy2 conversion state across widget callbacks.
    """
    import rpy2.robjects as ro
    from rpy2.robjects import pandas2ri
    from rpy2.robjects.conversion import localconverter

    with suppress_r_console():
        with localconverter(ro.default_converter + pandas2ri.converter):
            if assigns:
                for key, value in assigns.items():
                    ro.globalenv[key] = value
            obj = ro.r(r_code)

    if obj is None:
        return pd.DataFrame()
    try:
        df = pd.DataFrame(obj)
    except Exception:
        return pd.DataFrame()
    return df if df is not None else pd.DataFrame()


def fetch_mbb_scoreboard_game_ids_r(date_et) -> pd.DataFrame:
    """
    Returns one row per game on a specific date from hoopR::espn_mbb_scoreboard("YYYYMMDD").
    Dedupe by game_id because hoopR can return duplicate rows on some dates.
    """
    date_str = pd.Timestamp(date_et).strftime("%Y%m%d")

    r_code = r'''
    suppressPackageStartupMessages(library(hoopR))

    sb <- tryCatch(
      hoopR::espn_mbb_scoreboard(DATE_STR),
      error = function(e) data.frame()
    )

    if (!is.data.frame(sb) || nrow(sb) == 0) {
      out <- data.frame()
    } else {
      keep <- intersect(
        c("game_id",
          "home_team_id", "away_team_id",
          "home_team_display_name", "away_team_display_name",
          "home_team_short_display_name", "away_team_short_display_name",
          "game_date_time"),
        names(sb)
      )
      out <- sb[, keep, drop = FALSE]

      if ("game_id" %in% names(out)) {
        out$game_id <- as.character(out$game_id)
        out <- out[!duplicated(out$game_id), , drop = FALSE]
      }
    }

    out
    '''

    df = _run_r_dataframe(r_code, {"DATE_STR": date_str})

    if df is None or len(df) == 0:
        return pd.DataFrame()

    out = pd.DataFrame(df)
    if "game_id" in out.columns:
        out["game_id"] = out["game_id"].astype(str)
    return out


def fetch_mbb_scoreboard_finals_r(date_et) -> pd.DataFrame:
    """
    Pull a fresh ESPN scoreboard snapshot for one date and keep only
    completed/final games with scores for dashboard final-score patching.
    """
    date_str = pd.Timestamp(date_et).strftime("%Y%m%d")

    r_code = r'''
    suppressPackageStartupMessages(library(hoopR))

    sb <- tryCatch(
      hoopR::espn_mbb_scoreboard(DATE_STR),
      error = function(e) data.frame()
    )

    if (!is.data.frame(sb) || nrow(sb) == 0) {
      out <- data.frame()
    } else {
      keep <- intersect(
        c("game_id",
          "home_team_display_name", "away_team_display_name",
          "home_team_short_display_name", "away_team_short_display_name",
          "home_score", "away_score",
          "home_team_score", "away_team_score",
          "status_name", "status_type_name", "status_type_state",
          "status_type_completed", "status_type_short_detail",
          "game_date_time"),
        names(sb)
      )
      out <- sb[, keep, drop = FALSE]
    }

    out
    '''

    df = _run_r_dataframe(r_code, {"DATE_STR": date_str})

    if df is None or len(df) == 0:
        return pd.DataFrame()

    out = pd.DataFrame(df)
    if len(out) == 0:
        return pd.DataFrame()

    if "home_team_display_name" in out.columns:
        out["home_team"] = out["home_team_display_name"].astype(str).str.strip()
    elif "home_team_short_display_name" in out.columns:
        out["home_team"] = out["home_team_short_display_name"].astype(str).str.strip()
    else:
        out["home_team"] = ""

    if "away_team_display_name" in out.columns:
        out["away_team"] = out["away_team_display_name"].astype(str).str.strip()
    elif "away_team_short_display_name" in out.columns:
        out["away_team"] = out["away_team_short_display_name"].astype(str).str.strip()
    else:
        out["away_team"] = ""

    if "home_score" not in out.columns and "home_team_score" in out.columns:
        out["home_score"] = out["home_team_score"]
    if "away_score" not in out.columns and "away_team_score" in out.columns:
        out["away_score"] = out["away_team_score"]

    for c in ["game_id", "status_name", "status_type_name", "status_type_state", "status_type_short_detail"]:
        if c not in out.columns:
            out[c] = ""
    for c in ["home_score", "away_score"]:
        if c not in out.columns:
            out[c] = np.nan

    out["game_id"] = out["game_id"].astype(str)
    out["home_score"] = pd.to_numeric(out["home_score"], errors="coerce")
    out["away_score"] = pd.to_numeric(out["away_score"], errors="coerce")

    status_blob = (
        out["status_name"].astype(str).fillna("") + " " +
        out["status_type_name"].astype(str).fillna("") + " " +
        out["status_type_state"].astype(str).fillna("") + " " +
        out["status_type_short_detail"].astype(str).fillna("")
    ).str.lower()

    completed = pd.to_numeric(
        out.get("status_type_completed", pd.Series(np.nan, index=out.index)),
        errors="coerce"
    ).fillna(0).astype(int).eq(1)
    completed |= status_blob.str.contains(r"final|post|complete", case=False, na=False)
    completed |= out["home_score"].notna() & out["away_score"].notna()

    out = out[completed].copy()
    if len(out) == 0:
        return pd.DataFrame()

    out["status_type_completed"] = True
    out["status_type_state"] = "post"
    out["status_type_name"] = out["status_type_name"].astype(str).replace("", "STATUS_FINAL")
    out["status_type_short_detail"] = out["status_type_short_detail"].astype(str).replace("", "Final")
    out["final_score"] = np.where(
        out["home_score"].notna() & out["away_score"].notna(),
        out["away_team"] + " " + out["away_score"].round(0).astype(int).astype(str) + " - " +
        out["home_team"] + " " + out["home_score"].round(0).astype(int).astype(str),
        "",
    )
    out["slate_date_et"] = pd.Timestamp(date_et).date()
    out["k_away"] = out["away_team"].map(canonical_team)
    out["k_home"] = out["home_team"].map(canonical_team)

    out = out.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)
    return out[[
        "game_id", "away_team", "home_team", "away_score", "home_score", "final_score",
        "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail",
        "slate_date_et", "k_away", "k_home"
    ]].copy()


def fetch_mbb_team_boxes_for_game_ids_r(game_ids) -> pd.DataFrame:
    """
    Pull fresh game-level team box scores using hoopR::espn_mbb_team_box(game_id).
    Suppresses noisy console messages for unavailable IDs.
    """
    game_ids = [str(g) for g in game_ids if pd.notna(g)]
    if len(game_ids) == 0:
        return pd.DataFrame()

    r_code = r'''
    suppressPackageStartupMessages(library(hoopR))
    suppressPackageStartupMessages(library(dplyr))

    pull_one <- function(gid) {
      tryCatch({
        zz <- capture.output({
          x <- suppressMessages(
                 suppressWarnings(
                   hoopR::espn_mbb_team_box(as.numeric(gid))
                 )
               )
        })
        if (!is.data.frame(x) || nrow(x) == 0) return(data.frame())
        x$game_id <- as.character(x$game_id)
        x
      }, error = function(e) {
        data.frame()
      })
    }

    lst <- lapply(GAME_IDS, pull_one)
    lst <- lst[vapply(lst, nrow, integer(1)) > 0]

    if (length(lst) == 0) {
      out <- data.frame()
    } else {
      out <- bind_rows(lst)
    }

    out
    '''

    df = _run_r_dataframe(r_code, {"GAME_IDS": game_ids})

    if df is None or len(df) == 0:
        return pd.DataFrame()

    out = pd.DataFrame(df)
    if "game_id" in out.columns:
        out["game_id"] = out["game_id"].astype(str)

    # hard dedupe
    dedupe_cols = [c for c in ["game_id", "team_id"] if c in out.columns]
    if dedupe_cols:
        out = out.drop_duplicates(subset=dedupe_cols, keep="last").reset_index(drop=True)

    return out


def build_fresh_team_box_scores_for_date(date_et) -> pd.DataFrame:
    """
    Returns one row per game with fresh home/away final scores for a date.
    Uses scoreboard -> game_ids -> espn_mbb_team_box(game_id).
    """
    sb = fetch_mbb_scoreboard_game_ids_r(date_et)
    if sb is None or len(sb) == 0 or "game_id" not in sb.columns:
        return pd.DataFrame()

    team_boxes = fetch_mbb_team_boxes_for_game_ids_r(sb["game_id"].tolist())
    if team_boxes is None or len(team_boxes) == 0:
        return pd.DataFrame()

    tb = team_boxes.copy()

    for c in ["game_id", "team_id", "opponent_team_id", "team_score", "opponent_team_score"]:
        if c not in tb.columns:
            tb[c] = np.nan

    tb["game_id"] = tb["game_id"].astype(str)
    tb["team_id"] = pd.to_numeric(tb["team_id"], errors="coerce")
    tb["opponent_team_id"] = pd.to_numeric(tb["opponent_team_id"], errors="coerce")
    tb["team_score"] = pd.to_numeric(tb["team_score"], errors="coerce")
    tb["opponent_team_score"] = pd.to_numeric(tb["opponent_team_score"], errors="coerce")

    # --------------------------------------------------------
    # preferred path: explicit home/away
    # --------------------------------------------------------
    if "team_home_away" in tb.columns:
        home = tb[tb["team_home_away"].astype(str).str.lower().eq("home")].copy()
        away = tb[tb["team_home_away"].astype(str).str.lower().eq("away")].copy()

        if len(home) and len(away):
            home = home[["game_id", "team_id", "team_score"]].rename(
                columns={"team_id": "home_id", "team_score": "home_score"}
            )
            away = away[["game_id", "team_id", "team_score"]].rename(
                columns={"team_id": "away_id", "team_score": "away_score"}
            )

            out = home.merge(away, on="game_id", how="inner")
            out["status_type_completed"] = True
            out["status_type_state"] = "post"
            out["status_type_short_detail"] = "Final"

            out = out.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)
            return out

    # --------------------------------------------------------
    # fallback path: infer from two team rows
    # --------------------------------------------------------
    tb = tb.dropna(subset=["game_id", "team_id", "opponent_team_id", "team_score"]).copy()
    tb = tb.drop_duplicates(subset=["game_id", "team_id"], keep="last").reset_index(drop=True)

    rows = []
    for gid, g in tb.groupby("game_id", sort=False):
        g = g.drop_duplicates(subset=["team_id"], keep="last").copy()
        if len(g) != 2:
            continue

        r1 = g.iloc[0]
        r2 = g.iloc[1]

        rows.append({
            "game_id": str(gid),
            "team1_id": int(r1["team_id"]),
            "team2_id": int(r2["team_id"]),
            "team1_score": float(r1["team_score"]),
            "team2_score": float(r2["team_score"]),
            "status_type_completed": True,
            "status_type_state": "post",
            "status_type_short_detail": "Final",
        })

    out = pd.DataFrame(rows)
    if len(out):
        out = out.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)
    return out


def attach_fresh_scores_from_hoopr(board: pd.DataFrame, date_et) -> pd.DataFrame:
    """
    Merge freshest available finals from scoreboard/team_box-by-game onto the board.
    Only queries scoreboard games that match board team IDs.
    Also overwrites stale placeholder rows like 0-0 / pre.
    """
    if board is None or len(board) == 0:
        return pd.DataFrame()

    out = board.copy()

    for c in ["home_score", "away_score"]:
        if c not in out.columns:
            out[c] = np.nan
    for c in ["status_type_completed", "status_type_state", "status_type_short_detail"]:
        if c not in out.columns:
            out[c] = np.nan

    target_date = pd.Timestamp(date_et).date()
    today_et = pd.Timestamp.now(tz="America/New_York").date()
    if (not IN_COLAB) or target_date < today_et:
        return out

    # --------------------------------------------------------
    # pull scoreboard rows for the date
    # --------------------------------------------------------
    sb = fetch_mbb_scoreboard_game_ids_r(date_et)
    if sb is None or len(sb) == 0 or "game_id" not in sb.columns:
        return out

    for c in ["home_team_id", "away_team_id"]:
        if c in sb.columns:
            sb[c] = pd.to_numeric(sb[c], errors="coerce")

    out["home_id"] = pd.to_numeric(out["home_id"], errors="coerce")
    out["away_id"] = pd.to_numeric(out["away_id"], errors="coerce")

    # --------------------------------------------------------
    # keep only scoreboard rows relevant to the board
    # --------------------------------------------------------
    board_pairs = set()
    for h, a in zip(out["home_id"], out["away_id"]):
        if pd.notna(h) and pd.notna(a):
            board_pairs.add((int(h), int(a)))
            board_pairs.add((int(a), int(h)))

    if {"home_team_id", "away_team_id"}.issubset(sb.columns):
        sb = sb[
            sb.apply(
                lambda r: (
                    pd.notna(r["home_team_id"]) and
                    pd.notna(r["away_team_id"]) and
                    (int(r["home_team_id"]), int(r["away_team_id"])) in board_pairs
                ),
                axis=1
            )
        ].copy()

    if len(sb) == 0:
        return out

    sb = sb.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)

    # --------------------------------------------------------
    # fetch fresh team boxes only for relevant game_ids
    # --------------------------------------------------------
    fresh = fetch_mbb_team_boxes_for_game_ids_r(sb["game_id"].astype(str).tolist())
    if fresh is None or len(fresh) == 0:
        return out

    tb = fresh.copy()

    for c in ["game_id", "team_id", "opponent_team_id", "team_score", "opponent_team_score"]:
        if c not in tb.columns:
            tb[c] = np.nan

    tb["game_id"] = tb["game_id"].astype(str)
    tb["team_id"] = pd.to_numeric(tb["team_id"], errors="coerce")
    tb["opponent_team_id"] = pd.to_numeric(tb["opponent_team_id"], errors="coerce")
    tb["team_score"] = pd.to_numeric(tb["team_score"], errors="coerce")
    tb["opponent_team_score"] = pd.to_numeric(tb["opponent_team_score"], errors="coerce")

    # --------------------------------------------------------
    # build one row per game with home/away scores
    # --------------------------------------------------------
    if "team_home_away" in tb.columns:
        home = tb[tb["team_home_away"].astype(str).str.lower().eq("home")].copy()
        away = tb[tb["team_home_away"].astype(str).str.lower().eq("away")].copy()

        home = home[["game_id", "team_id", "team_score"]].rename(
            columns={"team_id": "home_id", "team_score": "home_score"}
        )
        away = away[["game_id", "team_id", "team_score"]].rename(
            columns={"team_id": "away_id", "team_score": "away_score"}
        )

        fresh_games = home.merge(away, on="game_id", how="inner")
    else:
        tb = tb.dropna(subset=["game_id", "team_id", "opponent_team_id", "team_score"]).copy()
        tb = tb.drop_duplicates(subset=["game_id", "team_id"], keep="last").reset_index(drop=True)

        rows = []
        for gid, g in tb.groupby("game_id", sort=False):
            if len(g) != 2:
                continue
            r1 = g.iloc[0]
            r2 = g.iloc[1]
            rows.append({
                "game_id": str(gid),
                "team1_id": int(r1["team_id"]),
                "team2_id": int(r2["team_id"]),
                "team1_score": float(r1["team_score"]),
                "team2_score": float(r2["team_score"]),
            })

        fresh_games = pd.DataFrame(rows)

    if len(fresh_games) == 0:
        return out

    fresh_games["status_type_completed"] = True
    fresh_games["status_type_state"] = "post"
    fresh_games["status_type_short_detail"] = "Final"

    if "game_id" in fresh_games.columns:
        fresh_games = fresh_games.drop_duplicates(subset=["game_id"], keep="last").reset_index(drop=True)

    # --------------------------------------------------------
    # helper: stale placeholder rows that should be overwritten
    # --------------------------------------------------------
    def _needs_score_replace(df: pd.DataFrame) -> pd.Series:
        hs = pd.to_numeric(df.get("home_score"), errors="coerce")
        aw = pd.to_numeric(df.get("away_score"), errors="coerce")

        completed = df.get("status_type_completed", pd.Series(False, index=df.index)).astype(str).str.lower().isin(["true", "1", "yes"])
        state_pre = df.get("status_type_state", pd.Series("", index=df.index)).astype(str).str.lower().isin(["pre", "scheduled"])
        state_final = df.get("status_type_state", pd.Series("", index=df.index)).astype(str).str.lower().isin(["post", "postgame", "final"])
        detail_final = df.get("status_type_short_detail", pd.Series("", index=df.index)).astype(str).str.contains("Final", case=False, na=False)

        has_real_final = completed | state_final | detail_final
        placeholder_zero = hs.fillna(-999).eq(0) & aw.fillna(-999).eq(0) & state_pre & (~has_real_final)
        missing_scores = hs.isna() | aw.isna()

        return missing_scores | placeholder_zero

    # --------------------------------------------------------
    # exact game_id match first
    # --------------------------------------------------------
    if "game_id" in out.columns and "game_id" in fresh_games.columns and {"home_id", "away_id", "home_score", "away_score"}.issubset(fresh_games.columns):
        tmp = fresh_games[[
            "game_id", "home_score", "away_score",
            "status_type_completed", "status_type_state", "status_type_short_detail"
        ]].copy()

        tmp["game_id"] = tmp["game_id"].astype(str)
        out["game_id"] = out["game_id"].astype(str)

        out = out.merge(tmp, on="game_id", how="left", suffixes=("", "_fresh_gid"))
        replace_mask = _needs_score_replace(out)

        for c in ["home_score", "away_score", "status_type_completed", "status_type_state", "status_type_short_detail"]:
            fc = f"{c}_fresh_gid"
            if fc in out.columns:
                out.loc[replace_mask, c] = np.where(
                    out.loc[replace_mask, fc].notna(),
                    out.loc[replace_mask, fc],
                    out.loc[replace_mask, c]
                )

        out = out.drop(columns=[c for c in out.columns if c.endswith("_fresh_gid")], errors="ignore")

    # --------------------------------------------------------
    # fallback by oriented home/away IDs
    # --------------------------------------------------------
    replace_mask = _needs_score_replace(out)
    if replace_mask.any() and {"home_id", "away_id", "home_score", "away_score"}.issubset(fresh_games.columns):
        tmp = out.loc[replace_mask].copy()

        fg = fresh_games[[
            "home_id", "away_id", "home_score", "away_score",
            "status_type_completed", "status_type_state", "status_type_short_detail"
        ]].copy()

        fg["home_id"] = pd.to_numeric(fg["home_id"], errors="coerce")
        fg["away_id"] = pd.to_numeric(fg["away_id"], errors="coerce")
        fg = fg.drop_duplicates(subset=["home_id", "away_id"], keep="last").reset_index(drop=True)

        tmp = tmp.merge(
            fg,
            on=["home_id", "away_id"],
            how="left",
            suffixes=("", "_fresh_id")
        )

        for c in ["home_score", "away_score", "status_type_completed", "status_type_state", "status_type_short_detail"]:
            fc = f"{c}_fresh_id"
            if fc in tmp.columns:
                tmp[c] = np.where(tmp[fc].notna(), tmp[fc], tmp[c])

        out.loc[replace_mask, [
            "home_score", "away_score",
            "status_type_completed", "status_type_state", "status_type_short_detail"
        ]] = tmp[[
            "home_score", "away_score",
            "status_type_completed", "status_type_state", "status_type_short_detail"
        ]].values

    # final hard dedupe
    dedupe_cols = [c for c in ["game_id", "away_team", "home_team", "game_dt_et"] if c in out.columns]
    if dedupe_cols:
        out = out.drop_duplicates(subset=dedupe_cols, keep="last").reset_index(drop=True)

    return out


def attach_espn_scoreboard_finals_patch(board: pd.DataFrame, date_et) -> pd.DataFrame:
    """
    Patch stale finals from hoopR ESPN scoreboard data.
    Prefers exact game_id, then falls back to normalized away/home/date matching.
    Optionally uses team-box game scores as a second pass if scoreboard scores are missing.
    """
    if board is None or len(board) == 0:
        return pd.DataFrame()

    out = normalize_board_for_downstream(board.copy())
    target_date = pd.Timestamp(date_et).date()
    today_et = pd.Timestamp.now(tz="America/New_York").date()
    if (not IN_COLAB) and target_date < today_et:
        return out

    try:
        patch = fetch_mbb_scoreboard_finals_r(date_et)
    except Exception:
        return out
    if patch is None or len(patch) == 0:
        return out

    if patch["home_score"].isna().any() or patch["away_score"].isna().any():
        try:
            tb_patch = build_fresh_team_box_scores_for_date(date_et)
        except Exception:
            tb_patch = pd.DataFrame()
        if tb_patch is not None and len(tb_patch) > 0:
            tb_patch = tb_patch.copy()
            tb_patch["game_id"] = tb_patch["game_id"].astype(str)
            patch = patch.merge(
                tb_patch[["game_id", "home_score", "away_score"]].rename(
                    columns={"home_score": "home_score_tb", "away_score": "away_score_tb"}
                ),
                on="game_id",
                how="left",
            )
            patch["home_score"] = patch["home_score"].where(patch["home_score"].notna(), patch["home_score_tb"])
            patch["away_score"] = patch["away_score"].where(patch["away_score"].notna(), patch["away_score_tb"])
            patch = patch.drop(columns=["home_score_tb", "away_score_tb"], errors="ignore")
            patch["final_score"] = np.where(
                patch["home_score"].notna() & patch["away_score"].notna(),
                patch["away_team"] + " " + patch["away_score"].round(0).astype(int).astype(str) + " - " +
                patch["home_team"] + " " + patch["home_score"].round(0).astype(int).astype(str),
                patch["final_score"].astype(str),
            )

    for c in ["home_score", "away_score"]:
        if c not in out.columns:
            out[c] = np.nan
    for c in ["status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail", "final_score"]:
        if c not in out.columns:
            out[c] = ""

    hs0 = pd.to_numeric(out.get("home_score"), errors="coerce")
    aw0 = pd.to_numeric(out.get("away_score"), errors="coerce")
    completed0 = out.get("status_type_completed", pd.Series(False, index=out.index)).astype(str).str.lower().isin(["true", "1", "yes"])
    state0 = out.get("status_type_state", pd.Series("", index=out.index)).astype(str).str.lower()
    detail0 = out.get("status_type_short_detail", pd.Series("", index=out.index)).astype(str)
    replace_mask = hs0.isna() | aw0.isna() | ((hs0 == 0) & (aw0 == 0) & ~completed0 & ~state0.isin(["post", "postgame", "final"]) & ~detail0.str.contains("Final", case=False, na=False))

    if "game_id" in out.columns:
        out["game_id"] = out["game_id"].astype(str)
        tmp = out.merge(
            patch[[
                "game_id", "home_score", "away_score", "final_score",
                "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"
            ]],
            on="game_id",
            how="left",
            suffixes=("", "_espn"),
        )
        gid_hit = (
            tmp.get("home_score_espn", pd.Series(np.nan, index=tmp.index)).notna() |
            tmp.get("away_score_espn", pd.Series(np.nan, index=tmp.index)).notna() |
            tmp.get("final_score_espn", pd.Series("", index=tmp.index)).astype(str).str.strip().ne("")
        )
        use_gid = replace_mask & gid_hit
        if use_gid.any():
            for c in ["home_score", "away_score", "final_score", "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
                ce = f"{c}_espn"
                if ce in tmp.columns:
                    src = tmp.loc[use_gid, ce]
                    if len(src) == 0:
                        continue

                    src_num = pd.to_numeric(src, errors="coerce")
                    src_all_nan = src.isna().all() if hasattr(src, "isna") else False
                    src_num_all_nan = src_num.isna().all() if hasattr(src_num, "isna") else True
                    if src_all_nan and src_num_all_nan:
                        continue

                    dest_is_bool = False
                    if c in out.columns:
                        try:
                            dest_is_bool = pd.api.types.is_bool_dtype(out[c]) or str(out[c].dtype) == "boolean"
                        except Exception:
                            dest_is_bool = False

                    if dest_is_bool:
                        valid = src.notna()
                        if valid.any():
                            out.loc[out.index[use_gid][valid.values], c] = src.loc[valid].astype("boolean").values
                    else:
                        out.loc[use_gid, c] = src.values

    still_missing = pd.to_numeric(out.get("home_score"), errors="coerce").isna() | pd.to_numeric(out.get("away_score"), errors="coerce").isna()
    if still_missing.any():
        out["slate_date_et"] = pd.to_datetime(out.get("game_dt_et"), errors="coerce").dt.date
        tmp = out.loc[still_missing].merge(
            patch[[
                "slate_date_et", "k_away", "k_home",
                "home_score", "away_score", "final_score",
                "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"
            ]],
            on=["slate_date_et", "k_away", "k_home"],
            how="left",
            suffixes=("", "_espn_match"),
        )
        hit = (
            tmp.get("home_score_espn_match", pd.Series(np.nan, index=tmp.index)).notna() |
            tmp.get("away_score_espn_match", pd.Series(np.nan, index=tmp.index)).notna() |
            tmp.get("final_score_espn_match", pd.Series("", index=tmp.index)).astype(str).str.strip().ne("")
        )
        if hit.any():
            hit_idx = out.loc[still_missing].index[hit.values]
            for c in ["home_score", "away_score", "final_score", "status_type_completed", "status_type_state", "status_type_name", "status_type_short_detail"]:
                ce = f"{c}_espn_match"
                if ce in tmp.columns:
                    src = tmp.loc[hit, ce]
                    if len(src) == 0:
                        continue

                    src_num = pd.to_numeric(src, errors="coerce")
                    src_all_nan = src.isna().all() if hasattr(src, "isna") else False
                    src_num_all_nan = src_num.isna().all() if hasattr(src_num, "isna") else True
                    if src_all_nan and src_num_all_nan:
                        continue

                    dest_is_bool = False
                    if c in out.columns:
                        try:
                            dest_is_bool = pd.api.types.is_bool_dtype(out[c]) or str(out[c].dtype) == "boolean"
                        except Exception:
                            dest_is_bool = False

                    if dest_is_bool:
                        valid = src.notna()
                        if valid.any():
                            out.loc[hit_idx[valid.values], c] = src.loc[valid].astype("boolean").values
                    else:
                        out.loc[hit_idx, c] = src.values

    out = out.drop(columns=["slate_date_et"], errors="ignore")
    return out

# ============================================================
# CELL 14: ACCURACY METRICS
# ============================================================

def _get_home_vegas_spread(board: pd.DataFrame) -> pd.Series:
    for c in ["rw_spread_home", "vegas_spread_home", "spread_home", "home_spread"]:
        if c in board.columns:
            return pd.to_numeric(board[c], errors="coerce")

    if "Vegas Spread" in board.columns:
        out = pd.Series(np.nan, index=board.index, dtype="float64")
        for idx, (txt, ht, at) in enumerate(zip(
            board["Vegas Spread"].astype(str),
            board.get("home_team", pd.Series("", index=board.index)).astype(str),
            board.get("away_team", pd.Series("", index=board.index)).astype(str),
        )):
            s = txt.strip()
            if not s:
                continue
            if s.upper() == "PK":
                out.iloc[idx] = 0.0
                continue
            m = re.search(r"(-?\d+(?:\.\d+)?)", s)
            if not m:
                continue
            line = abs(float(m.group(1)))
            if ht and s.startswith(ht):
                out.iloc[idx] = -line
            elif at and s.startswith(at):
                out.iloc[idx] = line
            else:
                out.iloc[idx] = float(m.group(1))
        return out

    return pd.Series(np.nan, index=board.index, dtype="float64")


def compute_daily_accuracy(board: pd.DataFrame) -> dict:
    if board is None or len(board) == 0:
        return {}


    g = board.copy()
    g["final_score"] = g.get("final_score", "").astype(str)

    completed = g.get("status_type_completed", pd.Series(False, index=g.index)).astype(str).str.lower().isin(["true", "1", "yes"])
    state_final = g.get("status_type_state", pd.Series("", index=g.index)).astype(str).str.lower().isin(["post", "postgame", "final"])
    detail_final = g.get("status_type_short_detail", pd.Series("", index=g.index)).astype(str).str.contains("Final", case=False, na=False)
    score_present = g["final_score"].str.strip().ne("")
    real_final_mask = completed | state_final | detail_final | score_present
    g = g[real_final_mask & score_present].copy()
    if len(g) == 0:
        return {}


    score_parts = g["final_score"].astype(str).str.extractall(r"(\d+)").groupby(level=0)[0].agg(list)
    score_parts = score_parts.reindex(g.index)
    g["away_pts"] = score_parts.map(lambda vals: float(vals[-2]) if isinstance(vals, list) and len(vals) >= 2 else np.nan)
    g["home_pts"] = score_parts.map(lambda vals: float(vals[-1]) if isinstance(vals, list) and len(vals) >= 2 else np.nan)
    g = g.dropna(subset=["away_pts", "home_pts"]).copy()
    if len(g) == 0:
        return {}

    g["home_margin_actual"] = g["home_pts"] - g["away_pts"]

    g["actual_winner"] = np.where(
        g["home_pts"] > g["away_pts"], g["home_team"],
        np.where(g["away_pts"] > g["home_pts"], g["away_team"], "PUSH")
    )

    pick_col = "winner_pick" if "winner_pick" in g.columns else None
    winner_acc = np.nan
    if pick_col:
        w = g[g["actual_winner"] != "PUSH"]
        if len(w):
            winner_acc = float((w[pick_col].astype(str) == w["actual_winner"].astype(str)).mean())

    spread_acc = np.nan
    margin_mae = np.nan
    within_5 = np.nan
    if "pred_margin_home" in g.columns:
        pm = pd.to_numeric(g["pred_margin_home"], errors="coerce")
        am = pd.to_numeric(g["home_margin_actual"], errors="coerce")
        valid = pm.notna() & am.notna()
        if valid.any():
            spread_correct = np.where(
                pm[valid] > 0,
                am[valid] > pm[valid],
                np.where(pm[valid] < 0, am[valid] < pm[valid], am[valid] == 0)
            )
            spread_acc = float(np.mean(spread_correct))
            err = (pm[valid] - am[valid]).abs()
            margin_mae = float(err.mean())
            within_5 = float((err <= 5).mean())

    ats_acc, ats_games = np.nan, 0
    vegas_spread_home = _get_home_vegas_spread(g)
    if vegas_spread_home.notna().any() and "pred_margin_home" in g.columns:
        ats_threshold = float(_get_ats_edge_threshold())
        rg = pd.DataFrame({
            "vegas_spread_home": pd.to_numeric(vegas_spread_home, errors="coerce"),
            "pred_margin_home": pd.to_numeric(g["pred_margin_home"], errors="coerce"),
            "home_margin_actual": pd.to_numeric(g["home_margin_actual"], errors="coerce"),
        }, index=g.index).dropna()
        if len(rg) > 0:
            rg["edge"] = rg["pred_margin_home"] + rg["vegas_spread_home"]
            rg = rg[rg["edge"].abs() >= ats_threshold].copy()
            if len(rg) > 0:
                rg["pick_home"] = rg["edge"] > 0
                rg["cover_margin"] = rg["home_margin_actual"] + rg["vegas_spread_home"]
                non_push = rg["cover_margin"] != 0
                rg = rg[non_push].copy()
                if len(rg) > 0:
                    ats_result = np.where(rg["pick_home"], rg["cover_margin"] > 0, rg["cover_margin"] < 0)
                    ats_acc = float(np.mean(ats_result))
                    ats_games = int(len(rg))


    return {
        "games_graded": len(g),
        "winner_acc": winner_acc,
        "spread_side_acc": spread_acc,
        "margin_mae": margin_mae,
        "within_5": within_5,
        "ats_acc": ats_acc,
        "ats_games": ats_games,
    }


def render_accuracy_banner(acc: dict, date_et=None) -> str:
    def fmt(x, pct=True):
        if x is None or (isinstance(x, float) and np.isnan(x)):
            return ""
        return f"{x*100:.1f}%" if pct else f"{x:.2f}"

    label = f"… {date_et}" if date_et else "ˆ Season-to-Date"
    return f"""
    <div style="background:#0d0d0d; border:1px solid #2a2a2a; border-radius:10px;
                padding:10px 14px; margin:0 0 10px 0; color:#EEE; font-size:13px;
                display:flex; gap:16px; flex-wrap:wrap; align-items:center;">
      <div style="font-weight:800; color:#00BFFF;">{label}</div>
      <div><span style="color:#AAA;">Games graded:</span> <b>{acc.get('games_graded',0)}</b></div>
      <div><span style="color:#AAA;">Winner acc:</span> <b>{fmt(acc.get('winner_acc'))}</b></div>
      <div><span style="color:#AAA;">Spread acc:</span> <b>{fmt(acc.get('spread_side_acc'))}</b></div>
      <div><span style="color:#AAA;">Margin MAE:</span> <b>{fmt(acc.get('margin_mae'), pct=False)}</b></div>
      <div><span style="color:#AAA;">Within 5:</span> <b>{fmt(acc.get('within_5'))}</b></div>
      <div><span style="color:#AAA;">ATS vs Vegas:</span> <b>{fmt(acc.get('ats_acc'))}</b>
        <span style="color:#555;">({acc.get('ats_games',0)} bets)</span></div>
    </div>"""

"""# ACCURACY"""

SEASON_ACC_CACHE_PATH = os.path.join(MODEL_DIR, "season_accuracy_by_week.json")

def _load_season_acc_cache() -> dict:
    if os.path.exists(SEASON_ACC_CACHE_PATH):
        try:
            with open(SEASON_ACC_CACHE_PATH, "r") as f:
                return json.load(f)
        except Exception:
            pass
    return {}


def _save_season_acc_cache(cache: dict):
    with open(SEASON_ACC_CACHE_PATH, "w") as f:
        json.dump(cache, f, indent=2, default=str)


def _safe_pct_mean(numer, denom):
    if denom == 0:
        return np.nan
    return float(numer) / float(denom)


def _week_key_from_date(d):
    ts = pd.Timestamp(d)
    iso = ts.isocalendar()
    return f"{int(iso.year)}-W{int(iso.week):02d}"


def _combine_accuracy_dicts(acc_list: list) -> dict:
    """
    Combines weekly cached accuracy stats into one season-to-date snapshot.
    """
    if not acc_list:
        return {}

    games_graded = 0

    winner_num = 0
    winner_den = 0

    spread_num = 0
    spread_den = 0

    within5_num = 0
    within5_den = 0

    ats_num = 0
    ats_den = 0

    mae_weighted_sum = 0.0
    mae_den = 0

    for a in acc_list:
        gg = int(a.get("games_graded", 0) or 0)
        games_graded += gg

        if a.get("winner_correct") is not None and a.get("winner_total") is not None:
            winner_num += int(a.get("winner_correct", 0) or 0)
            winner_den += int(a.get("winner_total", 0) or 0)

        if a.get("spread_correct") is not None and a.get("spread_total") is not None:
            spread_num += int(a.get("spread_correct", 0) or 0)
            spread_den += int(a.get("spread_total", 0) or 0)

        if a.get("within5_correct") is not None and a.get("within5_total") is not None:
            within5_num += int(a.get("within5_correct", 0) or 0)
            within5_den += int(a.get("within5_total", 0) or 0)

        if a.get("ats_correct") is not None and a.get("ats_total") is not None:
            ats_num += int(a.get("ats_correct", 0) or 0)
            ats_den += int(a.get("ats_total", 0) or 0)

        if a.get("margin_mae_sum") is not None and a.get("margin_mae_n") is not None:
            mae_weighted_sum += float(a.get("margin_mae_sum", 0.0) or 0.0)
            mae_den += int(a.get("margin_mae_n", 0) or 0)

    return {
        "games_graded": games_graded,
        "winner_acc": _safe_pct_mean(winner_num, winner_den),
        "spread_side_acc": _safe_pct_mean(spread_num, spread_den),
        "margin_mae": (mae_weighted_sum / mae_den) if mae_den > 0 else np.nan,
        "within_5": _safe_pct_mean(within5_num, within5_den),
        "ats_acc": _safe_pct_mean(ats_num, ats_den),
        "ats_games": ats_den,
    }


CONFIDENCE_BANDS = [
    ("50-60%", 0.50, 0.60),
    ("60-70%", 0.60, 0.70),
    ("70-80%", 0.70, 0.80),
    ("80-90%", 0.80, 0.90),
    ("90%+", 0.90, 1.01),
]


def _compute_confidence_band_detailed(board: pd.DataFrame) -> list:
    if board is None or len(board) == 0:
        return []

    g = board.copy()
    g["pick_conf_num"] = pd.to_numeric(g.get("pick_conf", g.get("confidence")), errors="coerce")
    g["home_score"] = pd.to_numeric(g.get("home_score"), errors="coerce")
    g["away_score"] = pd.to_numeric(g.get("away_score"), errors="coerce")
    g = g[_real_final_mask(g)].copy()
    g = g.dropna(subset=["pick_conf_num", "home_score", "away_score"])
    if len(g) == 0:
        return []

    g["actual_winner"] = np.where(
        g["home_score"] > g["away_score"],
        g["home_team"],
        np.where(g["away_score"] > g["home_score"], g["away_team"], "PUSH")
    )
    g["winner_correct"] = False
    if "winner_pick" in g.columns:
        non_push = g["actual_winner"].astype(str).ne("PUSH")
        g.loc[non_push, "winner_correct"] = (
            g.loc[non_push, "winner_pick"].map(canonical_team) ==
            g.loc[non_push, "actual_winner"].map(canonical_team)
        )

    g["ats_correct"] = np.nan
    if {"pred_margin_home", "rw_spread_home"}.issubset(g.columns):
        pm = pd.to_numeric(g["pred_margin_home"], errors="coerce")
        rw = pd.to_numeric(g["rw_spread_home"], errors="coerce")
        hma = g["home_score"] - g["away_score"]
        edge = pm + rw
        cover = hma + rw
        ats_valid = pm.notna() & rw.notna() & hma.notna() & edge.abs().ge(float(_get_ats_edge_threshold())) & cover.ne(0)
        g.loc[ats_valid, "ats_correct"] = np.where(
            edge[ats_valid] > 0,
            cover[ats_valid] > 0,
            cover[ats_valid] < 0,
        ).astype(float)

    out = []
    for label, lo, hi in CONFIDENCE_BANDS:
        if hi >= 1.0:
            band = g[g["pick_conf_num"] >= lo].copy()
        else:
            band = g[(g["pick_conf_num"] >= lo) & (g["pick_conf_num"] < hi)].copy()
        ats_vals = pd.to_numeric(band.get("ats_correct"), errors="coerce")
        out.append({
            "band": label,
            "games": int(len(band)),
            "avg_conf_sum": float(band["pick_conf_num"].sum()) if len(band) else 0.0,
            "avg_conf_n": int(len(band)),
            "winner_correct": int(pd.to_numeric(band.get("winner_correct"), errors="coerce").fillna(0).sum()) if len(band) else 0,
            "winner_total": int((band["actual_winner"].astype(str) != "PUSH").sum()) if len(band) else 0,
            "ats_correct": int(ats_vals.fillna(0).sum()) if ats_vals.notna().any() else 0,
            "ats_total": int(ats_vals.notna().sum()),
        })
    return out


def _combine_confidence_band_dicts(acc_list: list) -> list:
    order = [label for label, _, _ in CONFIDENCE_BANDS]
    bucketed = {
        label: {
            "band": label,
            "games": 0,
            "avg_conf_sum": 0.0,
            "avg_conf_n": 0,
            "winner_correct": 0,
            "winner_total": 0,
            "ats_correct": 0,
            "ats_total": 0,
        }
        for label in order
    }

    for entry in acc_list:
        for row in entry or []:
            label = str(row.get("band", ""))
            if label not in bucketed:
                continue
            dest = bucketed[label]
            for key in ["games", "avg_conf_n", "winner_correct", "winner_total", "ats_correct", "ats_total"]:
                dest[key] += int(row.get(key, 0) or 0)
            dest["avg_conf_sum"] += float(row.get("avg_conf_sum", 0.0) or 0.0)

    out = []
    for label in order:
        row = bucketed[label]
        out.append({
            "band": label,
            "games": int(row["games"]),
            "avg_conf": (float(row["avg_conf_sum"]) / float(row["avg_conf_n"])) if row["avg_conf_n"] > 0 else np.nan,
            "winner_acc": _safe_pct_mean(row["winner_correct"], row["winner_total"]),
            "ats_acc": _safe_pct_mean(row["ats_correct"], row["ats_total"]),
            "ats_games": int(row["ats_total"]),
        })
    return out


def compute_daily_accuracy_detailed(board: pd.DataFrame) -> dict:
    if board is None or len(board) == 0:
        return {
            "games_graded": 0,
            "winner_correct": 0, "winner_total": 0,
            "spread_correct": 0, "spread_total": 0,
            "margin_mae_sum": 0.0, "margin_mae_n": 0,
            "within5_correct": 0, "within5_total": 0,
            "ats_correct": 0, "ats_total": 0,
        }

    g = board.copy()
    g["final_score"] = g.get("final_score", "").astype(str)
    real_final_mask = _real_final_mask(g)
    g = g[real_final_mask & g["final_score"].str.strip().ne("")]
    if len(g) == 0:
        return {
            "games_graded": 0,
            "winner_correct": 0, "winner_total": 0,
            "spread_correct": 0, "spread_total": 0,
            "margin_mae_sum": 0.0, "margin_mae_n": 0,
            "within5_correct": 0, "within5_total": 0,
            "ats_correct": 0, "ats_total": 0,
        }

    def _extract_pts(s):
        nums = re.findall(r"(\d+)", str(s))
        return (float(nums[-2]), float(nums[-1])) if len(nums) >= 2 else (np.nan, np.nan)

    pts = g["final_score"].map(_extract_pts)
    g["away_pts"] = [p[0] for p in pts]
    g["home_pts"] = [p[1] for p in pts]
    g = g.dropna(subset=["away_pts", "home_pts"])

    if len(g) == 0:
        return {
            "games_graded": 0,
            "winner_correct": 0, "winner_total": 0,
            "spread_correct": 0, "spread_total": 0,
            "margin_mae_sum": 0.0, "margin_mae_n": 0,
            "within5_correct": 0, "within5_total": 0,
            "ats_correct": 0, "ats_total": 0,
        }

    g["home_margin_actual"] = g["home_pts"] - g["away_pts"]

    # winner
    g["actual_winner"] = np.where(
        g["home_pts"] > g["away_pts"], g["home_team"],
        np.where(g["away_pts"] > g["home_pts"], g["away_team"], "PUSH")
    )

    winner_correct = 0
    winner_total = 0
    if "winner_pick" in g.columns:
        w = g[g["actual_winner"] != "PUSH"].copy()
        if len(w):
            winner_correct = int((w["winner_pick"].map(canonical_team) == w["actual_winner"].map(canonical_team)).sum())
            winner_total = int(len(w))

    # true spread cover accuracy
    spread_correct = 0
    spread_total = 0
    margin_mae_sum = 0.0
    margin_mae_n = 0
    within5_correct = 0
    within5_total = 0

    if "pred_margin_home" in g.columns:
        pm = pd.to_numeric(g["pred_margin_home"], errors="coerce")
        am = pd.to_numeric(g["home_margin_actual"], errors="coerce")
        valid = pm.notna() & am.notna()

        if valid.any():
            pmv = pm[valid]
            amv = am[valid]

            spread_result = np.where(
                pmv > 0,
                amv > pmv,
                np.where(pmv < 0, amv < pmv, amv == 0)
            )

            spread_correct = int(np.sum(spread_result))
            spread_total = int(len(spread_result))

            err = (pmv - amv).abs()
            margin_mae_sum = float(err.sum())
            margin_mae_n = int(len(err))
            within5_correct = int((err <= 5).sum())
            within5_total = int(len(err))

    # ats vs vegas
    ats_correct = 0
    ats_total = 0
    ats_threshold = float(_get_ats_edge_threshold())
    vegas_spread_home = _get_home_vegas_spread(g)
    if vegas_spread_home.notna().any() and "pred_margin_home" in g.columns:
        rg = g.copy()
        rg["vegas_spread_home"] = vegas_spread_home
        rg["pred_margin_home"] = pd.to_numeric(rg["pred_margin_home"], errors="coerce")
        rg["home_margin_actual"] = pd.to_numeric(rg["home_margin_actual"], errors="coerce")
        rg = rg.dropna(subset=["vegas_spread_home", "pred_margin_home", "home_margin_actual"])

        if len(rg):
            rg["edge"] = rg["pred_margin_home"] + rg["vegas_spread_home"]
            rg = rg[rg["edge"].abs() >= ats_threshold].copy()
            rg["pick"] = np.where(rg["edge"] > 0, "HOME", np.where(rg["edge"] < 0, "AWAY", "NO_BET"))
            rg = rg[rg["pick"] != "NO_BET"]

            if len(rg):
                rg["cover_margin"] = rg["home_margin_actual"] + rg["vegas_spread_home"]
                pushes = rg["cover_margin"] == 0
                rg = rg[~pushes].copy()

                if len(rg):
                    ats_result = np.where(rg["pick"] == "HOME", rg["cover_margin"] > 0, rg["cover_margin"] < 0)
                    ats_correct = int(np.sum(ats_result))
                    ats_total = int(len(ats_result))

    return {
        "games_graded": int(len(g)),
        "winner_correct": winner_correct,
        "winner_total": winner_total,
        "spread_correct": spread_correct,
        "spread_total": spread_total,
        "margin_mae_sum": margin_mae_sum,
        "margin_mae_n": margin_mae_n,
        "within5_correct": within5_correct,
        "within5_total": within5_total,
        "ats_correct": ats_correct,
        "ats_total": ats_total,
    }


def build_or_update_season_accuracy_cache():
    """
    Updates weekly cached season accuracy.
    Rebuilds weeks when exact Rotowire odds files are now available so ATS stats stay current.
    """
    required_keys = {
        "games_graded",
        "winner_correct", "winner_total",
        "spread_correct", "spread_total",
        "margin_mae_sum", "margin_mae_n",
        "within5_correct", "within5_total",
        "ats_correct", "ats_total",
        "confidence_bands",
    }

    cache = _load_season_acc_cache()

    s = schedule_cur.copy()
    s["game_date_time"] = pd.to_datetime(s["game_date_time"], errors="coerce", utc=True)
    s["game_dt_et"] = s["game_date_time"].dt.tz_convert("America/New_York").dt.tz_localize(None)
    s = s.dropna(subset=["game_dt_et"]).copy()

    today_et = pd.Timestamp.now(tz="America/New_York").date()
    s = s[s["game_dt_et"].dt.date <= today_et].copy()

    all_dates = sorted(s["game_dt_et"].dt.date.unique())
    if not all_dates:
        return {}

    # group dates by ISO week
    weeks = {}
    for d in all_dates:
        wk = _week_key_from_date(d)
        weeks.setdefault(wk, []).append(d)

    updated = False
    week_items = list(weeks.items())
    total_weeks = len(week_items)

    for idx, (wk, dates_in_week) in enumerate(week_items, start=1):
        cached_wk = cache.get(wk, {})
        exact_rw_dates = int(sum(1 for d in dates_in_week if _has_exact_rotowire_file_for_date(d, ROTOWIRE_DIR)))
        cached_rw_dates = int(cached_wk.get("rw_exact_dates", -1) or 0)
        cached_ats_total = int(cached_wk.get("ats_total", 0) or 0)
        cached_games_graded = int(cached_wk.get("games_graded", 0) or 0)

        should_refresh = True
        if wk in cache and required_keys.issubset(set(cached_wk.keys())):
            should_refresh = False
            if exact_rw_dates > 0 and cached_games_graded > 0:
                if cached_rw_dates != exact_rw_dates or cached_ats_total == 0:
                    should_refresh = True

        if not should_refresh:
            continue

        progress_msg = f"Season accuracy cache: week {idx}/{total_weeks} ({wk})"
        if exact_rw_dates > 0:
            progress_msg += f" | exact RW dates: {exact_rw_dates}"
        print(progress_msg)
        with contextlib.suppress(Exception):
            _dashboard_log(
                "season_accuracy_cache",
                status="week_start",
                week=wk,
                week_index=int(idx),
                total_weeks=int(total_weeks),
                dates=len(dates_in_week),
                exact_rw_dates=exact_rw_dates,
                cached_ats_total=cached_ats_total,
                refresh_reason=(
                    "missing_or_incomplete_cache"
                    if not (wk in cache and required_keys.issubset(set(cached_wk.keys())))
                    else "rotowire_exact_dates_available"
                ),
            )

        boards = []
        for d in sorted(dates_in_week):
            try:
                b = build_board_for_date(
                    date_et=d,
                    schedule_df=schedule_cur,
                    team_snaps=team_snaps,
                    roll_cols=roll_cols,
                    spread_booster=spread_booster,
                    winner_booster=winner_booster,
                    lgb_spread=lgb_spread,
                    iso=iso,
                    imp=imp,
                    feature_cols=feature_cols,
                    spread_edge_booster=spread_edge_booster if "spread_edge_booster" in globals() else None,
                    lgb_spread_edge=lgb_spread_edge if "lgb_spread_edge" in globals() else None,
                    elo_snap=elo_snap,
                    verbose=False,
                )
                if b is not None and len(b) > 0:
                    b = _attach_rotowire_to_board(b, d)
                    boards.append(b)
            except Exception:
                continue

        if boards:
            week_board = pd.concat(boards, ignore_index=True)
            week_board = week_board.drop_duplicates(
                subset=[c for c in ["game_id", "away_team", "home_team", "game_dt_et"] if c in week_board.columns],
                keep="last"
            )
            cache[wk] = compute_daily_accuracy_detailed(week_board)
            cache[wk]["confidence_bands"] = _compute_confidence_band_detailed(week_board)
            cache[wk]["rw_exact_dates"] = exact_rw_dates
        else:
            cache[wk] = {
                "games_graded": 0,
                "winner_correct": 0, "winner_total": 0,
                "spread_correct": 0, "spread_total": 0,
                "margin_mae_sum": 0.0, "margin_mae_n": 0,
                "within5_correct": 0, "within5_total": 0,
                "ats_correct": 0, "ats_total": 0,
                "confidence_bands": [],
                "rw_exact_dates": exact_rw_dates,
            }

        updated = True
        done_msg = f"Season accuracy cache complete: week {idx}/{total_weeks} ({wk})"
        print(done_msg)
        with contextlib.suppress(Exception):
            _dashboard_log(
                "season_accuracy_cache",
                status="week_complete",
                week=wk,
                week_index=int(idx),
                total_weeks=int(total_weeks),
                games_graded=int(cache[wk].get("games_graded", 0) or 0),
                ats_total=int(cache[wk].get("ats_total", 0) or 0),
                exact_rw_dates=int(cache[wk].get("rw_exact_dates", 0) or 0),
            )

    if updated:
        _save_season_acc_cache(cache)

    return cache


def load_cached_season_accuracy_snapshot() -> dict:
    cache = _load_season_acc_cache()
    if not cache:
        return {}
    week_keys = sorted(cache.keys())
    acc_list = [cache[k] for k in week_keys]
    return _combine_accuracy_dicts(acc_list)


def load_cached_confidence_calibration_snapshot() -> list:
    cache = _load_season_acc_cache()
    if not cache:
        return []
    week_keys = sorted(cache.keys())
    acc_list = [cache.get(k, {}).get("confidence_bands", []) for k in week_keys]
    return _combine_confidence_band_dicts(acc_list)

